(168, NULL, 1, 1835, '78897b9ce16ca750295ade02980df2b9.pdf', NULL, 'Reportan equipo con fuga positiva', '2019-06-10 ', '4053', NULL, NULL, NULL, 'Nueva cubierta distal\r\nNuevo caucho protector\r\nNuevos pegantes.\r\nNuevo sellante\r\n7430 LUX\r\nNuevo canal de trabajo\r\n\r\nSe realizan reparaciones. Se realizó prueba de imagen, prueba final de fugas negativo. Se entrega al servicio en condiciones normales de funcionamiento.', '4301', '2019-08-20 ', 'no', '', 15, NULL),
(169, NULL, 1, 1833, '5dbe3187c3d1b4900628aff3b0be307a.pdf', NULL, 'Reportan equipo por interferencia en la imagen', '2019-08-06 ', 'SIN CÓDIGO', NULL, NULL, NULL, 'Se realiza procedimiento correctivo.\r\nSe instala:\r\nNuevo caucho protector, nuevos pegantes, cambio del Flex del conector eléctrico, ajuste de angulación y tensión de guayas. Se realiza prueba de imagen, angulación, fuga, succión e irrigación y se identifica equipo en optimas condiciones de funcionamiento ', 'retro 5479', '2019-11-26 ', 'no', '', 15, NULL),
