(171, NULL, 1, 907, '3f4ec7d6923cf3479119e6ee95354ef8.pdf', NULL, 'NO DEJA VISUALIZAR COMPLETAMENTE LA SEÑAL', '2019-08-16 00:00:00', '2376', '', '', '0000-00-00 00:00:00', 'EQUIPO CON ORDEN DE TRABAJO 2376, SE RESOLVIÓ REALIZANDO MANTENIMIENTO PREVENTIVO QUE ESTABA PENDIENTE CORRESPONDIENTE A REPORTE 57805. SE REPARA Y SE LIMPIA IMPRESORA QUE FORMABA ATASCO. PRUEBA DE FUNCIONAMIENTO, EQUIPO OK', '57805', '2019-08-23 00:00:00', 'no', '', 15, NULL),
