(192, NULL, 1, 1834, '74e4ad2ee16438f8e5efd1eff33368bd.pdf', NULL, 'Equipo presenta fuga positiva', '2019-01-10 ', 'SIN CÓDIGO', NULL, NULL, NULL, 'Se instala nuevo boton #1 y se realizan angulaciones y tensionan guayas.\r\nSe realiza prueba de fuga siendo negativa. se entrega equipo en optimas condiciones de funcionamiento en el servicio', '4046', '2019-06-05 ', 'no', '', 15, NULL),
(193, NULL, 1, 2121, '616cf454c79cc8371e715e41ca9bba4f.pdf', NULL, 'EQUIPO REPORTADO POR FUGA POSITIVA', '2019-05-30 00:00:00', 'NO REGISTRA', NULL, NULL, NULL, 'Se realiza diagnostico. Se identifica equipo desgastado y con multiples pliegues.\r\nEl equipo presenta desgaste critico del tubo angulador. El ingeniero de la empresa Admetec recomienda enviar el equipo a mantenimiento correctivo. Se recomienda cambio de tubo angulador completo, el cual contiene malla del tubo angulador, funda, guayas, canal de trabajo, tubo de inserción, caucho protector y pegantes.', '4015', '2019-05-30 00:00:00', 'no', '', 16, NULL),
(194, NULL, 1, 2122, 'ac68c088b0a0c1deee42a01331e2060a.pdf', NULL, '', ' ', '', NULL, NULL, NULL, 'Se realiza Rerparación segun orden de compra 87456.\r\nNueva cubierta distal.\r\nNuevo caucho protector.\r\nNuevos pegantes.\r\nNuevos sellantes distales.\r\nNueva fibra de imagen.\r\nNuevas fibras de luz.\r\nnuevo canal de trabajo.\r\nNuevo tubo angulador.\r\nNuevo tubo de inserción.\r\nAjuste de angulaciones.\r\nNuevas guayas.\r\nNuevas fundas de guayas.\r\n', '3169', '2018-07-10 ', 'no', '', 15, NULL),
(195, NULL, 1, 1833, 'b1a7bc7063c49ddc44668abd4fa50c67.pdf', NULL, 'no registra', '2018-10-10 ', 'SIN CÓDIGO', NULL, NULL, NULL, 'Se observa lente objetivo rallado. \r\nFibras de transmisión de luz 4240 LUX.\r\nfalta anillo de Tubo universal guia de luz.\r\nSe realiza reparación alternativa del conector eléctrico.\r\nNuevo flex de camara.\r\nAjuste de angulación.\r\nAjuste de tensión de guayas. Se realiza prueba de fugas y da negativa\r\n', '3492', '2018-10-10 ', 'no', '', 15, NULL),
(196, NULL, 1, 1833, 'b13173947da7181f8f09c8d231a39340.pdf', NULL, 'Equipo reportado por fuga positiva', '2019-07-24 ', 'SIN CÓDIGO', NULL, NULL, NULL, 'Se realiza mantenimeinto correctivo.\r\nLente objetivo rayado.\r\nNuevos sellantes, astillados en lentes guias de luz.\r\nFibras de transmision de luz al 90 % 5610 lux.\r\nSe realiza limpieza de pines del conector electrico.\r\nTapa lateral del cuerpo de control astillada.\r\nLimpieza de pines del conector electrico.\r\nSe realiza ajuste de angulación.\r\nSe realiza ajuste de tension.\r\nSe realiza prueba de fugas y da negativa.', '4228', '2019-07-26 ', 'no', '', 15, NULL),
(197, NULL, 1, 1833, 'eac154c40b0584eef02dc6237a2c64b7.pdf', NULL, 'no registra', '2018-05-16 ', 'SIN CÓDIGO', NULL, NULL, NULL, 'Se realiza mantenimiento correctivo de acuerdo a la orden de compra 87415.\r\nNuevo caucho protector.\r\nNuevos pegantes del caucho.\r\nNuevo sellante distal del lente objetivo.\r\nNuevo boton #1.\r\nReparación de malla del tubo angulador.\r\nAjuste de angulaciones.\r\nNuevo kit de empaques para los controles de angualción.\r\nTension de guayas del sistema de angulación\r\n', '3082', '2018-05-16 ', 'no', '', 15, NULL),
(1768, NULL, 1, 914, '7294498ce6397b6dfe72f0c972898878.pdf', NULL, 'NO SE ESCUCHA LA FETOCARDIA', '2021-05-24 ', '14150', NULL, NULL, NULL, 'EL TOCO FETO CARDIA SE ENCUENTRA MALO (CRISTALES DAÑADOS) SE REQUIERE CAMBIO DE TRANSDUCTOR DE FETO CARDIA', '59037', '2021-05-24 ', 'no', '', 15, 0),
(1769, NULL, 1, 805, 'a582e29d5cd57dc375fc7faa77725cee.pdf', NULL, 'SENSOR DE OXIMETRIA DAÑADO', '2021-05-24 ', '9608', NULL, NULL, NULL, 'SE REALIZA INSTALACION DE SENSOR SPO2 NUEVO, PREVIAMENTE DILIGENCIADA SALIDA DE ALMACEN', '9608', '2021-05-24 ', 'no', NULL, 15, NULL),
(199, NULL, 1, 1833, '5d7dbfd68a28f7cd9bf8afcc320814e3.pdf', NULL, 'no registra', '2019-01-17 ', 'SIN CÓDIGO', NULL, NULL, NULL, 'Se realiza mantenimiento correctivo.\r\nLa fecha de ejecución es del 17 de Enero del 2019, sin embargo la empresa entrega el equipo en mayo.\r\nFibras de transmision de luz al 90% 4230 Lux.\r\nNuevo flex CCD imagen EVIS.\r\n Ajuste de angulación.\r\nTension de guayas.\r\nSe realiza prueba de fugas la cual da negativa.\r\nSe realiza prueba de imagen y da ok', '3556', '2019-05-14 ', 'no', '', 15, NULL),
(200, NULL, 1, 1836, 'dbcae810aa999c0b02cf70a04ee7c4f0.pdf', NULL, 'Interferencia en la imagen', '2019-05-17 ', 'SIN CÓDIGO', NULL, NULL, NULL, 'Se realiza reparación según orden de compra 87931.\r\nSe realiza reparación alternativa en cubierta distal.\r\nNuevos pines del conector electrico.\r\nSe ajustan angulaciones.\r\nSe realiza tension de guayas', '4081', '2019-06-11 ', 'no', '', 15, NULL),
