(243, NULL, 1, 1847, 'a3a1a70350398f6138198d91c16d7768.pdf', NULL, '', '0000-00-00 00:00:00', '', NULL, NULL, NULL, 'Se realiza diagnostico, se identifica:\r\nTubo de insercion con hendiduras.\r\nNariz de irrigación obstruida.\r\nCanal de biopsia obstruido.\r\nIrrigación/Insuflacion obstruida.\r\nValvula de irrigación impactada.\r\nEl equipo debe ser retirado para realizar diagnsotico especializado y/o reparación', 'SIN CODIGO', '2017-10-26 00:00:00', 'no', '', 15, NULL),
(244, NULL, 1, 1847, 'd0eeae9acf0af6c6c8523783912652ce.pdf', NULL, '', '0000-00-00 00:00:00', '', NULL, NULL, NULL, 'Se realiza diagnostico\r\nSe identifica:\r\ntapa de punta distal rayada.\r\nTubo de inserción con hendiduras.\r\nIrrigación e insuflación obstruida.\r\nCilindro de succión desgastado.\r\nTubo principal con hendiduras.\r\nConector de luz rayado.\r\nValvula de irrigación desgastada.\r\nValvula de succión desgastada.\r\nEl equipo debe ser retirado para diagnostico especializado y/o reparación', 'SIN CODIGO', '2017-06-29 00:00:00', 'no', '', 15, NULL),
