(246, NULL, 1, 2000, 'f240c896ad751e70a8b43558be3c0e3e.pdf', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'No se reconoce cabezal de camara.\r\nSe presenta error luego de conectar memoeria usb.\r\nSe verifica equipo con diferentes cabezales obteniendo en todos un codigo de barra de colores.\r\nSe realiza cotizacion de tarjeta de conexion de entrada de cabezal y tarjeta principal de reconocimiento de video cabezal\r\n', '9794', '2017-06-22 00:00:00', 'no', NULL, NULL, NULL),
(247, NULL, 1, 1849, 'add1b7266b578b892e03ef44f4890cb0.pdf', NULL, '', '0000-00-00 00:00:00', '', NULL, NULL, NULL, 'Se realiza diagnostico, se identifica:\r\nGoma de angulación perforada.\r\nTubo principal con hendiduras.\r\nConector de luz rayado.\r\nValvula de irrigación ausente e impacatada.\r\nValvula de succión ausente e impacatada.\r\n Se necesita cotizar valvulas', 'SIN CODIGO', '2017-06-24 00:00:00', 'no', 'VALVULAS', 15, NULL),
