(495, NULL, 1, 179, '1822f5fc064a783e063d5f0622d744f6.pdf', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SE REVISAN TECLAS, FUNCIONAN CORRECTAMENTE, EXCEPTO LAS QUE QUEDAN DEBAJO DE LA PANTALLA PERO ESTAS NO AFECTAN EL FUNCIONAMIENTO DEL EQUIPO. PARA LA TOMA DE EKG DESDE LAS PADLES HAY QUE SELECCIONAR OPCION 5 CABL EIE. EQUIPO FUNCIONA CORRECTAMENTE', '16044', '2019-10-03 00:00:00', 'no', NULL, NULL, NULL),
