(686, NULL, 1, 1797, '6154660f686fa5421db03c3b7d198241.pdf', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Se realiza instalación de motor Motor High/Low de pies, el cual había sido solicitado de la ultima visita de mantenimiento preventivo del 27 de noviembre.\r\nNumero de repuesto instalado: HM-17-304', 'SO39312-13', '2019-12-26 00:00:00', 'no', NULL, NULL, NULL),
(687, NULL, 1, 2645, '4b9e4fc870365dd0a32db15128e0f0c8.pdf', NULL, '', '0000-00-00 00:00:00', '', NULL, NULL, NULL, 'Se realiza diagnostico de la cama por lo cual se realiza intercambio del control box de una cama que no esta con paciente, se intercambia con esta cama y se detecta que la cama persiste con asincronia.\r\nPor lo cual se realiza revisión de los motores y se evidencia que el motor de los pies presenta asincronia y este había sido cambiado el 19 de septiembre 2019 ', 'SO39312-15', '2019-12-26 00:00:00', 'no', '', 15, NULL),
(688, NULL, 1, 2645, '9f3b1124cf3201f4a3cf749835e5840e.pdf', NULL, '', '0000-00-00 00:00:00', '', NULL, NULL, NULL, 'SE REALIZA INSTLACION DE MOTOR HIGH/LOW  DE LOS PIES DESTINADO A OTRA CAMA AVERIADA PARA SACAR EQUIPO A FUNCIONAMIENTO.\r\nESPERA DE LLEGAR EL REPUESTO PARA INSTALAR EN LA SERIE CORRECTA', '0449', '2019-12-27 00:00:00', 'no', '', 15, NULL),
(689, NULL, 1, 677, '5ab5958e4e80de772e05ef8d5704b144.pdf', NULL, '', '0000-00-00 00:00:00', '', '', '', '0000-00-00 00:00:00', 'SE REALIZA AJUSTE DE BATERIAS, NO ESTABAN HACIENDO BUEN CONTACTO, SE REALIZAN PRUEBAS CON EL EQUIPO DESCONECTADO DE LA RED Y RESPONDE CORRECTAMENTE,', '16236', '2019-12-30 00:00:00', 'no', '', 15, NULL),
(690, NULL, 1, 1795, '4850788fa8f5936c71844881805b3ace.pdf', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SE REALIZA INSTALACION DE MOTOR HIGH/LOW DE LOS PIES EL CUAL SE ENCONTRABA AVERIADO CON RUIDO ANORMAL.\r\nVERIFICACION DEL EQUIPO. PRUEBA DE FUNCIONAMIENTO, SE DEJA EQUIPO CARGANDO', 'S039312-14', '2019-12-26 00:00:00', 'no', NULL, NULL, NULL),
(691, NULL, 1, 984, '397e3ed2d1918024f28b4e97d1f151fa.pdf', NULL, '\"PIEZA DE CABEZAL DE ULTRASONIDO DAÑADA\"', '2019-07-12 00:00:00', '6620', NULL, NULL, NULL, 'EL APLICADOR DE ULTRASONIDO PRESENTA FALLA EN EL CABEZAL. SE INSPECCIONA ACCESORIO Y SE DETECTA QUE NO CUENTA CON LA AGUJA EMISOR DE ULTRASONIDO. SE SOLICITA AL AREA DE COMPRAS DE SYSMED LA COTIZACION DE LA AGUJA DEL CABEZAL REF 5CM.', '16398', '2019-12-10 00:00:00', 'no', 'AGUJA EMISOR DE ULTRASONIDO 5CM', 15, NULL),
(692, NULL, 1, 1777, 'c8cc7b02057bf03eef77977c1e09802c.pdf', NULL, 'QUINTA RUEDA NO SE ACCIONA.\r\nSE REALIZA VERIFICACION DE 5TA RUEDA QUE SE HABIA REPORTADO NO ACCIONADO. LE HACE FALTA TORNILLO/PIN DEL SISTEMA. NO. PARTES\r\n-HM-12-004 E8 PERFORATED PIN (1).\r\n- YM-HM-02-026 PLASTIC WASHER(2).\r\nHM-11-35 RUE DIP(1).', '2019-07-31 00:00:00', '0424', NULL, NULL, NULL, 'Se instala PIN de quinta rueda.', 'SO45535', '2020-10-15 00:00:00', 'no', '', 15, NULL),
(693, NULL, 1, 2654, '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ESPALDAR NO SUBE.\r\nSE REALIZA REVISIÓN DEL EQUIPO, SE ENCUENTRAN GUAYAS DE ACTUADOR FOWLER MAL POSICIONADAS. SE REALIZA AJUSTE Y SE ENCUENTRA MOTOR FUNCIONAL.\r\nDURANTE REVISIÓN SE EVIDENCIA LA PRESENCIA DE LIQUIDOS/ACIDOS DENTRO DE MEMBRANAS DE BARANDA POR MALOS PROCESOS DE LIMPIEZA LO CUAL EMPIEZA A AFECTAR OTROS COMPONENTES DE LAS BARANDA Y EL CHASIS DE LA CAMA POR COMIENZOS DE OXIDACIÓN', '16033', '2019-11-13 00:00:00', 'no', NULL, NULL, NULL),
(694, NULL, 1, 2625, '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'NO HAY TESTIGOS ENCENDIDOS, COMO SI ESTUBIERA DESCONECTADA.\r\nSE REALIZA VERIFICACION DEL EQUIPO. PRUEBA DE TOMA CORRIENTE, CABLE AC Y SUMINISTRO A CONTROL BOX, SE EVIDENCIA QUE ESTE ULTIMO ESTA AVERIADO Y NECESITA CAMBIO.\r\nSE PRUEBAN CONTROLES DE BARANDA. NO HAY EVIDENCIA DE HUMEDAD.\r\nDAÑO PUEDE DEBERSE A FALLA ELECTRICA, EN LA ULTIMA REVISION DEL EQUIPO EL 18/10/2019. DONDE SE ECNONTRABA FUNCIONANDO', '16011', '2019-10-24 00:00:00', 'no', NULL, NULL, NULL),
(695, NULL, 1, 2625, '1c9ae4bf4058164a1fe4dffa6829a9aa.pdf', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'CONTROL DE BARANDA IZQUIERDO NO FUNCIONABA LA NOCHE ANTERIOR.\r\nSE REALIZA INSPECCION DEL EQUIPO, SE REVISAN MEMBRANAS, Y SE EVIDENCIA GRANDES SIGNOS DE SANGRE/FLUIDOS. SE PRUEBA CONTROL Y SE ENCUENTRA FUNCIONAL POR LE MOMENTO.\r\nFALLO SE DEBE A LA PRESENCIA DE HUMEDAD DENTRO DEL CONTROL POR MALOS PROCESOS DE LIMPIEZA Y DESINFECCION', '15296', '2019-10-18 00:00:00', 'no', NULL, NULL, NULL),
(696, NULL, 1, 2616, 'de3039533d039313c323a9750dcf3567.pdf', NULL, 'CAMA BLOQUEADA.\r\nSE REALIZA REVISION DEL EQUIPO. SE ENCUENTRA PANEL CON BARANDA IZQUIERDA AVERIADA, PRESENTA UN BOTON SIN FUNCIONAMIENTO Y BLOQUEA EL EQUIPO. NO HAY EVIDENCIA DE HUMEDAD NI LIQUIDOS.\r\nDURANTE REVISION SE ENCUENTRA MOTORHIGH/LOW DE LOS PIES CON SONIDO IRREGULAR (HM-17-304). SE RECOMIENDA CAMBIO. NO HAY DAÑO APARENTE Y SE DESCONOCE LA CAUSA DEL SONIDO', '2019-11-05 00:00:00', '16017', NULL, NULL, NULL, 'Instalacion Motor\r\nSe realiza instalacion motot high / low de los pies que presentaba sonido irregular (HM-17-304) de los pies.', '18082', '2020-02-11 00:00:00', 'no', '', 15, NULL),
(697, NULL, 1, 269, '2cf2c27e75895af46cd3a86b95b2532b.pdf', NULL, '', '0000-00-00 00:00:00', '', NULL, NULL, NULL, 'SEGUN ORDEN DE TRABAJO 5587 \"EKG GRANDE NO IMPRIME\". SE REALIZA REVISION DEL EQUIPO CON SIMULADOR Y RESPONDE CORRECTAMENTE. EQUIPO OK', '16815', '2020-01-08 00:00:00', 'no', '', 15, NULL),
(698, NULL, 1, 593, '5b89710f304a75f9aade29ff3a25bd8f.pdf', NULL, '', '0000-00-00 00:00:00', '', NULL, NULL, NULL, 'SE ENCUENTRA SENSOR SPO2 DEFECTUOSO, SE INSTALA SENSOR NUEVO ENTREGADO POR EL CLIENTE. SE REALIZAN PRUEBAS CON BUENOS RESULTADOS', '16816', '2020-01-08 00:00:00', 'no', '', 15, NULL),
(699, NULL, 1, 1878, '5176b141c1cec4d8417d7cb4a4d08216.pdf', NULL, '', '0000-00-00 00:00:00', '', NULL, NULL, NULL, 'CONTROL DE BARANDA NO FUNCIONA. \r\nSE REALIZA INSPECCION DEL EQUIPOY SE VERIFICA CONTROL DE BARANDA. SE ENCEUNTRA EL CABLE DESCONECTADO Y SE PRUEBA. MOVIMEINTOS OK, LOS DEMAS CONTROLES OK.', '15258', '2019-10-02 00:00:00', 'no', '', 15, NULL),
(700, NULL, 1, 1785, '0f6817076b92319ec22ad37edcd4f1cd.pdf', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'BATERIA NO CARGA.\r\nSE REALIZA SEGUIMIENTO DE BATERIA DE EQUIPO, EL CUAL SE HABIA PRESENCIADO DURANTE PREVENTIVO QUE NO CARGABA. DURANTE TIEMPO DE SEGUIMIENTO BATERIA NO CARGO Y SE ENCEUNTRA COMPLETAMENTE DESCARGADA. SE DEBERIA CAMBIAR POR DAÑO.\r\n\r\nEQUIPO FUNCIONAL CONECTADO A TOMA CORRIENTE. \r\nEL 18/10/2019 SE REALIZA CAMBIO DE BATERIA LA CUAL SE ENCONTRABA AVERIADA. SE INSTALA NUEVA, SE REALIZAN PRUEBAS Y SE DEJA CARGANDO.\r\nEQUIPO SE ENCUENTRA ACTUALEMENTE FUNCIONAL Y EN USO', '15257/15294', '2019-10-18 00:00:00', 'no', NULL, NULL, NULL),
(701, NULL, 1, 1913, 'a70f78293a9eceb1a49c11ccdb5860fd.pdf', NULL, '', '0000-00-00 00:00:00', '', NULL, NULL, NULL, 'SEGÚN ORDEN DE TRABAJO 5654 \"VENTILADOR NO ENTREGA LOS VOLÚMENES ASIGNADOS Y PRESENTA FUGA\" SE REALIZA INSTALACION DE KIT DE MANTENIMIENTO DE 1 AÑO, SE REALIZAN PRUEBAS DE FUNCIONAMIENTO CON EQUIPO PATRON. SE RECOMIENDA CAMBIO DE CELDA DE OXIGENO QUE QUEDA PENDIENTE', '5654', '2020-01-07 00:00:00', 'no', '', 15, NULL),
(733, NULL, 1, 185, '417ec2d4933ee53cfa62552b102d3418.pdf', NULL, '', '2020-01-14 ', 'Sin código', NULL, NULL, NULL, 'EQUIPO QUE AL REALIZAR PRUEBAS CON PALAS NO EJECUTA DESCARGA. SE VERIFICA CONEXIÓN INTERNA DE SOPORTE DE PALAS CORRIGIENDO CONEXIONES. SE EFECTUAN PRUEBAS FUNCIONALES Y AUTOTEST CON BUENOS RESULTADOS. EQUIPO OK. SE RECOMIENDA ADQUIRIR RESISTENCIA DE 50 OHMIOS PARA REALIZAR AUTOTEST SATISFACTORIO.', '16240', '2020-01-14 ', 'no', '', 15, NULL),
(703, NULL, 1, 2626, '1f21c34a632c88b7ceb2a49ecc7c780e.pdf', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'BARANDA NO AJUSTA Y SE BAJA SOLA.\r\n\r\nSE REALIZA DESMONTE DE BARANDA SUPERIOR IZQUIERDA, SE LIMPIAN PIEZAS Y SE AJUSTA RESORTE DEL PASADOR DE LIBERACION. SE COMPRUEBA CORRECTO FUNCIONAMIENTO Y SONIDO CLICK DEL SEGURO.\r\n\r\nSE INSPECCIONA LA CAMA Y SUS MOVIMIENTOS. SE EVIDENCIA SONIDO IRREGULAR EN EL MOTOR HIGH/LOW DE LOS PIES. SE RECOMIENDA CAMBIO.\r\nA ESPERA DE CONFIRMACIÓN DE GARANTIA POR EL DISTRIBUIDOR. SE DESCONOCE CAUSA DEL SONIDO.', '14379', '2019-09-05 00:00:00', 'no', NULL, NULL, NULL),
(704, NULL, 1, 2626, '3da625503314486a7c94cd050ccb1a15.pdf', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'MOTOR HIGH/LOW PIES CON RUIDO.\r\nSE REALIZA VERIFICACION DEL EQUIPO. SE REALIZA CAMBIO DE MOTOR HIGH/LOW DE LOS PIES EL CUAL PRESENTA RUIDO IRREGULAR AL MOMENTO DE ELEVAR LA CAMA. SE REALIZAN PRUEBAS DE FUNCIONAMIENTO, EQUIPO FUNCIONAL SIN NOVEDAD', '15295', '2019-10-18 00:00:00', 'no', NULL, NULL, NULL),
(705, NULL, 1, 2633, '06e7b88b21cf2989b60bdcce109dfcf1.pdf', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'CONTROL BOX AVERIADO, CABECERA NO SUBIA COMPLETO.\r\n\r\nSE REALIZA CAMBIO DE CONTROL BOX EL CUAL SE ENCONTRABA AVERADO.\r\nSER COMPRUEBAN MOVIMEITNOS Y CONTROLES DE BARANDA.\r\nEQUIPO EN CORRECTO ESTADO FUNCIONAL.\r\nSE DEJA CARGANDO.\r\n', '14378', '2019-09-05 00:00:00', 'no', NULL, NULL, NULL),
(706, NULL, 1, 2633, '9a795cceda5099b60dcf2798b24deaf8.pdf', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'CABEZOTE NO SUBE.\r\nSE PRUEBA SUMINISTRO DE ENERGIA DEL EQUIPO, TESTIGOS NO ENCIENDEN, CABLE AC EN BUEN ESTADO FISICO Y FUNCIONAL.\r\nCAMA BLOQUEADA Y DESCARGADA.\r\nCONTROL BOX AVERIADO. SE DEBE CAMBIAR.\r\nNOTA. SE DEBERIA PROBAR MOTRO DEL CABEZAL UNA VEZ SE CAMBIE EL CONTROL BOX. DE MOMENTO NO SE PUEDEN EJECUTAR MAS PRUEBAS', '14374', '2019-09-02 00:00:00', 'no', NULL, NULL, NULL),
(707, NULL, 1, 2632, '6a658bd37071d03f6481b9b7157982a2.pdf', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'NO FUNCIONA PARTE ELECTRICA.\r\n\r\nSE REALIZA INSPECCIÓN DEL CABLE DE PODER.\r\nSE VERIFICAN MÓDULOS DE BARANDAS PERO NO FUNCIONAN.\r\nSE DEBE CAMBIAR CONTROL BOX.\r\nLA CAMA QUEDA FUERA DE SERVICIO\r\n\r\nCAMA BLOQUEADA.\r\nSE REALIZA CAMBIO DE CONTROL BOX AVERIADO.\r\nSE COMPRUEBAN MOVIEMIENTOS Y SE DEJA EQUIPO CARGANDO.\r\nSE VERIFICAN BARANDAS Y CONTROL IZQUIERDO PRESENTA MUCHA HUMEDAD Y REMANENTES DE SANGRE. SE LIMPIA Y SE LE DA LA RECOMENDACIÓN DE CUIDADO', '14339', '2019-08-16 00:00:00', 'no', NULL, NULL, NULL),
(708, NULL, 1, 2650, '3858c9ffcae86dac7222e94d3bf23161.pdf', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'LA CAMA NO FUNCIONA CORRECTAMENTE.\r\nSE REALIZA VISITA PARA PRESTAR EL SERVICIO. SIN EMBARGO NO SE PUEDE RALIZAR POR PACIENTE AISLADO', '0853', '2019-06-19 00:00:00', 'no', NULL, NULL, NULL),
(709, NULL, 1, 2650, '855d70daba9836c3763a306882930716.pdf', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'BARANDA DE PIECERO NO BAJA/ SE QUEDA RIGIDA.\r\nSE REALIZA VERIFICACIÓN DEL EQUIPO, SE DESTAPA COMPONENTE Y SE COMPRUEBA RESORTE DE BARANDA MAL UBICADO, SE REALIZA AJUSTE Y SE DEJA EQUIPO FUNCIONAL.\r\nSE RECOMIENDA CONECTAR EL EQUIPO EN TOMA REGULADO', '0423', '2019-07-31 00:00:00', 'no', NULL, NULL, NULL),
(710, NULL, 1, 2645, 'cf01d1c6c5b75767a7ad5c29dd277ecd.pdf', NULL, '', '0000-00-00 00:00:00', '', NULL, NULL, NULL, 'RUIDO EN MOTOR HIGH/LOW DE PIES.\r\nSE REALIZA CAMBIO/INSTALACION DE MOTOR HIGH/LOW DE LOS PIES EL CUAL SE REPORTO POR DAÑO.\r\n\r\nSE REALIZA VERIFICACIÓN DE MOVIMIENTOS Y SE ENCUENTRA EQUIPO COMPLETAMENTE FUNCIONAL.\r\n\r\nSE EVIDENCIA RASTROS DE FLUIDOS EN EL EQUIPO, EVIDENCIA DE INADECUADOS PROCESOS DE LIMPIEZA Y DESINFECCION.\r\n\r\nPENDIENTE SUBSANAR RUIDO DE QUINTA RUEDA, ESPERA DE REPUESTOS.', '16204', '2019-09-19 00:00:00', 'no', '', 15, NULL),
(711, NULL, 1, 2645, '', NULL, '', '0000-00-00 00:00:00', '', NULL, NULL, NULL, 'RUIDO DURANTE TRANSPORTE.\r\nSE REALIZA DESMONTE DE QUINTA RUEDA, SE INSTALA LA DE OTRO EQUIPO Y SE PRUEBA.\r\n5TA RUEDA APARENTEMENTE DAÑADA, SE INSTALA EN EL DE PRUEBA Y SE COMPRUEBA O EVIDENCIA EL MISMO RUIDO. SE REALIZAN PRUEBAS CON Y SIN 5TA RUEDA, SE SUGIERE EL CAMBIO, SE DESCONOCE EL RUIDO O DAÑO, NO HAY EVIDENCIA DE COMPONENTES ROTOS O DAÑADOS.\r\nSE INSPECCIONA EQUIPO Y SE ENCUENTRA ADICIONALMENTE RUIDO EN MOTRO HIGH/LOW DE LOS PIES DURANTE ELEVACION DE CAMA, SE DESCONOCE CAUSA Y SE SUGIERE CAMBIO', '14383', '2019-09-06 00:00:00', 'no', '', 15, NULL),
(712, NULL, 1, 2645, '095dc32b44876de7b06cb322c125a813.pdf', NULL, '', '0000-00-00 00:00:00', '', NULL, NULL, NULL, 'RUIDO DURANTE TRANSPORTE.\r\nSE REALIZA VERIFICACION DE EQUIPO NO ENCONTRANDOSE FALLA O RUIDO REPORTADO.\r\nSE DEJA EN SEGUIMIENTO SI VUELVE A PRESENTAR RUIDO\r\n', '0422', '2019-07-31 00:00:00', 'no', '', 15, NULL),
(713, NULL, 1, 2645, '15c1005097610b1cfc928eb68b4e76be.pdf', NULL, '', '0000-00-00 00:00:00', '', NULL, NULL, NULL, 'INSTALACION 5TA RUEDA.\r\nSE REALIZA INSTALCION DE QUINTA RUEDA LA CUAL PRESENTA RUIDO DURANTE TRANSPORTE.\r\nSE REALIZA PRUEBA Y TRANSPORTE DEL EQUIPO NO NOTANDO MAS RUIDO O NOVEDADES.\r\nEQUIPO SE  ENCEUNTRA OPERATIVO', '18102', '2020-01-13 00:00:00', 'no', '', 15, NULL),
