(721, NULL, 1, 656, '8a30e9300534bafe15495a26ff5dcea7.pdf', NULL, '', '0000-00-00 00:00:00', '', NULL, NULL, NULL, 'SEGUN ORDEN DE TRABAJO REPORTADA EL 3 DE DICIEMBRE 6579 \"PANTALLA CON FRANJAS DE COLORES, DISPLAY DAÑADO\"\r\nEL 31 DE DICIEMBRE DE 2019 SE DESARMA EQUIPO INTERNAMENTE, SE CORRIGEN CONEXIONES INTERNAS, EFECTUAN LIMPIEZA Y LUBRICACION, PRUEBAS FUNCIONALES CON BUENOS RESULTADOS. EQUIPO OK', '16801', '2019-12-31 00:00:00', 'no', '', 15, NULL),
