(724, NULL, 1, 1972, '90efaf59539caba2190f09e2ea3aea3a.pdf', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SE EVIDENCIA UN AMPLIO RANGO DE ERROR EN LA MEDICION POR LO QUE SE REALIZA EL RESPECTIVO AJUSTE. SE REALZA VERIFICACIÓN FINAL Y EQUIPO PASA PRUEBAS. SE LE REALIZA ADEMAS LIMPIEZA INTEGRAL INTERNA Y EXTERNA. SE REALIZAN MEDICIONES CON LAS MASAS PATRON. EL EQUIPO SE ENTREGA EN CONDCIIONES FISICAS Y FUNCIONALES OK', '16242', '2020-01-14 00:00:00', 'no', NULL, NULL, NULL),
