(731, NULL, 1, 1996, '189f236350f7bff727dd75cab00b0b05.pdf', NULL, 'Lampara cielitica no enciende', '2020-01-13 00:00:00', '5664', NULL, NULL, NULL, 'SEGÚN ORDEN DE TRABAJO \"NO ENCIENDE, SE CAMBIO BOMBILLO Y SE AJUSTA PORTABOMBILLOS\". BOMBILLA FUNDIDA, SE CAMBIA Y SE REALIZA LIMPIEZA DE CONEXIONES DEL PLUG Y PUNTOS DE SOLDADURA EN TERMINALES, SE PRUEBA Y SE DEJA FUNCIONANDO CORRECTAMENTE', '16448', '2020-01-13 00:00:00', 'no', '', 15, NULL),
(732, NULL, 1, 466, '4a6fa7fe0ed05a447697647f34f7c790.pdf', NULL, '', '0000-00-00 00:00:00', '', NULL, NULL, NULL, 'EQUIPO REQUIERE KIT DE MANTENIMIENTO PUESTO QUE EN REVISION DE FUGAS NO SUPERA PRUEBAS Y NO ES POSIBLE CORREGIR FALLA. TIENE UNA SEGÚNDA ORDEN DEL 10 DE ENERO DE 2029 SEGÚN ORDEN DE TRABAJO 5663 \"MAQUINA PRESENTA FUGA NO DETECTABLE\". SE REALIZA INSTALACION DE KIT DE MANTENIMIENTO DE 1 AÑO, SE REALIZAN PRUEBAS DE FUNCIONAMIENTO CON EQUIPO PATRON. SE RECOMIENDA CAMBIO DE CELDA DE OXIGENO QUE QUEDA PENDIENTE', '16819', '2020-01-15 00:00:00', 'no', '', 15, NULL),
