(735, NULL, 1, 1845, '38194ba610bb34859344c3a7b37a0d85.pdf', NULL, 'EL EQUIPO SALE POR FUGA POSITIVA EN EL BOTON MM', '2020-01-20 00:00:00', '4546', 'Se realiza prueba de fugas con resultado positivo en conector de luz, botón\r\nMM y en cono de conector de luz. Los elementos mencionados anteriormente no han sido\r\ncambiados desde la entrega del equipo nuevo en junio del 2013.\r\nAdemás se evidencia:\r\nImagen de la videocámara con mancha en zona inferior izquierda y destellos leve.\r\n\r\n\r\nSe pueden presentar casos como: Manchas, empañamiento, rayas, círculo negro,\r\ninterferencia y/o corto circuito. \r\n', 'DX280120-07', '2020-01-30 00:00:00', 'EQUIPO RETORNA SIN REALIZAR AJUSTES NI MANTENIMIENTO CORRECTIVO PORQUE NO SE APROBO LA REPARACIÓN', 'RT190620-01 OT 308', '2020-06-19 11:00:00', 'no', '', 16, NULL),
(824, NULL, 1, 1846, '752f724e990e39f1edbe55b50a0ca74f.pdf', NULL, 'EL EQUIPO SE REPORTA EN EL SERVICIO POR FUGA POSITIVA', '2020-03-03 00:00:00', '8651', '', '', '0000-00-00 00:00:00', 'EQUIPO PERMANECE FUERA DE SERVICIO, SE TOMA LA DESICION DE NO EFECTUAR LA REPARACION POR LOS DAÑOS PREVIOS QUE HA PRESENTADO EL EQUIPO, QUEDA PEDNEITNE REALIZAR EL RESPECTIVO PROCESO DE BAJA DEL MISMO', 'NO REGISTRA', '2020-06-12 00:00:00', 'no', '', 16, NULL),
(825, NULL, 1, 1835, NULL, NULL, 'EL EQUIPO SALE DE SERVICIO POR GUAYAS SUELTAS', '2020-01-10 ', '8656', '', '', '0000-00-00 00:00:00', 'Se decide iniciar el procedimiento de disposición final del equipo considerando la obsolescencia del mismo, la vida útil ampliamente superada y que en mayo del presente año fue entregado en el servicio un equipo nuevo que suple la necesidad del servicio', 'SIN CODIGO', '2020-06-12 ', 'no', '', 16, NULL),
(826, NULL, 1, 6, '1185a7556bb9feb4b794e20c941006cb.pdf', NULL, 'EL AGITADOR NO FUNCIONA, SE VE LA BANDA REVENTADA', '2019-07-18 ', 'NO REGISTRA', '', '', '0000-00-00 00:00:00', 'SE REALIZA CAMBIO DE BANDA Y EL EQUIPO FUNCIONA CORRECTAMENTE', '15816', '2019-07-18 ', 'no', '', 15, NULL),
(827, NULL, 1, 6, 'a68782e43778091179b53eb1985dc3b3.pdf', NULL, 'SE SOLICITAARREGLO DEL AGITADOR, SIN MAS ESPECIFICACIONES', '2019-09-02 ', '2529', 'EQUIPO PRESENTA DAÑO EN CABLE ACPOR QUEMADURADEBIDO A DERRAMAMIENTO DE ALCOHOL', '16051', '0000-00-00 00:00:00', 'SE REALIZA CAMBIO DE CABLE AC DESDE CONEXION INTERNA Y SE REALIZAN PRUEBAS FUNCIONALES. EQUIPO FUNCIONA CORRECTAMENTE', '16051', '2019-09-02 ', 'no', '', 15, NULL),
(828, NULL, 1, 272, '542050a50258da77014fdeb4c2a543b9.pdf', NULL, 'FALLA EN LA LECTURA  DE DERIVADA PRECORDIAL V5 Y V6', '2019-01-15 ', 'NO REGISTRA', '', '', '0000-00-00 00:00:00', 'SE REALIZAN PRUEBAS CON PROSIM Y EQUIPO ES FUNCIONANDO OK.\r\nSE RECOMIENDA VERIFICACION DE POSTURA DE ELECTRODOS CON EL JEFE DEL AREA', '14607', '2019-01-15 ', 'no', '', 15, 0),
(829, NULL, 1, 283, '15a5bc3f0eeb5b5405796cd1f9a45790.pdf', NULL, 'NO FUNCIONA ADECUADAMENTE, RUEDA SUELTA', '2019-02-19 ', 'NO REGISTRA', '', '', '0000-00-00 00:00:00', 'SE REALIZA AJUSTE DE PEDAL Y BUJE DE RUEDA DE ROTACION. EQUIPO QUEDA OK.\r\nSE RECOMIEDNA CAMBIO DE EQUIPO, POR FALLA DEBIDO A DESGASTE EN BUJE DE TORQUE PARA ROTACIÓN. YA QUE EL TORNILLO DE SUJECION PUEDE SOLTARSE Y HACER CAER AL PACIENTE', '14640', '2019-02-19 ', 'no', '', 15, 0),
(830, NULL, 1, 283, 'e7e901510064c3c18751382077fd967b.pdf', NULL, 'EJE SUELTO', '2019-02-27 ', 'NO REGISTRA', '', '', '0000-00-00 00:00:00', 'SE RETIRAN CRUCETAS DE ROTACION QUE VAN SUJETAS A LAS BIELAS Y PLATO PRINCIPAL PARA SU CORRECCION EN TORNO. REQUIERE LA FABRICACION DE CUADRANTE QUE PRESETNA DESGASTE', '14184', '2019-02-27 ', 'no', '', 15, 0),
(736, NULL, 1, 1848, '54746dcb29a691cf26d550bb5f0de0e6.pdf', NULL, 'EL EQUIPO SE HA OBSTRUIDO EN REPETIDAS OCASIONES Y PESE A QUE SE REVISA Y QUEDA FUNCIONANDO LA SUCCION E INSUFLACION, CONSTANTEMENTE VUELVE A OBSTRUIRSE. SE LE DA SALIDA PARA DIAGNOSTICO EN LABORATORIO', '2020-01-30 ', '4545', 'Se realiza prueba de fugas con resultado positivo en conector de luz, botón\r\nMM y en cono de conector de luz. Los elementos mencionados anteriormente no han sido\r\ncambiados desde la entrega del equipo nuevo en junio del 2013.', 'DX280120-07', '2020-01-30 00:00:00', 'Equipo retorna a la institución en condiciones no operativas dada que no fue aprobada la reparación por el alto coste de la misma en comparación con el costo de adquisición. Se debe proceder con el respectivo proceso de disposición final', 'rt230620-25 O 309', '2020-06-23 ', 'no', '', 16, NULL),
