(893, NULL, 1, 2944, 'c349c83ea991eb026e12d538507a5e8e.pdf', NULL, 'Se reporta problemas de movimientos de la mesa.', '2020-02-18 00:00:00', '', 'Se realiza revisión por fallas en los movimientos de la mesa, y en las prubas del diagnostico se halla filamento pequeño abierto. Por lo que al indagar con el personal ellos reportan que solo usan el filamento o foco grande.  Se hace revsión de Log de fallas y se encuentran errores de estabilizacion del KV y las corrientes de los filamentos encontrandose que el foco fino falla por lo que no permite hacer calibración del generador. Se recomienda realizar cambio del tubo de rayos X ya que puede dejar de funcionar en medio de un procedimiento. ', 'WO-01324023', '2020-02-20 00:00:00', '', '', '0000-00-00 00:00:00', 'no', 'Tubo de rayos X', 15, NULL),
(894, NULL, 1, 831, NULL, NULL, 'EL EQUIPO NO PRENDE', '2020-04-21 ', '8233', 'EL EQUIPO SI PRENDE, SE IDENTIFICAN PROBLEMAS EN LA CARGA DE LA BATERÍA Y EN LA ALIMENTACIÓN, SE GESTIONA LA SALIDA PARA QUE SEA REALIZADO EL RESPECTIVO DIAGNOSTICO POR LA EMPRESA GILMEDICA.\r\n\r\nLA EMPRESA REALIZA EL DIAGNOSTICO RESPECTIVO  Y SE IDENTIFICA BATERIA DAÑADA. ENVIA LAS COTIZACIONES RESPECTIVAS.', 'NO REGISTRA', '2020-04-21 00:00:00', 'Se realizan pruebas de funcionamiento en Gilmedica corrigen falla de apagado expontaneo del equipo, es necesario cambiar bateria equipo funcionable', 'SIN CODIGO', '2020-04-21 ', 'si', 'BATERIA', 15, 2),
(895, NULL, 1, 888, NULL, NULL, 'EL EQUIPO SE APAGA SOLO, HAY PROBLEMAS CON EL PULSADOR DE ENCENDIDO Y APAGADO', '2020-04-21 ', '8665', '', '', '0000-00-00 00:00:00', 'SEGUN ULTIMO MANTENIMIENTO PREVENTIVO DE JUNIO DE 2020, EL EQUIPO SE ENCUENTRA EN CORRECTAS CONDICIONES, \'POR LO TANTO SE CIERRA LA ORDEN.', 'SIN CODIGO', '2021-07-31 ', 'no', '', 15, NULL),
