(901, NULL, 1, 183, '668252b6f84d5263687565205841a77a.pdf', NULL, 'PRENDE PERO LA PANTALLA NO DA IMAGEN', '2020-03-31 ', '9756', 'SE REALIZA REVISION DE TARJETAS ELECTRONICAS UBICANDO COMPONENTES ELECTRONICOS DAÑADOS (TRANSISTORES DE POTENCIA, INDUCTANCIAS) SE REQUIERE CAMBIO DE TARJETA ELECTRONICA DE POTENCIA, SE EVIDENCIA QUE EL CONECTOR HEMBRA DEL EQUIPO ( PALAS DE DESCARGA) DAÑADO SE REQUIERE CAMBIO DE CONECTOR', '17640', '2020-04-22 00:00:00', '', 'SIN CODIGO', '2020-03-31 ', 'si', 'TARJETA ELECTRONICA DE POTENCIA CU MEDICAL SYSTEMS, CONECTOR HEMBRA PALAS', 15, 3),
