(969, NULL, 1, 763, 'f426265476f5b8602719d3dbc0bdf233.pdf', NULL, '\"EL QUIPO SUFRE CAIDA\"', '2020-05-13 00:00:00', 'NO REGISTRA', NULL, NULL, NULL, 'EL EQUIPO SUFRE UNA CAIDA. SE LE REALIZA REPARACIÓN DE LA PARTE FRONTAL DE LA PANTALLA EN LA CARCASA. SE EFECTUAN PRUEBAS DE FUNCIONAMIENTO. EQUIPO FUNCIONALMENTE OK. SE RECOMIENDA SUJETAR EL MONITOR A LA CAMA DEL PACIENTE DURANTE EL TRASLADO YA QUE SI EL EQUIPO SUFRE OTRA CAIDA NO SERA POSIBLE SU REPARACIÓN.', '18377', '2020-05-13 00:00:00', 'no', '', 15, NULL),
