(976, NULL, 1, 3303, 'acad17a6348f5eeda375e494ccdb4827.pdf', NULL, 'Instalación Equipo en servicio. Pruebas de Funcionamiento.', '2020-05-14 08:00:00', '', NULL, NULL, NULL, 'Se realizan pruebas de funcionamiento de todos los parámetros fisiológicos: EKG, SPO2; NIBP. \r\nSe realiza revisión e instalación de accesorios suministrados por el cliente. \r\nEquipo instalado por cambio de monitor SN. 94118317 (Fuera de Servicio). \r\nEquipo se entrega funcionalmente OK.', '18155', '2020-05-14 12:00:00', 'no', '', 15, NULL),
