(1030, NULL, 1, 499, 'f8a46b194b7c72c46a46250ce955a1c8.pdf', NULL, 'NO FUNCIONA. NO DA BUENA LUZ AL BEBÉ.', '2020-04-22 00:00:00', '9671', NULL, NULL, NULL, 'SE REALIZA REVISIÓN DEL SISTEMA ELÉCTRICO Y ELECTRÓNICO. SE DETECTA QUE LA RESISTENCIA ESTA DAÑADA. SE REALIZA CAMBIO DE LA MISMA, TAMBIÉN EL SENSOR MODO PIEL SE ENCONTRÓ EN MAL ESTADO Y SE PROCEDIÓ A SU CAMBIO.', '3851', '2020-05-14 00:00:00', 'no', '', 15, NULL),
