(1035, NULL, 1, 1728, '5cce87dff2061dcdc682030fe02efd0c.pdf', NULL, '__', '0000-00-00 00:00:00', 'SIN CÓDIGO', NULL, NULL, NULL, 'SE EFECTUÓ REPARACIÓN DEL SISTEMA ELÉCTRICO, CABLEADO Y CORRECCIÓN DE SOLDADURAS FRÍAS, AJUSTE DE CIRCUITO DISPLAY, LIMPIEZA DE TARJETAS ELECTRÓNICAS, LIMPIEZA GENERAL DE CHASIS Y PRUEBAS DE FUNCIONAMIENTO.', '3906', '2020-05-28 00:00:00', 'no', '', 15, NULL),
(1036, NULL, 1, 640, '3f3cb7b767288c1e22cb32a263d66473.pdf', NULL, 'Servicio reporta falla total del dispositivo.', '2020-06-11 ', '', NULL, NULL, NULL, 'Se revisa pantalla y panel frontal.\r\nSe verifica tarjetas electrónicas y se encuentra integrado quemado de la fuente.\r\n\r\nSe recomienda cambio de fuente de poder y tarjeta de NIBP.\r\nSE RECOMIENDA DAR DE BAJA EL DISPOSITIVO.', '18751', ' null', 'no', '', 16, 4),
(1037, NULL, 1, 3092, 'c9e9163b4aa8b4b004b1f6875075488d.pdf', NULL, 'El servicio reporta fallo en el equipo puesto que deja de imprimir mientras se realiza la toma de datos.', '2020-06-11 10:30:00', '', NULL, NULL, NULL, 'Se realiza inspección física del equipo y funciones.\r\nSe encuentran botones del panel frontal sin funcionar.\r\nSe prueba fuente funcional con falla para cargar batería.\r\nPanel de control con conexiones sueltas.\r\nSe evidencia al momento de imprimir bloqueo generando que no se termine el proceso y el equipo se apaga.\r\nSE RECOMIENDA DAR DE BAJA EL EQUIPO.', '18752', '2020-06-12 11:00:00', 'no', NULL, 12, NULL),
(1038, NULL, 1, 486, '5d3e913d372de8f21e0ad7c385362fd4.pdf', NULL, 'Se solicita a la empresa de Sysmed revisión de la máquina de anestesia para poner en funcionamiento en el Hospital Universitario del Valle sede Norte', '2020-06-16 ', '', NULL, NULL, NULL, 'Se realiza cambia de  membrana de la válvula expiratoria  puesto que se encontraba fractura. Tambié se realiza cambio de completo manguera incluyendo el  acople de toma de oxigeno y acople de entrada de oxigeno. \r\nRecomendación: Calibración y ajuste', '18753', '2020-06-17 ', 'no', '', 15, NULL),
(1040, NULL, 1, 2622, '1bce1350df48b5954618f1728b46eb03.pdf', NULL, 'Cama bloqueda ruido durante transporte, se deja en seguimiento', '2020-05-18 ', '18795', NULL, NULL, NULL, 'Se realiza cambio de control box', '18813', '2020-05-26 ', 'no', '', 15, NULL),
(1041, NULL, 1, 4121, '2d0d8ba649fe6fb87d6b2ef42ef5c64c.pdf', NULL, 'Se requiere cambio de motores', '2020-05-19 ', '18804', NULL, NULL, NULL, 'Se realiza cambio de los dos motores, equipo funcional.', '18822', '2020-05-09 ', 'no', '', 15, NULL),
(1042, NULL, 1, 4114, 'cf72993d49bbe006adc1b258b006f80b.pdf', NULL, 'Cama con ruido, se requiere cambio de motores H17-304.', '2020-05-09 ', '18806', NULL, NULL, NULL, 'Se realiza instalación de dos motores equipo funcional', '18821', '2020-06-09 ', 'no', '', 15, NULL),
(1043, NULL, 1, 2618, '268fb97a8318e2c8f86f4d500360c693.pdf', NULL, 'Cama bloqueada, en revisión se evidencia que esta presenta humedad y este no cubre garantía.', '2020-05-29 ', '18817', NULL, NULL, NULL, 'Se realiza limpieza de los controles de enfermería, y equipo queda funcional', '18817', '2020-05-29 ', 'no', '', 15, NULL),
(1045, NULL, 1, 2605, 'be831ef5b38931739d0337158099d017.pdf', NULL, 'Se reporta que la cama no sube, se realiza intercambio de control box y se evidencia que el de la cama se encuentra averiado, por lo cual se solicita.', '2020-05-26 ', '18814', NULL, NULL, NULL, 'Se realiza cambio de control Box', '18816', '2020-05-29 ', 'no', 'Control Box', 15, NULL),
(1046, NULL, 1, 2197, NULL, NULL, 'EL EQUIPO MARCA SPO2 SIN ESTAR CONECTADO A PACIENTE', '2020-06-18 ', '8680', NULL, NULL, NULL, 'SATURACION MARCA 88% CON Y SIN PACIENTE. SE REQUIERE RETIRAR EQUIPO PARA REVISION INTERNA POR GARANTIA. ORDEN SE INGRESA PARA EL MES DE JULIO AL NO SER REPORTADA ANTES. SE REALIZA REVISIÓN TÉCNICA, FUNCIONAL,, ENCONTRANDO ERROR REPORTADO, ADICIONALMENTE SE ENCONTRO QUE LA LECTURA PRESENTABA RUIDO Y EL EQUIPO MOSTRABA EL MENSAJE DE RUIDO SPO2, ESTAS FALLAS FUERON CORREGIDAS CON EL AJUSTE DE CONEXIONES, LIMPIEZA Y PRUEBAS CON OTRO SENSOR SPO2, EL EQUIPO QUEDA FUNCIONANDO CORRECTAMENTE. SE RECOMIENDA CAMBIAR EL SENSOR SPO2 Y BRAZALETE NIBP YA QUE PRESENTA DESGASTE.', 'SIN CODIGO', '2020-07-29 ', 'no', '', 15, NULL),
(1923, NULL, 1, 1953, 'ec48e40a25c48d31b0ed1abe070a7d36.pdf', NULL, '\"LLAMADO VERBAL\"', '2021-09-24 ', '62128', NULL, NULL, NULL, 'SE REALIZA INSTALACIÓN DE ADAPTADOR DC AL CICLOERGOMETRO SE APLICAN PRUEBAS DE FUNCIONAMIENTO, SE ENTREGA AL JEFE DEL SERVICIO. EQUIPO EN BUENAS CONDICIONES FISICAS Y OPERATIVAS. EQUIPO OK.\r\nADAPTADOR SUMINISTRADO POR EL CLIENTE.', '62128', '2021-09-24 ', 'no', NULL, 15, NULL),
(1047, NULL, 1, 974, 'b776c103c1156afbdab0e33c266da2c0.pdf', NULL, 'Recalentamiento del gantry', '2020-04-14 00:00:00', '', NULL, NULL, NULL, 'Se realiza mtto preventivo según protocolo adjunto, limpieza general, verificación de funcionamiento.\r\nScansec=448304.\r\nSe encontró tercer ventilador superior, izq a der dañado. Se debe utilizar con intervalos de 1 hora entre pacientes\r\npara no sobrecalentar el equipo..', '480200079452 -0001', '2020-04-21 00:00:00', 'no', '', 15, NULL),
(1048, NULL, 1, 974, '2cfe976a15dbf95003a101ce2db453e9.pdf', NULL, 'Revisión remota que genera error PROA CT_EXC_2', '2020-05-05 00:00:00', '', NULL, NULL, NULL, 'Instalación de repuestos.\r\n-Filtro de aire IRS\r\n-w320 sensor temp in\r\n-p68 gantry fan\r\n-Filter mat\r\n-p68 air filter sponge ser\r\n-w319 Sensor temp out\r\n\r\nVer reporte Anexo.\r\n', '480100387914-0022', '2020-05-08 00:00:00', 'no', '', 15, NULL),
(1049, NULL, 1, 3514, '447b3c30a806378632ff458e1ffaa1a6.pdf', NULL, 'Revisar el funcionamiento del panel frontal y los botones', '2020-06-25 ', '', NULL, NULL, NULL, 'Se realiza verificación de funcionamiento.\r\nEl panel frontal y los botones no responden.\r\nInspección física en buenas condiciones.\r\nSe hace ajuste de conexiones, se cambia un pulsador que está dañado.\r\nSe rearma equipo y se entrega Ok y funcionando.', '18756', '2020-06-25 ', 'no', 'Pulsadores.', 15, NULL),
(1050, NULL, 1, 3329, '6cb398847ccf753bf82d452611bc1e30.pdf', NULL, 'Revisar funcionamiento de botones y panel frontal que no responde.', '2020-06-24 ', '', NULL, NULL, NULL, 'Se desarma el equipo para revisar circuito y membrana de botones.\r\nSe encuentra daño en conector de botones; se hace arreglo, se suelda.\r\nSe encuentra daño en el parlante del monitor, no tiene alarma sonora.', '18754', '2020-06-24 ', 'no', 'Parlante para alarma.', 15, 0),
(1051, NULL, 1, 3327, '6b10b40d331ecd7c58f0b84138ced880.pdf', NULL, 'Verificación de equipo para llevar al servicio ya que el equipo no prende ni responde conectado a la red eléctrica.', '2020-06-25 ', '', NULL, NULL, NULL, 'Equipo visualmente en buen estado.\r\nSe hace cambio de cable AC con resultado que el equipo no prende.\r\nSe desarma y se verifica estado de la fuente que da como resultado que está dañada.\r\nSe generó corto en la fuente pequeña debido a que se encontraba suelta.\r\nSe pegan fuentes con placa de acrílico.\r\nSe hacen conexiones nuevas para energizar el equipo.\r\nSe arma y se entrega OK.', '18757', ' null', 'no', '', 15, 4);
