(1220, NULL, 1, 659, '63cf57dd7fa9b3012cb7e3a9734c07f8.pdf', NULL, 'PULSIOXIMETRO NO FUNCIONA Y NO TIENE BRAZALETE', '2020-08-25 ', '10887', NULL, NULL, NULL, 'SE SOLICITA CALIBRAR MONITOR, NO TIENE SATURADOR. SE DESCARGA SI SE DESCONECTA. TIENE UNA SEGUNDA ORDEN NUMERO 9110 \"NO TOMA OXIMETRÍA\" PRESENTA UNA NUEVA ORDEN DEL 25 DE AGOSTO DE 2020, REFIEREN QUE PULSIOXIMETRO NO FUNCIONA Y NO TIENE BRAZALETE. SE REALIZA CAMBIO E INSTALACIÓN DE MANGUERA NIBP Y BRAZALETE ADULTO SUMINISTRADO POR EL CLIENTE. QUEDA FUNCIONANDO CORRECTAMENTE EXCEPTUANDO BATERIA QUE NO TIENE Y REQUIERE CAMBIO', '19271', '2020-08-26 ', 'no', 'BATERIA', 15, NULL),
