(1228, NULL, 1, 184, '0e14459d3449d00efb788ded10144ef0.pdf', NULL, 'LA BATERÍA ESTA DESCARGADA', '2020-08-26 ', '10704', NULL, NULL, NULL, 'EL EQUIPO NO PASA PRUEBA PERIODICA, SE REALIZA REVISIÓN Y EL EQUIPO REQUIERE CAMBIO DE BATERÍA 12 V 2800MA, REF NKB-301V. EQUIPO FUNCIONAL\r\nSE CIERRA ORDEN YA QUE EQUIPO SE ENCUENTRA FUNCIONAL Y TIENE ORDENES MAS RECIENTES CERRADAS.', '19291', '2020-08-27 ', 'no', 'BATERIA', 15, 0),
(1229, NULL, 1, 221, '13196ebd0e795c42c9f73814aaf69a49.pdf', NULL, '\"SE APAGA\"', '2020-08-27 00:00:00', '10918', NULL, NULL, NULL, 'INDICAN QUE EL EQUIPO SE APAGA, DE ACUERDO AL MANUAL, EL EQUIPO PRESENTA APAGADO AUTOMATICO SIN SEÑAL, SE REALIZAN PRUEBAS CON ULTRASONIDO POR MAS DE UN MINUTO Y EL EQUIPO NO SE APAGA. EQUIPO FUNCIONANDO CORRECTAMENTE', '19292', '2020-08-28 00:00:00', 'no', NULL, 15, NULL),
(1230, NULL, 1, 2865, '318036909919ad1e8d06161f7d1c5b43.pdf', NULL, '\"MAL FUNCIONAMIENTO\" \"NO SUCCIONA\"', '2020-08-25 00:00:00', '10784', NULL, NULL, NULL, 'SE REALIZA LUBRICACION INTERNA DE RESORTE Y EMBOLO. SE AJUSTA ORING Y SE EFECTÚAN PRUEBAS DE FUNCIONAMIENTO. EQUIPO EN CORRECTO FUNCIONAMIENTO', '19653', '2020-08-27 00:00:00', 'no', NULL, 15, NULL),
(1231, NULL, 1, 455, '013950b5666e5e2dd8907987a430de3a.pdf', NULL, 'SE ATIENDE LLAMADO POR PERDIDA DE POTENCIA EN LA ENDOSONDA CURVA Y FALLAS EN EL INGRESO AL MODO DE ENDOSONDA DEL LASER 871694, SE PROCEDIO A REALIZAR LA ACTUALIZACION DEL SOFTWARE (VERSION 3.01) CUANDO SE ESTABA VERIFICANDO LOS VALORES DE CALIBRACION ENTRE EL LASER 871694 Y EL LASER 1224123. SE PRESENTÓ UN BAJÓN DE ENERGÍA EN EL REGULADOR Y AMBOS EQUIPOS SE APAGARON. SE CAMBIÓ DE TOMACORRIENTE, SIN EMBARGO, LOS EQUIPOS NO VOLVIERON A ARRANCAR. SE REVISARON LAS PROTECCIONES EXTERNAS DE LOS EQUIPOS Y ESTABAN ACTIVADOS. TAMBIÉN SE EVIDENCIA QUE AMBAS CPUS SE ALARMARON. AMBOS EQUIPOS DEBEN SER ENVIADOS A BOGOTA PARA REVISIÓN POR EL PERSONAL ESPECIALIZADO DE ZEISS MEDITEC. SE RETIRARON AMBAS CONSOLAS JUNTO CON LOS PANELES DE CONTROL Y CABLES DE PODER. LOS PEDALES QUEDARON EN EL CONSULTORIO LASER DE LA UNIDAD DE OFTALMOLOGÍA, LA ENDOSONDA ES ENTREGADA EN LA OFICINA DE BIOMEDICINA.', '2020-08-14 00:00:00', '3211', NULL, NULL, NULL, 'SE REALIZA INSTALACIÓN DE BOTÓN DE PARADA DE EMERGENCIA EN EQUIPO. \r\nSE REALIZAN PRUEBAS DE FUNCIONAMIENTO.\r\nSE ENTREGA EQUIPO EN BUEN FUNCIONAMIENTO.', '3514', '2021-02-01 00:00:00', 'no', 'BOTON DE PARADA DE EMERGENCIA', 15, NULL),
(1232, NULL, 1, 3511, '605ad779f5fc6e695f801658752395c8.pdf', NULL, 'SE ATIENDE LLAMADO POR PERDIDA DE POTENCIA EN LA ENDOSONDA CURVA Y FALLAS EN EL INGRESO AL MODO DE ENDOSONDA DEL LASER 871694, SE PROCEDIO A REALIZAR LA ACTUALIZACION DEL SOFTWARE (VERSION 3.01) CUANDO SE ESTABA VERIFICANDO LOS VALORES DE CALIBRACION ENTRE EL LASER 871694 Y EL LASER 1224123. SE PRESENTÓ UN BAJÓN DE ENERGÍA EN EL REGULADOR Y AMBOS EQUIPOS SE APAGARON. SE CAMBIÓ DE TOMACORRIENTE, SIN EMBARGO, LOS EQUIPOS NO VOLVIERON A ARRANCAR. SE REVISARON LAS PROTECCIONES EXTERNAS DE LOS EQUIPOS Y ESTABAN ACTIVADOS. TAMBIÉN SE EVIDENCIA QUE AMBAS CPUS SE ALARMARON. AMBOS EQUIPOS DEBEN SER ENVIADOS A BOGOTA PARA REVISIÓN POR EL PERSONAL ESPECIALIZADO DE ZEISS MEDITEC. SE RETIRARON AMBAS CONSOLAS JUNTO CON LOS PANELES DE CONTROL Y CABLES DE PODER. LOS PEDALES QUEDARON EN EL CONSULTORIO LASER DE LA UNIDAD DE OFTALMOLOGÍA, LA ENDOSONDA ES ENTREGADA EN LA OFICINA DE BIOMEDICINA.', '2020-08-14 ', '3211', NULL, NULL, NULL, 'SE REALIZA ENTREGA E INSTALACION DE EQUIPO. EQUIPO SE ENTREGA EN PERFECTO ESTADO Y FUNCIONAMIENTO. SE REALIZAN PRUEBAS DE FUNCIONAMIENTO CON EL MEDICO RESIDENTE GABRIEL RIOS.\r\nSE RECOMIENDA CONECTAR EL EQUIPO A UNA UPS PARA EVITAR PICOS DE VOTAJE Y DAÑOS EN EL EQUIPO.', '2264', '2021-04-13 ', 'no', '', 15, NULL),
