(1235, NULL, 1, 2944, 'b3a69abad964341590fbfafa7d69a85b.pdf', NULL, 'POR NECESIDAD DEL EQUIPO SE  REQUIERE CAMBIO DE TUBO DE RAYOS X', '2020-08-26 00:00:00', 'NO REGISTRA', NULL, NULL, NULL, 'correctivas: Se realizó el cambio del Tubo de\r\nrayos X\r\n* MRC 200 0407 ROT-GS 1004\r\nSe realizó ajustes del generador, conditioning, adaptation,\r\nYield, EDL, calibración del detector, IQ level ok, calibración\r\ndel modulo GSS OK, se calibró la estación 3D extravisión\r\nok,\r\nse realizó backup del equipo FD20. se realizó pruebas\r\ncon Phantom y el equipo trabajó correctamente, se\r\nentrega operativo.', 'WO-01330486', '2020-08-26 00:00:00', 'no', NULL, 15, NULL),
