(1373, NULL, 1, 2379, '83aee06c463b9ce0ac2573969059a55f.pdf', NULL, '\"EQUIPO PRESENTA FUGA\"', '2020-10-26 ', '108765', NULL, NULL, NULL, 'SE REVISA FALLA REPORTADA, SE ANALIZA CON EQUIPO PATRON, EQUIPO ENTREGA LOS VALORES CORRESPONDIENTES. SE EVIDENCIA FUGA EN EMPAQUE DEL CRICUITO. EL EQUIPO FUNCIONA CORRECTAMENTE PERO LOS CIRCUITOS DE PACIENTE PRESENTAN VALVULAS ROTAS QUE GENERAN FUGA. POR LO TANTO EL EQUIPO QUEDA FUERA DE SERVICIO. \r\nSE DEBEN CONSEGUIR LOS REEMPLAZOS DE LAS VALVULAS.', '20005', '2020-10-26 ', 'si', 'VALVULA DE CIRCUITO', 15, 0),
(1374, NULL, 1, 1878, NULL, NULL, 'AL REALIZAR MOVIMIENTO DE SUBIDA SE ESCUCHA RUIDO. SE REPORTA A STRIKER A PESAR QUE YA NO LO CUBRE GARANTÍA', '2020-10-27 ', '11701', NULL, NULL, NULL, 'DE ACUERDO A ULTIMO PREVENTIVO, EL EQUIPO SE ENCUENTRA FUNCIONAL, POR LO TANTO SE CIERRA ORDEN YA QUE FUE INTERVENIDO Y SE DEJA CON REPUESTO PENDIENTE (MOTORES)', 'SIN CODIGO', '2020-12-02 ', 'no', '', 15, NULL),
(1375, NULL, 1, 974, NULL, NULL, 'NO PRENDE UPS Y GANTRY', '2020-08-25 00:00:00', 'NO REGISTRA', NULL, NULL, NULL, 'Fall en UPS..\r\nFalla permanente. .\r\nSe verifica entrada de voltaje a la UPS y se encuentran 0 VAC.\r\nEn la LCB tampoco hay alimentación.\r\nSe encuentra el braker F1 disparado, lo cual corta la alimentación eléctrica a los componentes del sistema.\r\nSe verifica que no exista riesgo electrico y se activa de nuevo en F1, equipo enciende sin problemas..\r\n\r\nEl breaker F1 se pudo haber activado debido a una fluctuación en la línea principal de voltaje.\r\nPrueba general concluyo exitosamente. .', '480100406451 -0006', '2020-08-25 00:00:00', 'no', '', 15, NULL),
