(1382, NULL, 1, 157, '15a2d8ad7af130e64a7df23dfe98dc69.pdf', NULL, 'SE REPORTA TELEFONICAMENTE QUE LA COMPUERTA DE LA CENTRIFUGA ESTA ATORADA Y NO ABRE, SE SOLICITA ENVIO DEL PERSONAL TECNICO Y PRIORIDAD EN EL LLAMADO YA QUE DENTRO DE LA CENTRIFUGA HAY UNAS MUESTRAS INDISPENSABLES PARA LA PRESTACIÓN INMEDIATA DEL SERVICIO.', '2020-10-30 00:00:00', 'NO REGISTRA', NULL, NULL, NULL, 'SE REALIZA REPARACIÓN DE TARJETA ELECTRONICA Y SE CAMBIA TRANSISTOR DE POTENCIA, SE REALIZAN PRUEBAS DE FUNCIOANMIENTO Y SE ENTREGA EQUIPO N BUENAS CONDICIONES FISICAS Y OPERATIVAS', '19359', '2020-01-31 00:00:00', 'no', NULL, 15, NULL),
