(1385, NULL, 1, 3810, NULL, NULL, '', '0000-00-00 00:00:00', '', NULL, NULL, NULL, 'Equipo requiere cambio de válvulas completas, cambio de kit, equipo con más de 40 mil horas de uso, requiere sensor de oxígeno, cambio de empaque completos.\r\nEquipo fuera de servicio.', '18791', '2020-11-10 00:00:00', 'no', NULL, 16, NULL),
(1386, NULL, 1, 2959, '1218f90fdfe07898ac169613f71b12e6.pdf', NULL, 'Se reporta que el equipo no enciende al iniciar jornada.', '2020-11-20 08:00:00', 'No registra', NULL, NULL, NULL, 'Ventiladores del equipo no encienden, falla permanente, se encuentra el breaker F7 disparad, se activa nuevamente y equipo enciende. Se realiza calibración y  chequeo funcional del equipo de forma exitosa.\r\nEl equipo detectó una fluctuación del voltaje en la línea, eso pudo haber causado que el breaker F7 se dispare.\r\nPruebas funcionales exitosas..', '480100420906-0007', '2020-11-20 15:23:00', 'no', NULL, 15, NULL),
(1387, NULL, 1, 4758, '4773b271d5389d5a9c9042e748422618.PDF', NULL, 'Se informa que bajo el gantry sale un liquido, se reporta a siemens.', '2020-11-24 08:00:00', 'No registra', NULL, NULL, NULL, 'Se encuentra aceite bajo el Gantry, se verifica internamente la parte frontal del Gantry y la unidad de enfriamiento, no se evidencia ningún componente con fuga de aceite.', '480100421383-0002', '2020-11-24 09:00:00', 'no', '', 15, NULL),
(1388, NULL, 1, 4893, '9c1f62a0d3e57f2a3b78277e3fa7a2f7.pdf', NULL, 'Correo enviado a soporte Leistung \"Me permito informar que se ha revisado el informe enviado, y es pertinente revisar estos porcentajes de error ya que +/-4ml + 15% es un rango muy amplio para manejar clínicamente.\r\nEstos resultados son después de realizar ajustes? o actualización de software? Porque no se realizaron pruebas con otros parámetros como frecuencia o PEEP, o se tomaron diferentes volúmenes?\"', '2020-11-18 00:00:00', 'Sin código', NULL, NULL, NULL, 'Se realiza verificación y revisión adicional en los equipos que tuvieron un porcentaje de error superior al 15%', 'HUV0040', '2020-11-23 00:00:00', 'no', NULL, 15, NULL),
