(1431, NULL, 1, 4116, NULL, NULL, 'Cama presenta sonido.', '2020-05-19 00:00:00', '18801', NULL, NULL, NULL, 'Se realiza instalación de dos motores hight low que presentaban ruido al ascenso del plano de la cama\r\nPrueba de funcionamiento Ok\r\nEquipo se entrega funcional.', '18916', '2020-08-06 00:00:00', 'no', '', 15, NULL),
(1432, NULL, 1, 4787, NULL, NULL, 'SE ENTREGA TERMOMETRO PARA \"CALIBRACIÓN\" YA QUE, AL TOMAR TEMPERATURA DE LOS PACIENTES, SIEMPRE MARCA 36.4.', '2020-07-30 00:00:00', 'NO REGISTRA', NULL, NULL, NULL, 'SE DA DE BAJA EQUIPO YA QUE NO ES POSIBLE SU REPARACIÓN, EL EQUIPO PRESENTA UNA TARJETA ELECTRONICA Y SENSOR CON OBSOLESCENCIA TEMPRANA. EQUIPO SE ADQUIRIÓ SIN GARANTÍA Y CALIBRACIÓN. SU REPARACIÓN ES MAS COSTOSA QUE EL MISMO EQUIPO.', 'SIN CODIGO', '2020-12-03 00:00:00', 'no', NULL, 16, NULL),
(1433, NULL, 1, 4900, '5b9da18c646f1efdfe53df0e72315e61.pdf', NULL, '', '0000-00-00 00:00:00', '', NULL, NULL, NULL, 'SE REALIZA INSPECCIÓN DEL EQUIPO; PASA PRUEBA DE LÍNEA SIN PROBLEMA, SE REALIZA VERIFICACIÓN DE FUGAS Y APERTURA DE VÁLVULAS EN BUEN ESTADO; SE INCIA PRUEBA DE CICLADO, DUDANTE UN INTERVALO DE 3 HORAS DE TIEMPO SE REALIZAN PRUEBAS; EL EQUIPO SE ENCUENTRA EN NORMAL FUNCIONAMIENTO.\r\nEQUIPO FUNCIONAL.', 'HUV0051', '2020-12-07 13:00:00', 'no', NULL, 15, NULL),
