(1436, NULL, 1, 2622, '4d96a0a330f8722ef1f924b47509eb9b.pdf', NULL, '', '2020-06-09 00:00:00', '18795', NULL, NULL, NULL, 'Se realiza seguimiento a ruido de la cama, se recomienda cambio de motor', '18812', '2020-05-19 00:00:00', 'no', 'Motor HM 17-304 *1 y control box', 15, NULL),
(1437, NULL, 1, 1841, '9f1f5575183b24c44c5bf65422b1a8f0.pdf', NULL, 'EN ENDOSCOPIA REPORTAN QUE LA FUENTE DE LUZ NEVCESITA MANTENIMIENTO Y NO FUNCIONA', '2020-12-03 00:00:00', 'NO REGISTRA', NULL, NULL, NULL, 'SE REVISA EL EQUIPO Y SE DETERMINA QUE LA TORRE DE ENDOSCOPIA SE ENCUENTRA EN OPTIMAS CONDICIONES DE USO, LA FUENTE DE LUZ TIENE LAMPARA DE LUZ XENON DE  330 h / 500h DE USO, POR LO QUE A LA FECHA NO DEBE SER CAMBIADA.\r\nEL PROBLEMA IDENTIFICADO ESTABA RELACIONADO RELAMENTE CON EL GASTROSCOPIO DE SERIE TERMINADA EN K132, EL CUAL AL MOMENTO DE LA REVISIÓN ANTES DE GESTIONAR LA SALIDA SE IDENTIFICO CON FUGA POSITIVA', 'NO REGISTRA', '2020-12-03 00:00:00', 'no', NULL, 15, NULL),
(1438, NULL, 1, 2412, 'acb10f521fc97a848338c11af71b364a.pdf', NULL, 'amplificador no conecta, errores de study room', '2018-09-11 00:00:00', 'no registra', NULL, NULL, NULL, 'se verifican conexiones, de amplificador, se ajusta y limpia base de datos, se desfragmenta disco duro, se limpia polvo de tarjetas y procesador, se limpia teclado, mouse, pantalla, se limpian puertos de amplificador, pruebas de fotoestimulador ok, test de impedancia ok, test de canales ok, se realiza backup de configuracion y de plantillas', '5699', '2018-09-11 00:00:00', 'no', NULL, 15, NULL),
(1439, NULL, 1, 4890, '3b8b0f33a62b44f1a530fff9ba283a41.pdf', NULL, '', '0000-00-00 00:00:00', 'Sin código', NULL, NULL, NULL, 'Se realiza ajuste por software para mejorar el porcentaje de error ya que la momento de realizar la calibración por la empresa externa superaba el 15%', 'HUV0047', '2020-12-04 00:00:00', 'no', NULL, 15, NULL),
(1440, NULL, 1, 4901, '859575f8af657131304133ad0fdf3d5e.pdf', NULL, '', '0000-00-00 00:00:00', '', NULL, NULL, NULL, 'AL MOMENTO DE REALIZAR LA PRUEBA DE LÍNEA EL EQUIPO PRESENTA FALLA, SE HACE REVISIÓN POR LO CUAL SE INTERVIENE EL EQUIPO DEBIDO A QUE HAY FUGA EN VÁLVULA PROPORCIONAL DE OXÍGENO, SE REALIZA AJUSTE VARIANDO LA VÁLVULA INTERNAMENTE HASTA LLEGAR AL VALOR ADECUADO PARA LA APERTURA DEL GAS, POR LO CUAL, UNA VEZ ELIMINADA LA FUGA, SE REALIZA NUEVAMENTE PRUEBA DE LÍNEA Y EFECTIVAMENTE EL EQUIPO PASA SIN PROBLEMA, SOLUCIONADO EL INCONVENIENTE, SE CONTINÚA CON EL PROCESO DE CALIBRACIÓN.', 'HUV0049', '2020-12-04 00:00:00', 'no', NULL, 15, NULL),
(1441, NULL, 1, 4921, '27e4236f9c53fde91ed2892ae5266b9e.pdf', NULL, '', '0000-00-00 00:00:00', '', NULL, NULL, NULL, 'EN EL MOMENTO EN QUE SE REALIZA EL PROCESO DE CALIBRACIÓN CON EMPRESA EXTERNA, SE DETECTA QUE EL EQUIPO PRESENTA RANGOS DE ERROR DEL 15% ,Y EN ALGUNAS MEDICIONES YA ES EL 16% ; DEBIDO A QUE LLEGA A SU LÍMITE Y EL ALGUNAS MEDICIONES LO SOBREPASA SE DECIDE REALIZAR AJUSTE POR SOFTWARE PARA ASÍ MEJORAR ÉSTOS PORCENTAJES', 'HUV0048', '2020-12-04 00:00:00', 'no', NULL, 15, NULL),
(1442, NULL, 1, 4895, 'dfb2ce37091f5b173d20cd35dd11c401.pdf', NULL, '', '0000-00-00 00:00:00', '', NULL, NULL, NULL, 'SE REALIZA VERIFICACIÓN DEL EQUIPO EL CUAL PRESENTA UN ERROR DE FUGA AL INICAR LA PRUEBA DE LÍNEA, SE REALIZA MODIFICACIÓN INTERNA PARA VERIFICAR LA APERTURA DE LAS VÁLVULAS PROPORCIONALES; SE EXTRAE VÁLVULA DE AIRE SE DESAJUSTA TUERCA EN LA PARTE DE ABAJO PARA ASÍ MOVER SU EJE INTERNO Y ELIMINAR LA FUGA, SE AJUSTA NUEVAMENTE SU TUERCA, SE DEJA EN LA POSICIÓN INICIAL Y EN LOS VALORES ADECUADOS; SE VERIFICA VÁLVULA T, VÁLVULAS REGULADORAS, SE REALIZA LA PRUEBA INICIAL, EL EQUIPO PASA SIN PROBLEMAS. Y SE CONTINÚA CON EL PROCESO DE CALIBRACIÓN.', 'HUV0050', '2020-12-04 00:00:00', 'no', NULL, 15, NULL),
(1443, NULL, 1, 559, '58bf627d71c7b047d34dee045360bf6e.pdf', NULL, '', ' ', '', NULL, NULL, NULL, 'Se realiza ajeste en la conexión con sus tornillos que lo sujeta al panel de control.\r\nSe hace ajuste en conector del cable de SpO2 para que la conexión quede fija.\r\nEquipo funcionalmente ok.', '18957', '2020-12-09 ', 'no', 'Cable de sensor SpO2', 15, 0),
(1444, NULL, 1, 734, NULL, NULL, 'nr', '2020-11-19 ', 'NO REGISTRA', NULL, NULL, NULL, 'INDICA QUE EL EQUIPO NO TOMA SPO2 NI NIBP, SE REALIZA PRUEBA DE FUNCIONAMIENTO CON EQUIPO PATRON, SE DETECTA QUE EL SENSOR SPO2 ESTA MALO Y SE REALIZA PRUEBAS DE NIBP DANDO BUENOS RESULTADOS, SE REALIZA INSTALACION DEBRAZALETE PEDIATRICO SUMINISTRADO POR EL CLIENTE. REQUIERE INSTALACION DE SENSOR SPO2.', '19372', '2020-11-19 ', 'no', 'SENSOR SPO2', 15, NULL),
(1445, NULL, 1, 988, NULL, NULL, 'REVISION DE LA TRACCION LUMBAR', '2020-11-25 00:00:00', '11592', NULL, NULL, NULL, 'SE REALIZA INSPECCIÓN VISUAL, LIMPIEZA INTERNA DE TARJETAS ELECTRONICAS Y PRUEBAS DE FUNCIONAMIENTO', '20036', '2020-11-27 00:00:00', 'no', NULL, 15, NULL),
(1446, NULL, 1, 2959, 'c31ad9422f60dfba369adddd07fee124.pdf', NULL, 'EQUIPO NO ENCIENDE', '2020-11-20 00:00:00', 'NO REGISTRA', NULL, NULL, NULL, 'Ventiladores del equipo no encienden..\r\nFalla permanente. .\r\nSe encuentra el breaker F7 disparado, se activa nuevamente y los ventiladores encienden.\r\nSe realiza calibración y chequeo funcional del equipo de forma exitosa.', '480100420906 -0007', '2020-11-20 00:00:00', 'no', NULL, 15, NULL),
(1447, NULL, 1, 2959, '4315d7b1d44240e21aab6653e0f67b25.pdf', NULL, 'falla en ups', '2020-08-25 00:00:00', 'NO REGISTRA', NULL, NULL, NULL, 'Falla en UPS..\r\nFalla permanente. .\r\nSe verifica entrada de voltaje a la UPS y se encuentran 0 VAC.\r\nEn la LCB tampoco hay alimentación.\r\nSe encuentra el braker F1 disparado, lo cual corta la alimentación eléctrica a los componentes del sistema.\r\nSe verifica que no exista riesgo eléctrico y se activa de nuevo en F1, equipo enciende sin problemas.', '480100406451 -0006', '2020-08-25 00:00:00', 'no', NULL, 15, NULL),
