(1451, NULL, 1, 597, 'f40ff0e9510396faa2aa8e09c9e9cb65.pdf', NULL, '\"EQUIPO SUFRE CAIDA\"', '2020-11-24 ', 'NO REGISTRA', NULL, NULL, NULL, 'EL EQUIPO SUFRE CAIDA AL MOMENTO DE TRASLADAR A UN PACIENTE, SE DETECTA QUE LA PANTALLA ESTA DAÑADA Y LA ESTRUCTURA DE SOPORTE DE TARJETAS ELECTRONICAS FRACTURADAS, EL EQUIPO QUEDA FUERA DE SERVICIO A LA ESPERA DE REPUESTO. REQUIERE CAMBIO DE PANTALLA, BATERIA Y CARCASA COMPLETA.', '19382', '2020-11-24 ', 'no', 'PANTALLA, BATERIA, CARCASA COMPLETA', 15, 0),
