(1468, NULL, 1, 5384, '62b71adf82248136636341697063b989.pdf', NULL, '\"SE SOLICITA REPARAR MONITOR DE SIGNOS VITALES DEBIDO A QUE PULSIOXIMETRO NO SENSA\"', '2020-11-25 00:00:00', '12310', NULL, NULL, NULL, 'SE ENCUENTRA CABLE DE SPO2 DAÑADO Y BRAZALETE DE PRESION DAÑADO. SE REALIZA INSTALACION DE CABLE DE SATURACION Y BRAZALETE. SE RECOMIENDA AL PERSONAL CUIDADO A LAINSERCIÓN DEL CABLE SPO2 YA QUE SE ENCONTRÓ MAL INSERTADO.', 'SIN CODIGO', '2020-11-25 00:00:00', 'no', NULL, 15, NULL),
