(1470, NULL, 1, 448, 'eea7906e984ccebd8006e2905fa0789c.pdf', NULL, '\"AJUSTAR\"', '2020-11-04 00:00:00', 'NO REGISTRA', NULL, NULL, NULL, 'SE REALIZA CAMBIO E INSTALACION DE PRISMA TOPCON. SE REALIZA AJUSTE DE MEDICIONES EN EL TONOMETRO CON SISTEMA DE MEDICIONES EN EL PUNTO 0, 20, 40 Y 60 MMHG, SE REALIZAN AJUSTES EN LOS ANGULOS DE INCIDENCIA ENTRE LAMPARA DE HENDIDURA Y TONOMETRO. NO FUE POSIBLE AJUSTAR EL SISTEMA DE VISION DESDE LOS 2 OBJETIVOS DE LA LAMPARA PUES LA BASE DEL TONOMETRO NO CORRESPONDE AL MODELO DE ESTE EQUIPO.', '20041', '2020-11-04 00:00:00', 'no', '', 15, NULL),
