(1494, NULL, 1, 4758, '823b36d52ddb3c5996a76bf19e1f7aef.PDF', NULL, 'SOBRECALENTAMIENTO ESTUDIOS LARGOS', '2020-10-08 00:00:00', '', NULL, NULL, NULL, 'Calentamiento en estudios largos..\r\nSe presenta cuando hacen varios pacientes seguidos..\r\nRevisión de filtros de aire, revisión física de la bomba de aceite del sistema de refrigeración del tubo. Condiciones\r\nambientales en rango (temperatura y humedad). Equipo en especificaciones, funcionamiento normal.', '480100413910-0015', '2020-10-08 00:00:00', 'no', '', 15, NULL),
