(1604, NULL, 1, 487, '7a404711e02298d8806bb05f5847938b.pdf', NULL, 'Equipo fuera de servicio, requiere cambio de kit de mantenimiento, no pasa prueba de fugas y calibración', '2021-03-16 ', '13098', NULL, NULL, NULL, 'SE EVIDENCIO FALLA EN LAS PRUEBAS DE FUGA Y FLUJO. SE REALIZARON PRUEBAS DE TARJETA DONDE VA EL TRASDUCTOR DE PRESION CON LA DE OTRA MAQUINA DE ANESTESIA DE LA MISMA REFERENCIA Y EL EQUIPO FUNCIONA CORRECTAMENTE, REQUIER CAMBIO DE LA TARJETA DE TRANSDUCTOR DE PRESION. EL EQUIPO QUEDA FUERA DE SERVICIO.', 'SIN CODIGO', '2021-03-18 ', 'no', 'KIT DE MANTENIMIENTO', 16, 3),
(1605, NULL, 1, 2058, 'b8b7aebdf12e8a0934dc2c1e7f8da4bc.pdf', NULL, 'Equipo fuera de servicio no tiene sensor de flujo', '2021-03-16 ', '13099', NULL, NULL, NULL, 'SE REALIZA MANTENIMIENTO CORRECTIVO, SE REALIZA INSPECCIÓN FISICA Y ESTRUCTURAL, LA PANTALLA TACTIL SE ENCUENTRA EN ESTADO REGULAR, EL ENCODER SE ENCUENTRA EN ESTADO REGULAR. SE REALIZA INSTALACIÓN DE SENSOR DE FLUJO NUEVO. SE EFECTUAN PRUEBAS DE FUNCIONAMIENTO CON EQUIPO PATRON, REUIQERE CAMBIO DE PANTALLA TACTIL, ENCODER Y KIT DE MANTENIMIENTO. EQUIPO FUNCIONALMENTE OK', '59034', '2021-03-30 ', 'no', 'SENSOR DE FLUJO', 15, NULL),
(1606, NULL, 1, 474, '789ca1464e95bc20a053a7d42e2217f0.pdf', NULL, 'EQUIPO FUERA DE SERVICIO POR PERDIDA DE SENSOR DE FLUJO', '2021-03-16 ', '13094', NULL, NULL, NULL, 'SE REALIZO MANTENIMIENTO CORRECTIVO, SE REALIZA INSPECCIÓN FISICA Y ESTRUCTURAL, LA PANTALLA TACTIL SE ENCUENTRA EN ESTADO REGULAR, EL ENCODER SE ENCUENTRA EN ESTADO REGULAR. SE REALIZA ISNTALACIÓN DE SEBSIR DE FLUJO NUEVO, SE EFECTUAN PRUEBAS DE FUNCIONAMIENTO JUNTO CON EQUIPO PATRON, REQUIERE CAMBIO DE PANTALLA TACTIL, ENCODER Y KIT DE MANTENIMIETNO. EQUIPO FUNCIONALMENTE OK', '59033', '2021-03-30 ', 'no', 'SENSOR DE FLUJO', 15, NULL),
(1607, NULL, 1, 468, '335020d2310dbe5f59006d9dc3577ccf.pdf', NULL, 'Equipo fuera de servicio por fuga constante, no permite llegar al volumen deseado', '2021-03-16 ', '13093', NULL, NULL, NULL, '', 'SIN CODIGO', '2021-03-16 ', 'no', '', 15, 3),
(1608, NULL, 1, 2862, '82a61a3e908132edfff7577fc6c6ccc2.pdf', NULL, '\"REVISAR\"', '2021-03-17 10:30', 'NO REGISTRA', NULL, NULL, NULL, 'SE REALIZA INSTALACION DE ADAPTADOR DE VOLTAJE (CONECTOR) SE REALIZAN PRUEBAS DE FUNCIONAMIENTO, EL EQUIPO RESPONDE CORRECTAMENTE.', '21573', '2021-03-17 11:40', 'no', NULL, 15, NULL),
(1609, NULL, 1, 3014, '789b9311d8eb9a4708af172a4700c94a.pdf', NULL, 'FAVOR REVISAR', '2021-02-26 ', 'NO REGISTRA', NULL, NULL, NULL, 'SE REALIZA INSPECCIÓN FISICA Y VISUAL DE FUNCIONAMIENTO DE TOCOS Y TRASDUCTORES, TOCO ULTRASONIDO, MARCADOR DE EVENTOS, PULSADORES, PANTALLA FRONTAL, IMPRESORA Y CABLE DE PODER, DONDE SE EVIDENCIA UN CORRECTO ESTADO DE LAS LECTURAS DE CONTRACCIONES UTERINAS Y FRECUENCIA CARDIACA DEL FETO. SE EJECUTA UNA LIMPIEZA Y DESINFECCIÓN INTERNA Y EXTERNA, EQUIPO OK.', '21517', '2021-02-26 ', 'no', NULL, 15, NULL),
(1610, NULL, 1, 264, '84f3ad4d99589963364ceb4b00c2489d.pdf', NULL, 'FAVOR CAMBIAR CABLEADO, MANIJAS Y CAMPANAS, COLOCAR BOTON DE AUTOMATICO.', '2021-03-10 ', '14131', NULL, NULL, NULL, 'SE REALIZA INSPECCIÓN FUNCIONAL Y ESTRUCTURAL DONDE SE EVIDENCIA AUSENCIA DE BOTON PARA FUNCION DE AUTOMATICO. LOS ACCESORIOS SE ENCUENTRAN DETERIORADOS. SE REALIZA CAMBIO DE JUEGO DE CHUPAS NUEVAS SUMINISTRADAS POR EL CLIENTE. SE HACE REEMPLAZO DE BOTON POR UN PULSADOR. SE EFECTUAN PRUEBAS DE FUNCIONAMIENTO Y LIMPIEZA EXTERNA. REQUIERE CAMBIO DE CABLE EKG. EQUIPO OK', '21566', '2021-03-12 ', 'no', NULL, 15, NULL),
(1611, NULL, 1, 2114, 'd9542af8ed03e2c08a5791163280e3c8.pdf', NULL, 'REVISAR', '2021-03-12 ', '14191', NULL, NULL, NULL, 'SE REALIZA FIJACIÓN DE SOPORTE DE EJE CENTRAL, EL EQUIPO SE ENCUENTRA EN BUENAS CONDICIONES PARA SU FUNCIONAMIENTO. SE ENTREGA EQUIPO EN BUENAS CONDICIONES FISICAS Y OPERATIVAS.', '21527', '2021-03-15 ', 'no', NULL, 15, NULL),
(1612, NULL, 1, 738, 'd4267be5c41417a4aca661fb24067e73.pdf', NULL, 'FAVOR INSTALAR ACCESORIOS', '2021-03-18 ', '21534', NULL, NULL, NULL, 'SE REALIZA INSPECCIÓN VISUAL Y ESTRUCTURAL, SE REALIZA INSTALACION DE ACCESORIOS, SE VERIFICA FUNCIONAMIENTO DE CADA UNO DE LOS PARAMETROS CON EQUIPO PATRON. SE ENTREGA EQUIPO EN BUENAS CONDICIONES FISICAS Y DE FUNCIONAMIENTO.', '21534', '2021-03-18 ', 'no', NULL, 15, NULL),
(1613, NULL, 1, 162, 'a5bdcef532d944a91c6b0e5056fe9d4a.pdf', NULL, 'DAÑI ELECTRICO POR BAJON DE ENERGIA', '2021-03-10 ', '13056', NULL, NULL, NULL, 'SE REALIZA UNA INSPECCIÓN FISICA Y VISUAL DEL FUNCIONAMIENTO COMPONENTES ELECTRONICOS, PULSADORES, PANTALLA FRONTAL, CARCASA, CABLE DE PODER DONDE SE EVIDENCIA CORRECTO ESTADO.\r\nSE REALIZA INSTALACIÓN DE FUSIBLE CERAMICO 16A, SE APLICAN PRUEBAS DE FUNCIONAMIENTO EN DIFERENTES PARAMETROS, EQUIPO OK.\r\nEQUIPO SE ENCUENTRA EN BUENAS CONDICIONES PARA SU FUNCIONAMIENTO, SE ENTREGA EQUIPO EN BUENAS CONDICIONES FISICAS Y OPERATIVAS A LAS 5:15 PM.', '21569', '2021-03-11 ', 'no', '', 15, NULL),
(1614, NULL, 1, 2370, 'bf63905195f5561c750c41464ec51d83.pdf', NULL, '\"DESCALIBRADA\"', '2021-03-12 ', '12861', NULL, NULL, NULL, 'SE REALIZA UNA INSPECCIÓN FISICA Y VISUAL DEL FUNCIONAMIENTO, BATERIAS, PULSADOR, SELECTOR DE UNIDADES DE PESO, GALGAS, BANDEJA. DONDE SE EVIDENCIA UN CORRECTO ESTADO DEL EQUIPO, SE APLICAN PRUEBAS DE EXCENTRICIDSAD Y REPETIBILIDAD AL EQUIPO, SE REALIZA LIMPIEZA INTEGRAL EXTERNA. EQUIPO OK.', '21519', '2021-03-12 ', 'no', NULL, 15, NULL),
(1615, NULL, 1, 758, '271913970fe75cc9abcc9ddceb10cc47.pdf', NULL, 'FAVOR INSTALAR ACCESORIOS', '2021-03-16 ', '21530', NULL, NULL, NULL, 'SE REALIZA INSTALACION DE ACCESORIOS NUEVOS (CABLE ECG, MANGUERA NIBP, BRAZALETE, SENSOR SPO2 Y CABLE AC) SUMINISTRADOS POR EL CLIENTE, SE VERIFICA CON EL PERSONAL DE SERVICIO EL FUNCIONAMIENTO DE TODOS LOS PARAMETROS, EL EQUIPO RESPONDE CORRECTAMENTE.\r\nEL EQUIPO SE ENTREGA EN BUENAS CONDICIONES PARA SU FUNCIONAMIENTO.', '21530', '2021-03-16 ', 'no', NULL, 15, NULL),
(1616, NULL, 1, 2006, '75ef9a8c75728c18d00d7a657141617e.pdf', NULL, 'REVISAR', '2021-03-18 ', '21577', NULL, NULL, NULL, 'SE REALIZA VERIFICACION DE PULSADORES, TRANSFORMADOR, CABLEADO, PORTA BOMBILLO, BOMBILLOS, MOVIMIENTOS DE BRAZOS. SE ENCUENTRA PORTA BOMBILLO EN MAL ESTADO, SE RALIZA CAMBIO DE PORTABOMBILLO (SOCKET) ENTREGADO POR EL CLIENTE', '21577', '2021-03-18 ', 'no', NULL, 15, NULL),
(1617, NULL, 1, 2193, 'e59b9a189c30d2b889899b7b60ab97f8.pdf', NULL, 'REVISAR', '2021-03-15 ', '14202', NULL, NULL, NULL, 'SE REALIZA UNA INSPECCIÓN FÍSICA Y VISUAL DEL FUNCIONAMIENTO DEL BRAZALETE, SENSOR DE OXIGENO, SENSOR DE TEMPERATURA, PANTALLA FRONTAL, COMPONENTES ELECTRÓNICOS, PULSADORES, CABLE DE PODER, DONDE SE EVIDENCIA FRACTURA DE LOS PINES DEL SENSOR DE OXIGENO. REQUIERE REEMPLAZO DE SENSOR DE OXIGENO.\r\nSE REALIZA INSTALACIÓN DEL SENSOR DE OXIGENO SUMINISTRADO POR EL CLINETE. SE APLICAN PRUEBAS POR MEDIO DEL EQUIPO PATRON.', '21520', '2021-03-15 ', 'no', NULL, 15, NULL),
(1618, NULL, 1, 733, '4c7ee6b2e579eef83a5bc3bd0613771b.pdf', NULL, 'FAVOR INSTALAR ACCESORIOS', '2021-03-16 ', '21571', NULL, NULL, NULL, 'SE REALIZA INSTALACION DE ACCESORIOS NUEVOS (CABLE EKG, MANGUERA NIBP, BRAZALETE, SENSOR SPO2 Y CABLE AC)SUMINSITRADOS POR EL CLIENTE. SE VERIFICA CON EL PERSONAL DEL SERVICIO EL FUNCIONAMIENTO DE CADA UNO. EL EQUIPO RESPONDE CORRECTAMENTE.', '21571', '2021-03-16 ', 'no', NULL, 15, NULL),
