(1622, NULL, 1, 414, '0c91a5c38ed7e81aae025d1ce9b71039.pdf', NULL, '\"DESAJUSTADO\"', '2021-03-10 ', '14121', NULL, NULL, NULL, 'EL DIA JUEVES 18/03/2021 SE REALIZA CALIBRACIÓN CON DIFERENTES ESFERAS Y SE AJUSTA LOS GRADOS DE MANERA VERTICAL Y HORIZONTAL PARA ALINEAR LA MEDIDA DE LOS RADIOS. SE REALIZA LIMPIEZA INTERNA DEL SISTE,A OCULAR Y SE EFECTUAN PRUEBAS DE FUNCIONAMIENTO JUNTO CON EL PERSONAL MEDICO.\r\nEL EQUIPO SE ENTREGA EN OPTIMAS CONDICIONES FISICAS DE FUNCIONAMIENTO.', '21537', '2021-03-18 ', 'no', '', 15, NULL),
