(1626, NULL, 1, 4, 'b066dab271283deacc36700b1feade2a.pdf', NULL, 'REVISAR. REQUIERE PRUEBAS DE FUNCIONAMIENTO.', '2021-02-03 ', '19785', NULL, NULL, NULL, 'SE REALIZA UNA INSPECCIÓN FÍSICA Y VISUAL DEL FUNCIONAMIENTO DE LA BANDA PLASTICA, PULSADORES, FUSIBLE, COMPONENTES ELECTRONICOS, DONDE SE OBSERVA UN CORRECTTO FUNCIONAMIENTO. EQUIPO OK.', '19785', ' null', 'no', '', 15, 3),
(1627, NULL, 1, 2861, 'd6e4286ecc2a4b4b0f7a04cf3ddfc6b6.pdf', NULL, 'REVISAR', '2021-03-17 ', '21574', NULL, NULL, NULL, 'SE ATIENDE LLAMADO PARA MANTENIMIENTO CORRECTIVO. SE REALIZA AJUSTE DE 2 TORNILLOS DE LA BASE, SE REALIZAN PRUEBAS DE FUNCIONAMIENTO. EL EQUIPO RESPONDE CORRECTAMENTE.', '21574', '2021-03-17 ', 'no', NULL, 15, NULL),
