(1629, NULL, 1, 992, '9bb7e38f12413f1b842be252c8f8955b.pdf', NULL, 'REVISAR', '2021-03-11 ', '21561', NULL, NULL, NULL, 'SE REALIZA UNA INSPECCIÓN FÍSICA Y VISUAL DEL FUNCIONAMIENTO, V´´ALVULAS, MANGUERAS, MOTORES, ILUMINACIÓN, DONDE SE EVIDENCIA ACOPLES BORDEN SUELTOS, SE REALIZA AJUSTE DE ACOPLES BORDEN EN PIEZA DE ALTA, BAJA.\r\nSE REALIZAN PRUEBAS DE FUNCIONAMIENTO EN TODA LA UNIDAD ODONTOLÓGICA, EQUIPO EN BUENAS CONDICIONES PARA SU FUNCIONAMIENTO.', '21561', '2021-03-11 ', 'no', NULL, 15, NULL),
(1630, NULL, 1, 2246, 'e357a86f5d0db4b82b1207a33a44fe0e.pdf', NULL, 'FAVOR REVISAR MONITOR DE SIGNOS VITALES, ESTE SE ENCUENTRA FALLANDO.', '2021-03-11 ', '13927', NULL, NULL, NULL, 'SE REALIZA INSPECCIÓN FISICA Y VISUAL DEL EQUIPO, VERIFICACIÓN DE TARJETAS ELECTRONICAS, ACCESORIOS Y PULSADORES. EL EQUIPO PRESENTA ACCESORIOS (MANGUERA, BRAZALETE, SENSOR SPO2) SE REALIZARON PRUEBAS DE FUNCIONAMIENTO CONE QUIPO PATRON. SE REALIZA INSTALACION DE BRAZALETE ENTREGADO POR EL CLIENTE.', '21562', '2021-03-11 ', 'no', NULL, 15, NULL),
(1631, NULL, 1, 659, 'f82231211fd4dc335b13619727242a2d.pdf', NULL, 'SATURADOR NO FUNCIONA', '2021-03-11 ', '14057', NULL, NULL, NULL, 'SE REALIZA INSPECCIÓN VISUAL Y FÍSICA DE FUNCIONAMIENTO DONDE SE EVIDENCIA AUSENCIA DE SENSOR DE SPO2, SE REALIZA INSTALACIÓN DE SENSOR SPO2 NUEVO SUMINISTRADO POR EL CLIENTE Y SE EFECTUAN PRUEBAS DE FUNCIONAMIENTO, EL EQUIPO RESPONDE CORRECTAMENTE. EQUIPO OK.', '21565', '2021-03-11 ', 'no', NULL, 15, NULL),
(1632, NULL, 1, 2194, '9b2a2151a6f8de5fd6a6bcd1de13c220.pdf', NULL, 'SATURADOR AVERIADO', '2021-03-11 ', '14056', NULL, NULL, NULL, 'SE EVIDENCIA AUSENCIA DE SENSOR SPO2- SE REALIZA INSTALACION DE SENSOR SPO2 NUEVO SUMINISTRADO POR EL CLIENTE, SE EFECTUAN PRUEBAS DE FUNCIONAMIENTO DE SATURACION Y EL EQUIPO RESPONDE CORRECTAMENTE. EQUIPO OK.', '21564', '2021-03-11 ', 'no', NULL, 15, NULL),
(1633, NULL, 1, 223, 'dd72f17bc47c2b207d829a93f33ab53a.pdf', NULL, 'REVISAR', '2021-03-10 ', '13864', NULL, NULL, NULL, 'SE REALIZA INSPECCIÓN FISICA DE FUNCIONAMIENTO, TRANSDUCTOR, PULSADOR ON/OFF, SELECTOR DE VOLUMEN Y PUERTO DE CARGA. SE EJECUTA LIMPIEZA Y DESINFECCIÓN INTERNA Y EXTERNA.\r\nSE EVIDENCIA UN CORRECTO ESTADO DEL EQUIPO.', '21518', '2021-03-10 ', 'no', '', 15, NULL),
(1634, NULL, 1, 893, '66be15516e4e14630fbb8a84a718225c.pdf', NULL, 'NO SENSA FRECUENCIA CARDIACA', '2021-03-12 ', '14251', NULL, NULL, NULL, 'SE REALIZA REVISION, SIMULADOR PATRON EN PARAMETROS ECG Y SPO2. EQUIPO FUNCIONA OK. EQUIPO PENDIENTE DE SENSOR SPO2 (NO TIENE)', '14251', '2021-03-12 ', 'no', 'SENSOR SPO2', 15, 0),
(1635, NULL, 1, 860, 'f631bb8cdf47f55a437e7f9f4872c9ca.pdf', NULL, 'REVISAR MONITOR, NO SENSA DE MANERA ADECUADA TOMA DE ELECTROCARDIOGRAFIA DE FRECUENCIA CARDIACA', '2021-03-17 ', '13015', NULL, NULL, NULL, 'SE REVISA MONITOR CON PATRON.\r\nEQUIPO OK.', '13015', '2021-03-17 ', 'no', NULL, 15, NULL);
