(1636, NULL, 1, 2431, 'b62ba819494a071750f18420e44459fb.pdf', NULL, 'TIENE LA LUZ DE MENOR CALIDAD A LA HABITUAL', '2021-03-18 ', '14255', NULL, NULL, NULL, 'SE REALIZA MANTENIMIENTO CORRECTIVO, SE AJUSTAN LENTES INTERNOS, SE REALIZAN PRUEBAS DE FUNCIONAMIENTO, EL EQUIPO RESPONDE CORRECTAMENTE, SE ENTREGA EL EQUIPO EN BUENAS CONDICIONES FISICAS Y OPERATIVAS. \r\nSE RECOMIENDA NO DEJAR CAER EL EQUIPO POR QUE ESTO CAUSA UN MOVIMIENTO EN LOS LENTES.', '21533', '2021-03-18 ', 'no', NULL, 15, NULL),
(1637, NULL, 1, 273, '5ed9b814b9447a36d44da3524a948181.pdf', NULL, '', '2021-03-12 ', 'ELECTROCARDIOGRAFO NO IMPRIME', NULL, NULL, NULL, 'SE ATIENDE POR MEDIO DE ORDEN DE TRABAJO DEL DAÑO DE EL ELECTROCARDIOGRAFO.\r\nSE REALIZA INSPECCIÓN FISICA Y ESTRUCTURAL. SE VERIFICA FUNCIONAMIENTO Y EL EQUIPO NO IMPRIME, SE REVISA LA IMPRESORA Y SE EVIDENCIA DAÑO EN LA TAPA DE LA IMPRESORA. SE REALIZA CAMBIO DE TAPA DE IMPRESORA DE UN ELECTROCARDIOGRAFO MARCA GENERAL ELECTRIC MODELO MAC 600, SERIE SP417440049PA QUE SE ENCUENTRA FUERA DE SERVICIO EN EL TALLER DE MANTENIMIENTO. SE REALIZA LIMPIEZA INTERNA Y EXTERNA DEL EQUIPO Y SE EFECTUAN PRUEBAS DE FUNCIONAMIENTO CON EQUIPO APTRON. EQUIPO \"OK\"\r\nLA REPARACIÓN ES TEMPORAL POR LO CUAL SE SOLICITA AL AREA DE COMPRAS COTIZACION DE LA TAPA DE LA IMPRESORA.', '21576', '2021-03-17 ', 'no', 'TAPA DE LA IMPRESORA', 15, 0),
