(1687, NULL, 1, 5720, 'ddd449a664258d10d0200e36de3661f1.pdf', NULL, 'REVISAR POR FAVOR, NO FUNCIONA LA LUZ', '2021-03-24 ', '14128', NULL, NULL, NULL, 'SE ENCONTRÓ BOMBILLO EN MAL ESTADO, SE REALIZO CAMBIO DE BOMBILLO ENTREGADO POR EL CLIENTE, SE REALIZARON PRUEBAS DE FUNCIONAMIENTO, SE ENTREGA EQUIPO EN OPTIMAS CONDICIONES.\r\nSE REALIZA ENTREGA DE EQUIPO EN OPTIMAS CONDICIONES.', '21538', '2021-03-24 ', 'no', '', 15, NULL),
(1688, NULL, 1, 280, '79333ddb9c15d7abb5cea6181a5ba195.pdf', NULL, 'LLAMADO VERBAL POR PARTE DE LA INGENIERA NATALIA PEDREROS.', '2021-03-25 ', 'NO REGISTRA', NULL, NULL, NULL, 'SE EVIDENCIA FRACTURA DEL POLO A TIERRA DE LA CLAVIJA DE LA UPS, REQUIERE REEMPLAZO DEL CABLE DE PODER A LA UPS. SE REALIZA INSTALACIÓN DEL CABLE DE PODER A LA UPS. SE APLICAN PRUEBAS DE FUNCIONAMIENTO. EQUIPO OK. SE RECOMIENDA CAMBIO DE UPS.\r\nSE APLICAN PRUEBAS DE FUNCIONAMIENTO. EQUIPO OK.\r\nSE RECOMIENDA CAMBIO DE LA UPS DEBIDO A QUE PRESENTA FALLA EN LAS BATERIAS Y DESGASTE EN LA CARCASA.\r\n', '21583', '2021-03-25 ', 'no', NULL, 15, NULL),
(1689, NULL, 1, 2431, '942858e86b513076fb65f72a1f773bd8.pdf', NULL, 'POR FAVOR ARREGLO DE FRONTOLUZ URGENTE.', '2021-03-23 ', '13032', NULL, NULL, NULL, 'SE EVIDENCIA QUE EL LENTE OCULAR ESTA SUELTO. EL EQUIPO SE TRASLADA AL TALLER DE MANTENIMIENTO BIOMEDICO PARA SU REPARACION.\r\nSE REALIZA LIMPIEZA DE LENTE OCULAR Y SE REALIZA TRATAMIENTO POR MEDIO DE PEGANTE GRADO MEDICO. SE VERIFICA FUNCIONAMIENTO Y SE EVIDENCIA DAÑO EN EL CONECTOR DE INTENSIDAD DE LUZ AL CUAL SE LE REALIZA AJUSTE CON SOLDADURA. SE EFECTUAN PRUEBAS DE FUNCIONAMIENTO Y EL EQUIPO RESPONDE CORRECTAMENTE.\r\n', '21541', '2021-03-25 ', 'no', NULL, 15, NULL),
(1690, NULL, 1, 409, '95a90211b9c7bd2ed277b8ff94fa3cac.pdf', NULL, 'NO FUNCIONAN ELECTRODOS DE ESTIMULACION.', '2021-03-19 ', '14256', NULL, NULL, NULL, 'SE EVIDENCIA AISLAMIENTO DEL CONECTOR CON RESPECTO AL CABLE. SE REALIZA TRATAMIENTO POR MEDIO DE SOLDADURA DE ESTAÑO AL CABLE, SE APLICAN PRUEBAS DE FUNCIONAMIENTO. EQUIPO OK.', '21581', '2021-03-24 ', 'no', '', 15, NULL),
(1691, NULL, 1, 877, 'fafa5ed37946b698c16f038462c6102c.pdf', NULL, '\"NO TOMA PRESION\"', '2021-04-08 ', '14439', NULL, NULL, NULL, 'SE REALIZA REVISION DEL EQUIPO, ESTE INSUFLA, PERO SE DETECTA QUE LA NIBO ESTA PROGRAMADA EN UNIDADES KPA LO QUE OCASIONA DATOS PEQUEÑOS, SE DEJA EQUIPO CON UNIDADES MMHG.', '14439', '2021-04-08 ', 'no', NULL, 15, NULL),
(1692, NULL, 1, 881, '2f55a642ef7178fdbd28dcdd1f317eba.pdf', NULL, 'FAVOR REVISAR MONITOR DEL CUBICULO 3. NO PRENDE', '2021-04-06 ', '14566', NULL, NULL, NULL, 'SE REALIZA REVISION DE MONITOR UCI URGENCIAS CON SIMULADOR PATRON PROSIM 8, EQUIPOR OK.', '14566', '2021-04-06 ', 'no', NULL, 15, NULL),
(1693, NULL, 1, 3377, '418ff38f07bcaa3b384692c959d0fce6.pdf', NULL, '\"ESTA DESCALIBRADA\"', '2021-03-16 ', '12785', NULL, NULL, NULL, 'SER REALIZA VERIFICACIÓN DE EQUIPO Y SE ENCUENTRA EN BUENAS CONDICIONES DE FUNCIONAMIENTO.\r\nNO ES  \"DESCALIBRADA\" SE COMPRUEBA AJUSTE Y SE ENCUENTRA FUNCIONANDO CORRECTAMENTE,', '12785', '2021-03-16 ', 'no', NULL, 15, NULL),
(1694, NULL, 1, 269, '9310f792e99b2450c7bf15cdd7ac2f2b.pdf', NULL, '\"NO IMPRIME\"', '2021-04-08 ', '14262', NULL, NULL, NULL, 'SE EVIDENCIAN CHUPAS EN MAL ESTADO CON PRESENCIA DE OXIDO Y GEL, SE CAMBIAN CHUPAS POR NUEVAS.\r\nSE RECOMIENDA EN EL SERVICIO LA LIMPIEZA DE LAS CHUPAS DESPUES DE CADA USO. EQUIPO OK.', '14262', '2021-04-08 ', 'no', NULL, 15, NULL),
(1695, NULL, 1, 280, '893f9f2c3ca0a0876ec7c62a66d0458c.pdf', NULL, 'REQUIERE ASISTENCIA TECNICA POR PARTE DEL PROVEEDOR', '2021-04-07 ', '59041', NULL, NULL, NULL, 'SE REALIZA ASISTENCIA TECNICA (REMOTA) CON EL REPRESENTANTE DE LA MARCA DONDE SE VERIFICA EL SOFTWARE POR MEDIO DE ASISTENCIA MEDICA, SE CORRIGEN FALLAS, SE REINICIA EL COMPUTADOR Y SE REALIZAN ESTUDIOS CON LOS OPERADORES DEL EQUIPO. QUEDA PENDIENTE EL BACK UP DEL EQUIPO YA QUE HACE FALTA UNA CONEXION MAS ESTABLE A INTERNET, MEDIANTE CABLE DE RED POR PARTE DEL CLIENTE HUV. EQUIPO FUNCIONALMENTE OK. REQUIERE CAMBIO DE ESTIMULADOR ELECTRICO.', '59041', '2021-04-07 ', 'no', 'ESTIMULADOR ELECTRICO', 15, NULL),
(1696, NULL, 1, 713, 'f3aae4a33f97243dd6ef186f7f334fa7.pdf', NULL, 'REVISAR', '2021-04-07 ', '59042', NULL, NULL, NULL, 'SE EVIDENCIAN FALLAS TECNICAS DE LA BATERIA.\r\nSE INSTALA BATERIA USADA EN BUEN ESTADO SUMINISTRADA POR EL CLIENTE, SE APLICAN PRUEBAS DONDE SE OBSERVA UN BUEN FUNCIONAMIENTO, EQUIPO \"OK\".', '59042', '2021-04-07 ', 'no', NULL, 15, NULL),
(1699, NULL, 1, 702, 'b21f264cd3992e5c78730500d88848c6.pdf', NULL, 'REVISAR', '2021-04-09 ', '59045', NULL, NULL, NULL, 'SE REALIZA ENTREGA DE MONITOR PARA TRANSPORTE CON TODOS LOS ACCESORIOS COMPLETOS. SE VERIFICA FUNCIONALIDAD DE CADA UNO DE LOS PARAMETROS JUNTO CON EQUIPO PATRON Y EL EQUIPO RESPONDE CORRECTAMENTE. EQUIPO OK.', '59045', '2021-04-09 ', 'no', NULL, 15, NULL),
