(2339, NULL, 1, 1027, NULL, NULL, 'ONTRACT # PREVENTIVE LIMPIEZA EXTERNA, INSPECCION VISUAL, NINGUN \r\nHALLAZGO DE FLUIDOS Y SANGRE, SE VERIFICA EL EQUIPO ENCONTRANDO FALLAS \r\nEN LA FUENTE, AL REALIZAR ATG SE EVIDENCIA FALLA EN PSOL\'S DE AIRE Y O2.\r\nSE REQUIEREN ESTOS REPUESTOS PARA HABILITAR EL EQUIPO. PROXIMO \r\nMANTENIMIENTO : NOV 2024', '2024-08-05 ', '403086676', NULL, NULL, NULL, 'CONTRACT # PREVENTIVE LIMPIEZA EXTERNA, INSPECCION VISUAL, NINGUN \r\nHALLAZGO DE FLUIDOS Y SANGRE, SE VERIFICA EL EQUIPO ENCONTRANDO FALLAS \r\nEN LA FUENTE, AL REALIZAR ATG SE EVIDENCIA FALLA EN PSOL\'S DE AIRE Y O2.\r\nSE REQUIEREN ESTOS REPUESTOS PARA HABILITAR EL EQUIPO. PROXIMO \r\nMANTENIMIENTO : NOV 2024', '403086676', '2024-08-05 ', 'no', NULL, 15, 0),
