(1897, NULL, 1, 698, 'ce2002e5c11991fbbf233e51cc7a2f26.pdf', NULL, 'ARREGLO PULSIOXIMETRO DEL MONITOR', '2021-09-03 ', '2573', NULL, NULL, NULL, 'SE VERIFICA ESTADO DEL SENSOR DE SATURACIÓN, ENCONTRANDO QUE MUESTRA VALORES SIN ESTAR CONECTADO A PACIENTE. SE REALIZA CAMBIO DE SENSOR DE SATURACIÓN. EL EQUIPO QUEDA OPERANDO EN ÓPTIMAS CONDICIONES.', 'SIN CODIGO', '2021-09-03 14:30', 'no', '', 15, NULL),
(1898, NULL, 1, 337, NULL, NULL, 'Gammacamara bloqueada', '2021-09-01 ', '1234', NULL, NULL, NULL, 'Se realizó revisión general del sistema .Se realizó la adquisición de Control de Calidad. Se\r\nobserva en el D1 que el pico de TC99 se ha corrido a 137 keV. En el D2 hay daño grave pues\r\nel pico de energia para Tc99 esta por debajo de 100 KeV.De entrada se observa que la fuente\r\nde alta del D2 tiene problemas pues genera un valor muy por debajo del esperado. Se\r\nintercambiaron las fuentes de alta. Con esto el problema cambia de detector, por lo tanto la\r\nfuente de alta del D2 debe ser reemplazada.Se realizo: Ajuste de fotomultiplicadores,\r\nCorrección de Energía y Uniformidad en el D1.Adquisición de Control de calidad con\r\nexcelentes resultados en D1.De manera intermitente, se presenta problema con el PSD, el cual\r\nse activa y desactiva. Esto es debido a que el sistema detecta un problema en el PSD del D2.\r\nEsto ocurre cuando el equipo tiene instalados los señuelos. Por lo tanto es necesario\r\nreemplazar el switch y cable del señuelo 2.', '06158634', '2021-09-01 ', 'no', NULL, 15, NULL),
(1899, NULL, 1, 337, NULL, NULL, 'El servicio reportó bloqueo general del equipo.', '2021-09-06 ', '1234', NULL, NULL, NULL, 'Ya en el sitio se encuentra que no es posible realizar ningún movimiento. El sistema trata de\r\ninicializar los movimientos pero no le es posible. se realizaron pruebas y verificaciones de todos\r\nlas posiciones límites. Se realizó una reinicialización general del sistema. Se comprobó que\r\ntodos los movimientos se realizan normalmente. Se realizó la inicialización de todos los\r\nmovimientos.', '06158634', '2021-09-06 ', 'no', NULL, 15, NULL),
(1900, NULL, 1, 1842, 'e547c0b308940376cd975bc4436e1f72.pdf', NULL, 'Reportan desde el servicio baja intensidad de luz con el videoprocesador', '2021-08-18 ', 'F465-21', NULL, NULL, NULL, 'Se realiza verificación técnico funcional del equipo, se configura el IRIS a AVE para mayor intensidad en la imagen, el equipo se encuentra en optimas condiciones de funcionamiento', 'F465-21', '2021-08-18 ', 'no', '', 15, NULL),
(1901, NULL, 1, 390, 'e6d58720e5270d278b68d20ca3188924.pdf', NULL, '\"LLAMADO VERBAL: LA INCUBADORA SE SOBRECALIENTA\"', '2021-07-06 ', '4115', NULL, NULL, NULL, 'EL EQUIPO QUEDA FUNCIONANDO CORRECTAMENTE, DESPUES DE REALIZARLE VARIAS PRUEBAS DE TEMPERATURA POR ESPACIO DE 10 HORAS.', '4115', '2021-07-06 ', 'no', NULL, 15, NULL),
(1902, NULL, 1, 467, '5de07c12a52f6d4e06561b4ecca14307.pdf', NULL, '\"LLAMADO VERBAL\"..', '2021-08-30 ', '61725.', NULL, NULL, NULL, 'SE REALIZA UNA INSPECCION FISICA Y VISUAL DEL FUNCIONAMIENTO DEL SISTEMA DE VENTILACION MECANICO, MANUAL Y PANTALLA FRONTAL, PULSADORES, DONDE SE EVIDENCIA UN BUEN ESTADO. SE APLICAN PRUEBAS EN DIFERENTES PARAMETROS DE VENTILACIÓN, SE ENTREGA EQUIPO EN BUENAS CONDICIONES FISICAS Y OPERATIVAS.', '61725', '2021-08-30 ', 'no', '', 15, 7),
