(1904, NULL, 1, 4012, '74676f564a958f424c1cf943f5af0e54.pdf', NULL, '\"LLAMADO VERBAL\"', '2021-08-19 ', '61678', NULL, NULL, NULL, 'SE REALIZA INSPECCION FUNCIONAL Y ESTRUCTURAL DEL SISTEMA MECANICO, SE AJUSTA AL INICIO DE LA MEDIDA EN CERO, GALGAS EXTENSIOMETRICAS Y SE REALIZA LIMPIEZA INTERNA Y EXTERNA, LUBRICACIÓN DE PARTES MECANICAS. SE EFECTUAN PRUEBAS DE FUNCIONAMIENTO CON MASAS PATRON A CARGAS ALTAS, MEDIAS Y BAJAS. EL EQUIPO SE ENCUENTRA EN OPTIMAS CONDICIONES FISICAS Y DE FUNCIONAMIENTO. EQUIPO OK.', '61678', '2021-08-19 ', 'no', NULL, 15, NULL),
