(1911, NULL, 1, 991, 'd61dce3ed46410764d8ec3d6df77cd94.pdf', NULL, 'LLAMADO VERBAL', '2021-09-01 ', '61853', NULL, NULL, NULL, 'SE INSTALÓ MÓDULO DE ESCUPIDERA, SE REVISARON LOS SITEMAS ELECTRÓNICO Y NEUMÁTICO, EL MÓDULO DE PIEZAS REQUIERE CAMBIO, LOS MOTORES DE MOVIENTO SE ENCUENTRAN MALOS, SE REQUIERE PINTURA PARA BASE DE LA UNIDAD.', '61853', '2021-09-01 ', 'no', 'MÓDULO DE PIEZAS, MOTORES DE MOVIMIENTO, BOQUILLA DEL EYECTOR, PINTURA DE BASE DE LA UNIDAD,ACRÍLICO', 15, NULL),
(1912, NULL, 1, 992, '49f44ac6d48e35149f186fa58e4bb331.pdf', NULL, 'LLAMADO VERBAL', '2021-08-30 ', '61855', NULL, NULL, NULL, 'SE INSTALÓ MÓDULO ESCUPIDERA, SE REUIERE CAMBIO EN MÓDULO PIEZAS, SE REQUIERE PINTURA PARA BASE DE UNIDAD, SE REVISARON SISTEMAS NEUMÁTICO Y ELECTRÓNICO, LOS MOTORES DE MOVIMIENTO SE ENCUENTRAN MALOS, UNIDAD DE FUNCIONAMIENTO OK.', '61855', '2021-08-30 ', 'no', 'MÓDULO DE PIEZAS, MOTORES DE MOVIMIENTO, BOQUILLA DEL EYECTOR, PINTURA DE BASE DE LA UNIDAD,ACRÍLICO', 15, 0),
