(1914, NULL, 1, 2087, '669ef15b6b0f369a7bc624f3d0b62497.pdf', NULL, 'No censa la presión arterial, dice \"Falla en el sistema\".', '2021-08-27 ', '0682', NULL, NULL, NULL, 'SE REALIZÓ EL RESPECTIVO MANTENIMIENTO, SE HIZO REVISIÓN FUNCIONAL Y ESTRUCTURAL, LIMPIEZA INTERNA Y EXTERNA, SISTEMA ELECTRÓNICO, NEUMÁTICO Y PULSADORES OK, SE REALIZÓ CAMBIO DEL CONECTOR SUMINISTRADO POR EL CLIENTE AL EVIDENCIAR EL DAÑO DEL PULSADOR DEL NIBP, SE COMPROBÓ EL BUEN FUNCIONAMIENTO DEL EQUIPO CON LAS PRUEBAS DEL PATRÓN DE PRESIÓN, EL EQUIPO QUEDÓ OK.', '61721', '2021-08-27 ', 'no', '', 15, 0),
(1915, NULL, 1, 210, 'cd446c53eb46c742fd3b6c6e77eb2a4e.pdf', NULL, 'NO DEJA HACER PRUEBA DE USUARIO.', '2021-08-30 ', '2129', NULL, NULL, NULL, 'SE REALIZÓ INSPECCIÓN FUNCIONAL Y ESTRUCTURAL DEL SISTEMA Y DE LOS ACCESORIOS, NO SE PRESENTÓ LA FALLA DE LA PRUEBA DE USUARIO, SE VERIFICÓ QUE NO SE PRESENTA ERROR Y QUE IMPRIME CORRECTAMENTE.', '61724', '2021-08-30 ', 'no', '', 15, NULL),
(1916, NULL, 1, 2192, 'f00528fa859aad625496893f2e288d82.pdf', NULL, 'EL EQUIPO NO TOMA PRESIÓN ARTERIAL.', '2021-09-20 07:10', '2339', NULL, NULL, NULL, 'SE REALIZA REVISIÓN DE PARÁMETROS ENCONTRANDO FUGA EN BRAZALETE. SE INSTALA ACCESORIO NUEVO, DEJANDO EL EQUIPO EN OPTIMAS CONDICIONES.', 'SIN CODIGO', '2021-09-20 07:45', 'no', NULL, 15, NULL),
(1918, NULL, 1, 698, '20a8748efdbce4992cab1b44567dfec7.pdf', NULL, 'NO TOMA PRESIÓN NO INVASIVA, TIENE SUELTO EL CONECTOR ', '2021-09-03 ', '2574', NULL, NULL, NULL, 'SE REALIZA EL RESPECTIVO MANTENIMIENTO, SE INSPECCIONÓ A NIVEL FUNCIONAL Y ESTRUTURAL, SE LIMPIÓ INTERNA Y EXTERNAMENTE, SISTEMA ELECTRÓNICO Y NEUMÁTICO OK, SE AJUSTÓ CONECTOR DEL PULSADOR DEL NIBP POR EVIDENCIA DE FALLA EN ESTE, EL EQUIPO QUEDÓ OK.', '61740', '2021-09-06 ', 'no', NULL, 15, NULL),
(1919, NULL, 1, 181, '4ef36eac8b3c16b6258956b63658e3f2.pdf', NULL, 'LLAMADO VERBAL.', '2021-09-08 ', '61821', NULL, NULL, NULL, 'SE REALIZÓ INSTALACIÓN DE CABLE EKG NUEVO, SE EFECTUARON PRUEBAS DE FUNCIONAMIENTO Y EL EQUIPO QUEDÓ OK.', '61821', '2021-09-08 ', 'no', NULL, 15, NULL),
(1920, NULL, 1, 694, 'dab8759dd27a2315bec4520d4a138f56.pdf', NULL, 'REVISIÓN COMPLETA DEL EQUIPO Y BRAZALETE, NO REGISTRA SATURSCIÓN DE OXÍGENO.', '2021-08-31 ', '2131', NULL, NULL, NULL, 'SE REALIZÓ EL RESPECTIVO MANTENIMIENTO, INSPECCIÓN FUNCIONAL Y ESTRUCTURAL DEL EQUIPO, LIMPIEZA INTERNA Y EXTERNA, SE RECTIFICÓ EL FUNCIONAMIENTO DEL PULSADOR DE NIBP, SE CAMBIÓ BRAZALETE POR PRESENTAR DAÑO, SE CAMBIÓ LA BATERÍA  Y SE HICIERON LAS RESPECTIVAS PRUEBAS DE FUNCIONAMIENTO DEL EQUIPO CONECTADO A LA RED Y DESCONECTADO DE ESTA, SE INSTALÓ SENSOR DE SPO2, PANTALLA OK, EQUIPO OK.', '61729', '2021-08-31 ', 'no', '', 15, NULL),
(1921, NULL, 1, 991, '50afa2b64190b9fe329710a033b733c0.pdf', NULL, 'LLAMADO VERBAL.', '2021-09-01 ', '61854', NULL, NULL, NULL, 'SE REALIZÓ VERIFICACIÓN DE LA PIEZA ALTA PARTES MECÁNICAS, TURBINA, EL ACOPLE MANDRIL SE ENCUENTRA PEGADO, SE AJUSTA Y LUBRICA EL MANDRIL, PIEZA DE ALTA EN OPTIMAS CONDICIONES PARA SU FUNCIONAMIENTO.', '61854', '2021-09-01 ', 'no', NULL, 15, NULL),
(1924, NULL, 1, 2226, '664d878f3580b085c061fca2b16b88dc.pdf', NULL, 'EL ELECTROCARDIOGRAFO NO IMPRIME.', '2021-09-23 ', '2340', NULL, NULL, NULL, 'SE REALIZA INSPECCION DE PORTE FUNCIONAL Y SE EVIDENCIA QUE LA IMPRESORA FALLA, SE RETIRA EL PAPEL Y SE RETIRA EL RODILLO DE LA TAPA SE CAMBIA DE POSICION Y SE VERIFICA FUNCIONAMIENTO DE LA IMPRESION Y EL EQUIPO RESPONDE CORRECTAMENTE. EQUIPO OK.', '62121', '2021-09-23 ', 'no', NULL, 15, NULL),
(1925, NULL, 1, 2428, '6a02a95d7b90ea83aa39ee1bc352658e.pdf', NULL, 'DAÑO DEL FOCO Y CABLE QUE UNE CON BATERIA SE ENTREGA SIN CABLE DE PODER.', '2021-09-21 ', '0273', NULL, NULL, NULL, 'EN LA REVISION DEL EQUIPO SE EVIDENCIA EL CONECTOR. Y EL CABLE QUE SE CONECTA A LA BATERIA ESTAN SUELTOS. SE SUELTA EL CONECTOR Y SE SOLDAN LOS CABLES Y SE PEGA.', '62114', '2021-09-21 ', 'no', NULL, 15, NULL),
(1926, NULL, 1, 1909, 'd131c093e1bf4a76f5b81903002219d9.pdf', NULL, '\"LLAMADO VERBAL\"', '2021-09-01 ', '61841', NULL, NULL, NULL, 'SE REALIZA CAMBIO DE KIT DE 3 AÑOS NUEVO, SUMINISTRADO POR EL CLIENTE, ESTE KIT FUE SOLICITADO EN EL MANTENIMIENTO PREVENTIVO. \r\nSE INSTALAN FUELLE INTERO Y EXTERNO, EMPAQUES, VALVULAS, FILTROS Y BATERIAS. SE REALIZA LIMPIEZA, SE CALIBRAN VALVULAS Y SE EFECTUAN PRUEBAS DE FUGA EN EL SISTEMA Y PRUEBAS DE PARAMETROS JUNTO CON EQUIPO PATRON. EQUIPO OK.', '61841', '2021-09-01 ', 'no', '', 15, NULL),
(1927, NULL, 1, 466, '9fa5ca8effd2926192bd0e4dd8163eb8.pdf', NULL, '\"LLAMADO VERBAL\"', '2021-09-03 ', '61842', NULL, NULL, NULL, 'SE REALIZA CAMBIO DE KIT DE 3 AÑOS NUEVO, SUMINISTRADO POR EL CLIENTE, ESTE KIT FUE SOLICITADO EN EL MANTENIMIENTO PREVENTIVO. \r\nSE INSTALAN FUELLE INTERO Y EXTERNO, EMPAQUES, VALVULAS, FILTROS Y BATERIAS. SE REALIZA LIMPIEZA, SE CALIBRAN VALVULAS Y SE EFECTUAN PRUEBAS DE FUGA EN EL SISTEMA Y PRUEBAS DE PARAMETROS JUNTO CON EQUIPO PATRON. EQUIPO OK.', '61842', '2021-09-03 ', 'no', '', 15, NULL),
