(1929, NULL, 1, 707, '24f544d26a3486a33c4e03e0085899d3.pdf', NULL, '\"LLAMADO VERBAL\"', '2021-09-24 ', '62130', NULL, NULL, NULL, 'SE REALIZA ENTREGA DEL EQUIPO CON TODOS SUS ACCESORIOS FUNCIONALES, EN BUEN ESTADO FISICO Y DE FUNCIONAMIENTO. \r\nSE REALIZA LIMPIEZA EXTERNA Y LAS PRUEBAS DE FUNCIONAMIENTO SE EJECUTAN CON EQUIPO PATRON, EL EQUIPO RESPONDE CORRECTAMENTE. EQUIPO OK.', '62130', '2021-09-24 ', 'no', NULL, 15, NULL),
(1930, NULL, 1, 2025, '0ecbe1b6ff84eaeee7f0427a89ac23ff.pdf', NULL, '\"LLAMADO VERBAL\"', '2021-09-04 ', '61843', NULL, NULL, NULL, 'SE REALIZA CAMBIO DE KIT DE 3 AÑOS NUEVO, SUMINISTRADO POR EL CLIENTE, ESTE KIT FUE SOLICITADO EN EL MANTENIMIENTO PREVENTIVO. \r\nSE INSTALAN FUELLE INTERO Y EXTERNO, EMPAQUES, VALVULAS, FILTROS Y BATERIAS. SE REALIZA LIMPIEZA, SE CALIBRAN VALVULAS Y SE EFECTUAN PRUEBAS DE FUGA EN EL SISTEMA Y PRUEBAS DE PARAMETROS JUNTO CON EQUIPO PATRON. EQUIPO OK.', '61843', '2021-09-04 ', 'no', NULL, 15, NULL),
(1931, NULL, 1, 192, '6ffb1556dfe36a626f2aeae94fee8552.pdf', NULL, '\"LLAMADO VERBAL\"', '2021-09-29 ', '62257', NULL, NULL, NULL, 'SE REALIZA CAMBIO DE BATERIA NUEVA, SUMINISTRADA POR EL CLIENTE SE VERIFICA DESDE EL MENU QUE LA BATERIA QUEDE RESETEADA Y NUEVAMENTE SE REALIZA EL AUTOTEST DONDE SE COMPRUEBA QUE QUEDA INSTALADA LA BATERIA CORRECTAMENTE. EQUIPO OK.', '62257', '2021-09-29 ', 'no', NULL, 15, NULL),
(1932, NULL, 1, 2226, 'e9604260213b69b972db265145765c63.pdf', NULL, '\"LLAMADO VERBAL\"', '2021-09-08 ', '61823', NULL, NULL, NULL, 'SE REALIZA MANTENIMIENTO CORRECTIVO, INSPECCIÓN FUNCIONAL Y ESTRUCTURAL, LIMPIEZA GENERAL, SE EVIDENCIA QUE EL EQUIPO ESTA MAL CONFIGURADO. SE CONFIGURA EN EL MENU Y SE REALIZAN PRUEBAS DE FUNCIONAMIENTO CON EQUIPO PATRON. EL EQUIPO FUNCIONA CORRECTAMENTE SE ENTREGA AL SERVICIO EN BUENAS CONDICIONES PARA SU FUNCIONAMIENTO. EQUIPO OK.', '61823', '2021-09-08 ', 'no', NULL, 15, NULL),
(1933, NULL, 1, 993, 'c59fd26ab05d84255b7ae738ea4c0fff.pdf', NULL, '\"LLAMADO VERBAL\"', '2021-09-07 ', '61819', NULL, NULL, NULL, 'SE REALIZA MANTENIMIENTO CORRECTIVO, INSPECCION FUNCIONAL Y ESTRUCTURAL, LIMPIEZA GENERAL, SISTEMA ELECTRICO OK, SE EVIDENCIA FUGA EN MANGUERA DE AGUA, SE REALIZA CORRECCIÓN DE FUGA Y PRUEBAS DE FUNCIONAMIENTO. EL EQUIPO RESPONDE CORRECTAMENTE, EQUIPO OK.', '61819', '2021-09-07 ', 'no', NULL, 15, NULL),
(1934, NULL, 1, 739, '3d55ad00b09bcdbeaab5018aeef28e43.pdf', NULL, '\"LLAMADO VERBAL\"', '2021-09-16 ', '61850', NULL, NULL, NULL, 'SE REALIZA MANTENIMIENTO CORRECTIVO, INSPECCION FUNCIONAL Y ESTRUCTURAL, LIMPIEZA GENERAL, SISTEMA ELECTRONICO, NEUMATICO, PULSADORES, PANTALLA. SE EVIDENCIA FRACTURA DE CONECTOR DE SPO2, SE DESARMA EL EQUIPO, SE PEGA CONECTOR INTERNAMENTE, SE REALIZAN PRUEBAS DE FUNCIONAMIENTO EL EQUIPO RESPONDE CORRECTAMENTE, SE ENTREGA AL SERVICIO EN BUENAS CONDICIONES PARA SU FUNCIONAMIENTO. EQUIPO OK.', '61850', '2021-09-16 ', 'no', NULL, 15, NULL);
INSERT INTO `correctivos_generales` (`id`, `created_at`, `status`, `equipo_id`, `file`, `file_orden`, `orden`, `fecha_inicio`, `code_orden`, `diagnostico`, `code_diagnostico`, `fecha_diagnostico`, `description`, `code`, `fecha_mantenimiento`, `repuesto_pendiente`, `repuesto_id`, `cierre_id`, `tipo_falla_id`) VALUES
(1935, NULL, 1, 2560, '1787672218a04f37601c7fed6fb08e34.pdf', NULL, '\"LLAMADO VERBAL\"', '2021-09-14 ', '61846', NULL, NULL, NULL, 'SE REALIZA MANTENIMIENTO CORRECTIVO, INSPECCION FUNCIONAL Y ESTRUCTURAL, LIMPIEZA GENERAL, INFORMA EL SERVICIO QUE EL EQUIPO NO EXPULSA EL AGUA CORRECTAMENTE, SE REALIZA LIMPIEZA DE CONDUCTOS INTERNOS Y VALVULAS, SE REALIZAN PRUEBAS DE FUNCIONAMIENTO Y RESPONDE CORRECTAMENTE, SE ENTREGA AL SERVICIO EN BUENAS CONDICIONES PARA SU FUNCIONAMIENTO, EQUIPO OK.', '61846', '2021-09-14 ', 'no', NULL, 15, NULL),
(1936, NULL, 1, 683, 'b6a8038981453ab84609e0ded323fa83.pdf', NULL, '\"LLAMADO VERBAL\"', '2021-09-09 ', '61871', NULL, NULL, NULL, 'SE REALIZA UNA INSPECCION FISICA DEL MONITOR, DONDE REPORTAN QUE EL EQUIPO SE ESTA APAGANDO, SE APLICAN PRUEBAS DEL MONITOR SE OBSERVA QUE LA BATERIA SE ENCUENTRA EN MAL ESTADO, SE APLICA INSTALACIÓN DE LA BATERIA SUMINISTRADA POR EL CLIENTE, SE ENTREGA EQUIPO EN BUENAS CONDICIONES FISICAS Y OPERATIVAS. EQUIPO OK.', '61871', '2021-09-09 ', 'no', NULL, 15, NULL),
(1937, NULL, 1, 883, '057df94b96fac63c29229fc09288ca1c.pdf', NULL, '\"LLAMADO VERBAL\"', '2021-09-14 ', '61845', NULL, NULL, NULL, 'SE REALIZA MANTENIMIENTO CORRECTIVO, INSPECCION FUNCIONAL Y ESTRUCTURAL, LIMPIEZA GENERAL, SISTEMA ELECTRONICO Y NEUMATICO, SE EVIDENCIA QUE EL CONECTOR DE MANGUERA NIBP LO ACOPLARON A LA FUERZAM SE DESARMA MONITOR Y SE EXTRAE CONECTOR PARA SU REPARACION, SE REALIZARON PRUEBAS DE FUNCIONAMIENTO EL EQUIPO RESPONDE CORRECTAMENTE. EQUIPO OK.', '61845', '2021-09-14 ', 'no', NULL, 15, NULL),
(1938, NULL, 1, 606, 'ee0035b3d7b6c98afd07719b95c5e0ef.pdf', NULL, '\"POR FAVOR REVISAR MONITOR ESTA HACIENDO CORTO EN LA CONEXIÓN\"', '2021-09-16 ', '0672', NULL, NULL, NULL, 'SE APLICA REEMPLAZO DEL CABLE DE PODERM SUMINISTRADO POR EL CLIENTE, SE ENTREGA EQUIPO EN BUENAS CONDICIONES FISICAS Y OPERATIVAS EQUIPO OK.', '23224', '2021-09-17 ', 'no', NULL, 15, NULL),
(1939, NULL, 1, 771, '6bac5f1fa18e6bf416d1ba23548cc508.pdf', NULL, '\"LLAMADO VERBAL\"', '2021-09-24 ', '23256', NULL, NULL, NULL, 'MONITOR DE SIGNOS VITALES MARCA GOLDWAY MODELO UT7000C SERIE=CN7CABAS00069\r\nSE DEJO ESTE EQUIPO EN EL SERVICIO COMO MONITOR DE TRANSPORTE, SE ENTREGA CON LOS SIGUIENTES ACCESORIOS, CABLE EKG, SENSOR SPO2, MANGUERA NIBP, CABLE IBP, CABLE AC Y BRAZALETE, SE DEJA EN OPTIMAS CONDICIONES FISICAS Y OPERATIVAS.', '23256', '2021-09-24 ', 'no', NULL, 15, NULL),
(1940, NULL, 1, 272, 'd4c3f16a70b349f82a45ee4a89153a0e.pdf', NULL, '\"POR FAVOR REVISAR ELECTROCARDIOGRAFO SALA NEURO CX SALE ERROR.\"', '2021-09-24 ', '2778', NULL, NULL, NULL, 'SE REALIZA REVISION DE LA FALLA REPORTADA POR MEDIO DE ORDEN. EL ERROR QUE PRESENTA ES FALLA DE PAPEL. SE VERIFICA EL FUNCIONAMIENTO DE IMPRESORA, SE RETIRA EL PAPEL Y SE PONE EN LA POSICION CORRECTA PARA QUE EL SENSOR DETECTE AL MOMENTO DE IMPRIMIR. SE LE EXPLICA AL JEFE DE TURNO COMO SE INSERTA EL PAPEL DE MANERA CORRECTA Y SE EFECTUAN JUNTO CON EQUIPO Y EL EQUIPO RESPONDE CORRECTAMENTE.', '23257', '2021-09-24 ', 'no', '', 15, NULL),
(1941, NULL, 1, 529, NULL, NULL, 'Reportaron el equipo, ya que se apago en plena cirugía, el servicio sugiere que es a razón del pedal', '2021-09-27 ', 'NO REGISTRA', NULL, NULL, NULL, 'Se realiza limpieza de terminales sulfatadas, se cambia bombillo y se colca cubierta protectora al cable de conexión al pedal. El equipo queda en optimas condiciones de funcionamiento.\r\nAcción correctiva realizada por el ingeniero Julio Cesar Carrillo', 'SIN CODIGO', '2021-09-28 ', 'no', NULL, 15, NULL),
(1942, NULL, 1, 974, 'bb1b5e7e582d779a8859f17ac4c2f799.pdf', NULL, 'Se reporta sonido del gantry como si estuviera rotando el tubo, aun cuando el equipo no se está usando.', '2021-10-06 ', 'No registra', NULL, NULL, NULL, 'Ventiladores del lado derecho del equipo suenan mas de los normal, se cambian ambos ventiladores y el sonido ahora es normal.\r\nSe reemplazan los filtros de aire del gantry y el filtro de aire para el detector.\r\nSe nota que otro de los ventiladores opone mucha resistencia al movimiento, por lo que se solicitará ventilador para cambio.\r\nTambién, se solicitará el kit de grasas para el equipo, ya que no fue posible realizar la lubricación de la mesa debido a que no\r\nse encuentran grasas en sitio.\r\nPruebas funcionales exitosas', '80052806', '2021-11-12 ', 'no', '2 fans Ref.10891306 ', 15, 3),
(1943, NULL, 1, 2959, '08c886ea8e3118ac07d3c59fa2324aef.pdf', NULL, 'Se reporta mensaje que dice \" la comunicación con el IRD, el gantry y el SAI no se ha podido establecer o se ha interrumpido\" y el equipo no permite realizar estudios.', '2021-10-07 ', 'No registra', NULL, NULL, NULL, 'Se reviso errores y se detecto que el equipo tuvo un bajonazo de energía externa cuyo síntoma es desconexión del Gantry, la UPS y la IRS con una ventana de aviso pero cuando pasa el evento eléctrico muestra otro pantallazo informando que Gantry, UPS y la IRS están conectadas. No hay incidencia en el equipo y sigue operando normal.', 'No resgistra', '2021-10-07 ', 'no', NULL, 15, NULL),
(1944, NULL, 1, 991, 'c0b1f577ea18f92b82be1e839d2a8246.pdf', NULL, 'LLAMADO VERBAL', '2021-09-30 ', '62098', NULL, NULL, NULL, 'SE REALIZA MANTENIMIENTO CORRECTIVO, SE EVIDENCIA DAÑO EN LA PIEZA DE MANO, EL EQUIPO PRESENTA DAÑO NO SUJETA LA FRESA DEBIDO A QUE ESTA DAÑADO SHULZ, EL ENCARGADO DE SUJETAR. REQUIERE CAMBIO. LA PIEZA DE MANO QUEDA FUERA DE SERVICIO.', '62098', '2021-09-30 ', 'no', 'SHULZ', 15, 0),
(1945, NULL, 1, 5941, NULL, NULL, 'Reportan obstrucción del equipo', '2021-10-05 ', 'NO REGISTRA', NULL, NULL, NULL, 'El equipo es revisado por la Ingeniera Daniela de la empresa Jomedica, se realiza el proceso respectivo para eliminar la obstrucción y se dan recomendaciones al servicio sobre que elementos deben usarse para evitar la aparición de obstrucciones. El equipo queda completamente operativo.', 'SIN CODIGO', '2021-10-06 ', 'no', '', 15, NULL),
(1946, NULL, 1, 262, '833bec8d93c2385f30c9b7d293598f5b.pdf', NULL, 'LLAMADO VERBAL', '2021-09-29 ', '62085', NULL, NULL, NULL, 'SE REALIZA INSTALACION DE CABLE ECG, EQUIPO OK', '62085', '2021-09-29 ', 'no', NULL, 15, NULL),
