(1948, NULL, 1, 2071, '3da35bac63f0ca87c7200e51916a2444.pdf', NULL, 'LLAMADO VERBAL', '2021-09-29 ', '62087', NULL, NULL, NULL, 'SE EVIDENCIAN FALLAS TECNICAS DEL SENSOR DE SPO2, SE APLICA REEMPLAZO DEL SENSOR SUMINISTRADO POR EL CLIENTE. EQUIPO OK', '62087', '2021-09-29 ', 'no', NULL, 15, NULL),
