(2070, NULL, 1, 5588, NULL, NULL, 'Desde el servicio reportan obstrucción.', '2022-01-17 ', 'No registra', NULL, NULL, NULL, 'La ingeniera Daniela Galván realiza la respectiva revisión. Pruebbas de verificación de desempeño.\r\nSe identifica obstrucción en el nozzel por residuos de fibra del material con el que finalizan el secado del equipo. Por lo tanto se procedió a realizar cepillado de los canales de aire y agua y de la nariz de irrigación. Además se inyecto jabón enzimático y agua tibia obteniendo resultado satisfactorios quedando el equipo en optimas condiciones funcionales.', 'NO REGISTRA', '2022-01-17 ', 'no', NULL, 15, 3),
(2071, NULL, 1, 5965, NULL, NULL, 'Reportan el equipo por imagen borrosa.', '2021-12-22 ', 'NO REGISTRA', NULL, NULL, NULL, 'El equipo es revisado por la ingeniera Daniela Galvan. \r\nSe identifica equipo inundado.\r\nDado que este equipo es de la empresa queda pendiente la salida del mismo por lo que sale definitivamente del hospital.', 'NO REGISTRA', '2022-01-17 ', 'no', '', 16, 3),
