(2149, NULL, 1, 4293, NULL, NULL, '', ' ', '', NULL, NULL, NULL, 'Se realiza verificación de toma de llenado se encuentra tuerca desajustada, se ajusta y se realiza prueba de fugas a la toma de llenado en optimas condiciones. Se realizó correctivo de pintura a la base de la toma de llenado', '24076', '2021-11-05 ', 'no', NULL, 15, NULL),
(2252, NULL, 1, 233, '4beb3f82c323c7ad606fbee5fed7f0df.pdf', NULL, 'Se reporta daño en Trackball, transductor convexo y transductor endocavitario.', '2022-10-31 ', 'No registra', NULL, NULL, NULL, 'Se realiza instalación de las partes reportadas. Equipo queda funcional  y operativo en el servicio.', 'SIN CODIGO', '2022-10-31 ', 'no', NULL, 15, 2),
(2151, NULL, 1, 993, '082bf146ebbcde21f8fe7665a4019f74.pdf', NULL, 'Pieza N° 1 (00027901) con pin torcido. Pieza N° 2 (00010733) cambio de fresa girado', '2022-03-01 ', '13300', NULL, NULL, NULL, 'Previa limpieza y desinfección de las piezas de mano. Se realiza revisión de las piezas encontrando que la pieza N° 1 tiene el pin torcido y la pieza N° 2 cuenta con el cambiador de fresa girado. Pieza N° 2 se evidencia daño en shut que sujeta la fresa, se procede a reemplazar la turbina  completa por la de la pieza N° 1. \r\nPieza N° 2 queda funcionando correctamente. Pieza N° 1 queda fuera de servicio por daño de shut y pin doblado. Se entrega otra pieza de pulsador en contingencia', '00019', '2022-03-02 ', 'no', 'Acrilico, disipador, tapizado, manguera y pintura', 15, 3),
(2152, NULL, 1, 606, '0a5ccd9976cc4a81d7e66dbd3315214d.pdf', NULL, '\"El sensor no satura\" ', '2022-03-07 10:00', '4115', NULL, NULL, NULL, 'se reviso el equipo y se identifico que el sensor de saturacion de averio, se procedio a reemplazarlo por uno nuevo', '4115', '2022-03-07 12:00', 'no', NULL, 15, 2),
(2153, NULL, 1, 698, NULL, NULL, 'Al monitor le suena la alarma permanentemente y no cesa.', '2022-03-16 ', '0086', NULL, NULL, NULL, 'Se pone a trabajar el circuito con el simulador, se identifica que un latiguillo del EKG estaba presentando intermitencia, se procede a cambiar el latiguillo', '0086', '2022-03-16 ', 'no', '', 15, 2),
(2154, NULL, 1, 467, '0348c81f033c7b50560259d757c9246d.pdf', NULL, 'Toma presiones muy bajas', '2022-02-17 ', '1616', NULL, NULL, NULL, 'Se realiza mantenimiento preventivo dejándose equipo en optimas condiciones de funcionamiento. Se procede a cerrar correctivo', '', '2022-03-31 ', 'no', '', 15, 0),
(2155, NULL, 1, 2134, NULL, NULL, 'La lampara ingresa por que no enciende. ', '2022-03-17 16:00', '00063', NULL, NULL, NULL, 'Lampara es reportada por que no enciende, se revisa el cable de poder y se encuentra que esta en buen estado, se revisan los circuitos y se encuentra que el componente LM2596 no esta regulando.																																																									\r\n																																																									\r\nPor lo tanto se reemplaza la pieza y se cambia el led, se vuelve a probar la lampara y esta funciona correctamente, el equipo se entrega al servicio en buenas condiciones																																																									\r\n																																																									', '00063', '2022-03-22 16:00', 'no', '', 15, 7),
(2156, NULL, 1, 941, NULL, NULL, '', ' ', '', NULL, NULL, NULL, 'Presenta mensajes de error al montar el proceso, se realizan asistencia remota para encontrar la falla y resolver la avería, el equipo no responde a las acciones ejecutadas quedando fuera de servicio', '3844', '2022-02-10 ', 'no', '', 15, 3),
(2157, NULL, 1, 1114, '0e5dccfc1f17b56ee05b51076f1e51a0.pdf', NULL, 'EQUIPO SE REPORTA POR QUE NO SE QUEDA  FIJO EN LA MESA', '2022-03-28 ', '00096', NULL, NULL, NULL, ', SE REVISA EL EQUIPO Y SE IDENTIFICA QUE TIENE LE FALTAN LAS CHUPAS QUE LO MANTIENEN ESTABLE SOBRE LA MESA. SE LE ADECUA LA CARCASA DE OTRO VORTEX; EL EMCO1207 EL CUAL SE ENCUENTRA AVERIADO POR OTRO PROBLEMA, SE SACA DE SERVICIO EL OTRO VORTEX Y ESTE SE DEVUELVE AL SERVICIO EN BUEN ESTADO.', '00096', '2022-03-31 ', 'no', '', 15, 4),
(2158, NULL, 1, 2479, NULL, NULL, 'Equipo no funciona, ademas carece de cargador', '2022-03-28 ', '00000', NULL, NULL, NULL, 'Se desarma el equipo y se identifica que el rodamiento esta roto, ademas de que no tiene el cargador, se desmonta el equipo y se le cambia su carcaza al vortex EMCO3896, se retira el equipo del servicio', '00000', '2022-03-28 ', 'no', '', 15, 0),
(2159, NULL, 1, 6190, NULL, NULL, 'Reportan los ingnieros de sala de operaciones que el porcentaje de fugas del equipo se ha incrementado.', '2022-03-16 ', 'OTT-15783 17-3-2022', NULL, NULL, NULL, 'El equipo es revisado por el ingeniero Fabio de la empresa maquet. AL momento de la revisión el equipo pasa el control preliminar sin mas novedades.', 'OTT-15783 13-3-2022', '2022-03-17 ', 'no', '', 15, 0),
(2164, NULL, 1, 3870, 'a41b6dbdaae86e5f08c8b0e172e7cc1d.pdf', NULL, 'Reportan el servicio por guaya suelta', '2022-03-24 ', 'Guaya suelta', NULL, NULL, NULL, 'Posterior a la instalación de los elementos relacionados en la orden de compra y haber realizado la verificación funcional , pruebas de fuga, angulación, imagen, insuflación e irrigación se entrega equipo en el servicio en optimas condiciones funcionales', 'OS 1165', '2022-07-25 ', 'no', '', 15, 0),
(2165, NULL, 1, 5588, '92af70b5d93ae9d7466a151be6c655ab.pdf', NULL, 'Reportan equipo obstruido', '2022-03-17 ', 'no', NULL, NULL, NULL, 'Se realiza limpieza y utilizo agua tibia para destapar el equipo, equipo queda en optimas condiciones de funcionamiento.', 'SIN CODIGO', '2022-03-17 ', 'no', NULL, 15, 0),
(2161, NULL, 1, 1842, '683407d3aff8c1b5d20f004dd08adaee.pdf', NULL, 'Reportan imagen opaca con los equipos.', '2022-03-16 ', 'No registra', NULL, NULL, NULL, 'Por parte de la empresa jomedical se realiza limpieza generalizada del equipo dada imagen opaca, equipo queda en buenas condiciones.', 'SIN CODIGO', '2022-03-17 ', 'no', NULL, 15, 0),
(2162, NULL, 1, 1849, 'bff4bad238e04cd006ccc8fd07f19949.pdf', NULL, 'Se solicita inspección del equipo porque no se reconoce en el procesador', '2022-03-16 ', 'NO REGISTRA', NULL, NULL, NULL, 'Se limpian los pines con limpiador electrónico equipo queda en optimas condiciones operativas', 'SIN CODIGO', '2022-03-17 ', 'no', NULL, 15, 0),
(2163, NULL, 1, 3868, '70b5f0a1e5c7ceab796366cfbf13f4ef.pdf', NULL, 'Reportan empañamiento del equipo', '2022-02-20 ', 'No registra', NULL, NULL, NULL, 'Se realiza pruebas de fugas, inspección del equipo, pruebas en la torre , prueba de empañamiento. Se identifica equipo en buenas condiciones.', 'No registra', '2022-03-17 ', 'no', '', 15, 0),
(2167, NULL, 1, 3975, NULL, NULL, 'La vascula no pesa adecuadamente y no apaga																																																						', '2022-04-12 08:00', 'C0006', NULL, NULL, NULL, 'Se realiza limpieza del equipo. Se identifica que uno de los transductores de presion de la báscula esta desajustado, se procede a ajustar el transductor. Se hacen las pruebas de funcionamiento y el equipo	las pasa satisfactoriamente. El equipo enciende con un pulsador, pero no posee pulsador de apagado; por tanto, se le instala un switch de apagado. Se le hacen todas las pruebas técnicas con diferentes masas y el equipo las pasa satisfactoriamente. El equipo se devuelve al servicio funcionando de manera optima.																																																									\r\n', 'C0006', '2022-04-12 08:00', 'no', NULL, 15, 7),
(2168, NULL, 1, 1849, NULL, NULL, 'Equipo presenta fuga positiva', '2022-04-12 ', 'NO REGISTRA', NULL, NULL, NULL, 'Se realiza mantenimiento correctivo in sitio. Se retiro el cilindro, se hizo limpieza. Se coloco silicona ene el lente de luz. Equipo queda completamente funcional.', 'SIN CODIGO', ' ', 'no', '', 15, 0),
(2181, NULL, 1, 2192, '1314a2927055e9e3d93d896dbee6d047.pdf', NULL, 'Equipo no esta midiendo la presion no invasiva', '2022-04-18 16:00', 'C0014', NULL, NULL, NULL, 'Se realiza limpieza del equipo. Se hacen las pruebas correspondientes y se identifica que el acople de la manguera NIBP presenta una fuga hacia el brazalete. Se procede a instalar una manguera NIBP nueva de inventario. Se hacen las pruebas de funcionamiento de nuevo. El equipo responde correctamente. Se devuelve el equipo al servicio en optimas condiciones.																																	', 'C0014', '2022-04-18 15:00', 'no', NULL, 15, 4),
(2182, NULL, 1, 2959, '9e1a12e5dc4ca1e792aeb624f8191edd.pdf', NULL, 'Se reporta falla en conexion con el PACS', '2022-05-02 10:00', 'No registra', NULL, NULL, NULL, 'Se revisa secuencia de encendido y apagado del sistema, funcionamiento correcto.\r\nSe debe mantener discos de trabajo al 50% o menos (deseable) para mejorar el funcionamiento del equipo.\r\nPrueba con pacientes, prueba del Worklist y envío a PACS en el TOP OK\r\nEn el Now se debe actualizar la configuración del RIS ', 'No registra', '2022-05-03 13:32', 'no', NULL, 15, 3),
(2170, NULL, 1, 660, 'd89726b50beaa1d9abc659edb33da548.pdf', NULL, 'No funciona sistema, saturador, brazalete', '2022-04-13 ', '0274', NULL, NULL, NULL, 'Se realiza instalacion de brazalete nuevo. Se realizan pruebas de funcionamiento. El equipo pasa las pruebas adecuadamente.', '0274', '2022-04-13 ', 'no', '', 15, 2),
(2171, NULL, 1, 1735, '8e78cca0f77b01096806c008cd542900.pdf', NULL, 'Por mordida de paciente se fracturo el latiguillo', '2022-04-08 10:00', '1541', NULL, NULL, NULL, 'Se realiza cambio de latiguillos por unos disponibles de inventario biomedico', '1541', '2022-04-11 ', 'no', NULL, 15, 6),
(2172, NULL, 1, 2195, 'ff1c5c7e00790aa70604570dfb1d61c9.pdf', NULL, 'el monitor tiene problemas en el momento de censar la presion no invasiva. 																																						', '2022-04-05 10:00', 'C0003', NULL, NULL, NULL, 'Se recibe el monitor por que reporta problemas en el momento de censar la presion no invasiva. Se hacen pruebas con equipo patron y se evidencia que el equipo funciona correctamente, se prueban los accesorios de forma independiente y esos tambien pasan las pruebas de funcionamiento. Se entrega el equipo al servicio funcionando en optimas condiciones.																																																									\r\n', 'C0003', '2022-04-25 17:00', 'no', NULL, 15, 3),
