(2179, NULL, 1, 2193, '30ce95912e3cb01efcc711cbf973f775.pdf', NULL, 'NO TIENE SENSOR SPO2', '2022-03-14 ', '0080', NULL, NULL, NULL, 'Se verifico el funcionamiento del equipo y se evidencia que cuenta con sensor SpO2 funcional el cual fue entregado el 13/09/2022 en mantenimiento preventivo realizado.', '0080', '2022-09-13 ', 'no', 'SENSOR SPO2', 15, 2),
(2180, NULL, 1, 5922, 'eaca5f1db6de257f49f558d07b8572ec.pdf', NULL, 'monitor de signos con brazalete que no toma la presión, solo infla pero no arroja el reporte	', '2022-03-23 ', '1556', NULL, NULL, NULL, 'Mantenimiento correctivo realizado por IMPOCOR SAS. Se realiza revision tecnica funcional evidenciando lo comunicado, esto se debe a fallas en el modulo NIBP. Se realiza cambio del modulo NIBP, se instala dicho repuesto y se realizan pruebas de funcionales, evidenciando el buen funcionamiento del equipo.', '0000008568', '2022-04-25 ', 'no', '', 15, 7),
(2183, NULL, 1, 5708, NULL, NULL, 'TICKET 1385', '2022-02-01 07:41', '1385', NULL, NULL, NULL, 'El equipo se encuentra apagado , se realiza encendido y se evidencia que cuando envía el pulso de encendido a la unidad de refrigeración la protección de sobre tensión se activa, se verifican el sistema de arranque, condensador, tarjetas entre otros componentes y se determina falla de la unida de enfriamiento (compresor de refrigeración)\r\nEl equipo queda fuera de servicio.', '19626', '2022-02-01 ', 'no', NULL, 14, NULL),
(2184, NULL, 1, 769, '5e19f61affd742e936eb599b3c519c8c.pdf', NULL, 'REVISIÓN POR SOLICITUD DE NATALIA. EQUIPO EN TALLER.', '2022-04-05 ', 'Sin código', NULL, NULL, NULL, 'EL MONITOR ENCENDÍA PERO NO CARGABA INTERFACE. SE REALIZA CAMBIO DE MAIN BOARD.\r\nSE REALIZAN PRUEBAS DE FUNCIONAMIENTO Y ESTAS SON SUPERADAS SATISFACTORIAMENTE.', 'C0025', '2022-04-05 ', 'no', '', 15, 3),
(2185, NULL, 1, 695, '578698f3d57c8963099acf2335ad1f0c.pdf', NULL, 'REVISIÓN POR SOLICITUD DE NATALIA. EQUIPO EN TALLER.', '2022-04-05 ', 'Sin código', NULL, NULL, NULL, 'EL MONITOR ENCENDÍA PERO NO CARGABA INTERFACE. SE REALIZA CAMBIO DE PANTALLA.\r\nSE REALIZAN PRUEBAS DE FUNCIONAMIENTO Y ESTAS SON SUPERADAS SATISFACTORIAMENTE.', 'C0026', '2022-04-05 ', 'no', 'CABLE ECG. SENSOR SpO2. MANGUERA NIBP. BRAZALETE NIBP. CABLE AC. BATERÍA', 15, 3),
(2186, NULL, 1, 4893, '302a13798da40f5d0e288585cea20d3a.pdf', NULL, 'FALLA INTERMITENTE EN ALARMAS AUDITIVAS.', '2022-03-01 ', 'Sin código', NULL, NULL, NULL, 'SE REALIZA CAMBIO DE PARLANTE INTERNO.\r\nSE REALIZAN PRUEBAS DE FUNCIONAMIENTO.\r\nEQUIPO OPERATIVO', 'HUV0068', '2022-03-01 ', 'no', NULL, 15, 4),
(2187, NULL, 1, 694, NULL, NULL, 'Monitor de signos vitales solo funciona conectandolo con el cable de energia y se apaga.', '2022-05-05 10:00', '18813', NULL, NULL, NULL, 'Se inspeccion el equipo, se identifica que el cable de poder esta interrumpido. Se reemplaza el cable  de poder por uno nuevo. Se revisa  el estado de las baterias y se identifica que estan defectuosas, equipo requiere cambio de bateria.', '18813', '2022-05-05 10:00', 'no', 'Baterias', 15, 4),
(2188, NULL, 1, 2190, 'ee81d41e6dd8dfde5ab368b52c94a65f.pdf', NULL, 'Monitor con pantalla rota y sin accesorios', '2022-05-06 10:00', 'C0040', NULL, NULL, NULL, 'Equipo fue retirado del servicio por pantalla rota el 25-04-2022. Se realiza instalacion de pantalla, perilla, cable EKG,  y sensor SPO2 del monitor EMCO5536. Se realizan pruebas de funcionamiento. Equipo le falta tapa lateral y queda expuesto el interior. El equipo se devuelve al servicio en buenas condiciones.			', 'C0040', '2022-05-06 10:00', 'no', NULL, 15, 7),
(2189, NULL, 1, 915, NULL, NULL, 'SE SOLICITA REVISIÓN DE ESPECIALISTA DEL EQUIPO PARA VERIFICAR REPUESTOS QUE NECESITA.', '2022-05-01 ', 'C-626', NULL, NULL, NULL, 'SE REALIZA REVISION DE LOS DOS MONITORES FETALES, LOS CUALES SE EVIDENCIA USO CON PAPEL DIFERENTE MARCA AL FABRICANTE, LA RECOMENDACION ES REALIZAR USO CON PAPEL QUE RECOMIENDA FABRICA, SE REALIZA REVISION DE LOS DOS EQUIPOS CABEZALES TERMICOS Y SE EVIDENCIA EN BUEN ESTADO, SE REALIZA LIMPIEZA DE RODILLO Y CABEZAL DE LOS DOS EQUIPOS Y SE EVIDENCIA CON MUCHA SUCIEDAD DEBIDO AL PAPEL QUE MANEJA TIENE UNA TINTA LA CUAL PRODUCE QUE EL CABEZAL SE ENSUCIE Y PUEDA GENERAR LA MALA IMPRESION', 'C-626', '2022-05-04 ', 'no', NULL, 15, 6),
(2190, NULL, 1, 914, NULL, NULL, '', '2022-05-01 ', 'C-626', NULL, NULL, NULL, 'SE REALIZA REVISION DE LOS DOS MONITORES FETALES, LOS CUALES SE EVIDENCIA USO CON PAPEL DIFERENTE MARCA AL FABRICANTE, LA RECOMENDACION ES REALIZAR USO CON PAPEL QUE RECOMIENDA FABRICA, SE REALIZA REVISION DE LOS DOS EQUIPOS CABEZALES TERMICOS Y SE EVIDENCIA EN BUEN ESTADO, SE REALIZA LIMPIEZA DE RODILLO Y CABEZAL DE LOS DOS EQUIPOS Y SE EVIDENCIA CON MUCHA SUCIEDAD DEBIDO AL PAPEL QUE MANEJA TIENE UNA \r\nINSTALADA LA CUAL PRODUCE QUE EL CABEZAL SE ENSUCIE Y PUEDA GENERAR LA MALA \r\n IMPRESION', 'C-626', '2022-05-04 ', 'no', NULL, 15, 6),
(2191, NULL, 1, 915, '422c39726b675058c7b8c5b08a6adf97.pdf', NULL, 'El monitor fetal no imprime', '2022-05-13 10:00', 'C0047', NULL, NULL, NULL, 'El equipo se encontraba fuera de servicio por previo retro (errado) donde diagnostican que la impresora se encontraba averiada. Se realiza verificacion por parte de KAIKA el dia 04-05-22, quienes evidencian que el equipo solo requeria  limpieza de la impresora; rodillo y cabezal. Se realizan pruebas de funcionamiento y las pasa adecuadamente. Se le instalan transductor, toco (de almacen) y cable de poder. Equipo se devuelve al servicio funcionando correctamente.', 'C0047', '2022-05-13 11:00', 'no', NULL, 15, 7),
(2192, NULL, 1, 1849, 'de38a98c780d3580d1f5346b23e4d7f2.pdf', NULL, 'Reportan error 200223', '2022-05-11 ', 'Equipo no lo reconoce la torre', NULL, NULL, NULL, 'Se realiza limpieza de pines sulfatados', 'SIN CODIGO', '2022-05-11 ', 'no', NULL, 15, 0),
(2193, NULL, 1, 5913, '617c7a00ed4587bf31cf9a7f5dfb46ea.pdf', NULL, 'No se especifica causa de la revisión.', '2022-05-11 ', 'No registra', NULL, NULL, NULL, 'Se realiza inspección general dele quipo, se evidencian puntos en la imagen mas no fuga positiva.', 'SIN CODIGO', '2022-05-11 ', 'no', NULL, 15, 0),
(2194, NULL, 1, 6134, NULL, NULL, 'Reportan equipos en general equipos opacos en torre de endoscopia.', '2022-05-16 ', 'NO REGISTRA', NULL, NULL, NULL, 'Se hace limpieza del lente obteniendo resultados de imagen satisfactorios.', 'SIN CODIGO', '2022-05-16 ', 'no', NULL, 15, 0),
(2195, NULL, 1, 1849, '8071fb9bc7c96c4c3f70d90862f7718d.pdf', NULL, 'Reportan imagen opaca de los endoscopios en general', '2022-05-16 ', 'NO REGISTRA', NULL, NULL, NULL, 'Se realizan pruebas, se realiza limpieza del lente, equipo se encuentra completamente funcional', 'SIN CODIGO', '2022-05-16 ', 'no', NULL, 15, 0),
