(2198, NULL, 1, 1842, '54ca0ae6a8382def7a4c9e5f7c2bc353.pdf', NULL, 'Reportan que se apaga de manera intermitente.', '2022-05-11 ', 'NO REGISTRA', NULL, NULL, NULL, 'Se realiza verificación, del equipo y se identifica que el problema se asocia con una extensión. que en las condiciones en las que se encuentra no es la adecuada.', 'SIN CODIGO', '2022-05-11 ', 'no', NULL, 15, 0),
