(2200, NULL, 1, 5880, NULL, NULL, 'Equipo no prende', '2022-05-16 ', '0276', NULL, NULL, NULL, 'Se realiza limpieza, se enciende el equipo y este lo hace normalmente, Se deja el equipo encendido 1 hora con bateria y 1 hora conectado a la red electrica. El equipo funciona adecuadamente y se devuelve al servicio', '0276', '2022-05-16 ', 'no', '', 15, 7),
(2201, NULL, 1, 834, '778af701dbd8f78d4f552f3e16f56081.pdf', NULL, 'No enciende', '2022-05-13 12:00', '0313', NULL, NULL, NULL, 'Se realiza limpieza del equipo. Se realizan pruebas de funcionamiento. Se identifica que el cable de poder esta interrumpido. Se realiza cambio de cable de poder.', '0313', '2022-05-13 17:00', 'no', NULL, 15, 7),
(2202, NULL, 1, 584, 'c2c13d8d9261b7b00fd753bf85585d36.pdf', NULL, 'No toma la presion', '2022-05-13 10:00', '0312', NULL, NULL, NULL, 'Se realiza limpieza del equipo. Se realizan pruebas de funcionamiento sobre el modulo NIBP. Esperado 120/80 Medido 123/80. Esperado 60/30 Medido 62/32. Esperado 200/150 Medido 200/152. Se le instala brazalete y cable SPO2', '0312', '2022-05-13 10:00', 'no', NULL, 15, 7),
(2210, NULL, 1, 617, NULL, NULL, 'Equipo no toma la presion no invasiva adecuadamente. Equipo entrega valores erroneos cuando se usa el brazalete \r\n pediatrico', '2022-04-20 ', 'C0043', NULL, NULL, NULL, 'Se realiza cambio de tarjeta mainboard del modulo NIBP por una de inventario. Se realizan pruebas de NIBP con brazalete pediatrico teniendo como resultados: Esperado 120/80 medido 125/82. Esperado 60/30 medido 65/30. Esperado 80/50 Medido 82/50. Saturacion: Esperado 95% Medido 94%. esperado 90 Medido 91%: Equipo pasa las pruebas de funcionamiento adecuadamente. Equipo se devuelve al servicio en optimas condiciones.', 'C0043', '2022-05-13 ', 'no', '', 15, 7),
(2211, NULL, 1, 5878, NULL, NULL, 'Saturador no lee', '2022-05-27 10:00', '1361', NULL, NULL, NULL, 'Se verifica el funcionamiento del sensor, se identifica que la interfaz esta interrumpida pero el sensor esta en buen estado. Se  reemplaza la interfaz SPO2. Se hacen pruebas de funcionamiento y el equipo las pasa adecuadamente. Equipo se devuelve al servicio.', '1361', '2022-05-27 10:00', 'no', NULL, 15, 2),
(2204, NULL, 1, 942, 'fbe9ece73a4635917e97f7d849601f49.pdf', NULL, 'Equipo enciende pero se queda congelado. No cambia la imagen.																																																							\r\n																																																									', '2022-05-17 ', 'C0052', NULL, NULL, NULL, 'Se realiza limpieza del equipo. Se evidencia que el proyector enciende pero no cambia de imagen. Se evalua estado del control remoto. Control remoto en optimas condiciones. Se desmonta el equipo. Se revisa la fuente de poder y esta se encuentra en buen estado. Se realiza una prueba de funcionamiento instalando la tarjeta principal de otro equipo con las mismas caracteristicas. Equipo funciona correctamente con la otra tarjeta principal. Se evidencia que la tarjeta principal esta averiada. Se ensambla el equipo. Equipo queda fuera de funcionamiento por estado de la tarjeta principal.\r\n\r\nSe da de baja el equipo debido a los fallos presentados', 'C0052', '2025-04-30 ', 'no', '', 16, 7),
(2205, NULL, 1, 943, '13f27f3f1b6dbb8caacbe18c7d71dffb.pdf', NULL, 'Se solicita revisar proyector de optativos, debido a que se prende y apaga. Gracias', '2022-04-05 10:00', '18787', NULL, NULL, NULL, 'Se realiza limpieza del equipo. Se evidencia que el proyector no esta encendiendo. Se miden voltajes sobre el bombillo del equipo. Los voltajes son los correctos. Se identifica que el bombillo tipo led esta dañado. Se reeemplaza el bombillo tipo led por uno nuevo. Equipo se deja en el servicio de oftalmologia urgencia como reemplazo del proyector con serie 53887103.																																																									\r\n																																																									', 'C0051', '2022-05-17 10:00', 'no', NULL, 15, 7),
(2206, NULL, 1, 262, 'c148448740ae0ff2bf337f698847355c.pdf', NULL, 'Equipo no imprime bien. Se queda pegado a la hora de imprimir', '2022-05-19 08:00', 'C0054', NULL, NULL, NULL, 'Se realiza mantenimiento correctivo. Se realiza limpieza del equipo. El equipo se reporta debido a que se perdio el rodillo del papel, lo que dificulta el uso del dispositivo. Se le diseña un cilindro nuevo en metal. Se realizan pruebas de funcionamiento y se verifica que el rodillo quedo con las dimensiones correctas. Equipo se devuelve al servicio en optimas condiciones.', 'C0054', '2022-05-19 10:00', 'no', NULL, 15, 7),
(2207, NULL, 1, 6248, 'c17fd9f226ef323bdd81786455162950.pdf', NULL, 'Cambio de batería y ajuste de spam', ' ', '', NULL, NULL, NULL, 'Cambio de batería y ajuste de spam', '7347', '2019-08-23 ', 'no', '', 14, 2),
(2208, NULL, 1, 6259, '89f15f8ffb218d1dd7be7a16c421f871.pdf', NULL, '', ' ', '', NULL, NULL, NULL, 'CAMBIO DE CONTROL DE TEMPERATURA', '7200', '2020-05-19 ', 'no', NULL, 14, NULL),
(2209, NULL, 1, 6260, '5928eae3337bad9b0943d5b5be67ca6c.pdf', NULL, '', ' ', '', NULL, NULL, NULL, 'SE ASEGURA LAMINA DE LA CINTA TERMICA', '6550', '2020-09-08 ', 'no', NULL, 14, NULL),
(2212, NULL, 1, 4293, NULL, NULL, 'Indicador de nivel no funciona', '2022-05-13 ', 'sin codigo', NULL, NULL, NULL, 'Se realiza instalación de un nuevo indicador de nivel', '34159', '2022-05-28 ', 'no', NULL, 15, NULL),
(2213, NULL, 1, 2959, '931940e136138acae911b2876dc0f3d1.pdf', NULL, 'Se reporta que no enciende la Tablet del equipo', '2022-03-31 ', 'No registra', NULL, NULL, NULL, 'Se realiza instalación y configuración de la tablet G8 en el tomografo.\r\nPruebas funcionales exitosas.\r\nLa clave para el usuario es 123\r\nSe solicita control remoto y cable interno en el gantry, ya que se encuentran en mal estado. ', 'No registra', '2022-06-01 ', 'no', '', 15, 3),
(2214, NULL, 1, 2959, '541be072000b54b5ea348aa3effbab53.pdf', NULL, 'Durante la instalación de la tablet el 01 de junio de 2022, se evidencia daño del control remoto y del cable interno de este que viene dentro del Gantry.', '2022-06-01 ', 'No registra', NULL, NULL, NULL, '', '', ' ', 'no', NULL, 14, 0),
(2215, NULL, 1, 2095, NULL, NULL, 'La pesa no prende ', '2022-06-02 10:00', '1363', NULL, NULL, NULL, 'Se revisan los voltajes. Se identifica que el cargador esta interrumpido. Se destapa el cargador, se reparan las soldaduras, se ensambla de nuevo. Se realizan pruebas y el cargador queda funcionando. Equipo se devuelve al servicio funcional.', '1363', '2022-06-02 10:00', 'no', NULL, 15, 2),
(2216, NULL, 1, 1993, '0de223d6a263186a79ddd3c4916e4d15.pdf', NULL, 'Otoscopio falto de ajuste, esta arrojando doble foco de luz', '2022-06-06 10:00', 'C0064', NULL, NULL, NULL, 'Se evidencia que el otoscopio se encuentra falto de ajuste, ya que produce una luz doble. Se desensambla el equipo. Se realiza limpieza interna del equipo. Se ajustan los rodamientos. Se ensambla el equipo nuevamente. Equipo se devuelve funcional al servicio.																																																									\r\n																																																									', 'C0064', '2022-06-06 ', 'no', NULL, 15, 7),
(2217, NULL, 1, 5055, '6f9ae6eb4ca7acf0849689b6382ea315.pdf', NULL, 'Al equipo le falla la bateria, hay que mantenerlo conectado.', '2022-06-07 ', '3591', NULL, NULL, NULL, 'Se revisa la bateria, se evidencia que esta descargada. Se intenta cargar y se observa que se descarga demasiado rapido. Se requiere instalacion de bateria nueva. Se instala un cable de poder mas largo para mantener el equipo conectado en el servicio. Se evidencia que el saturador de SPO2 pediatrico esta en mal estado por desgaste.Se instala saturador de SPO2 pediatrico nuevo.', '3591', '2022-06-08 ', 'si', '', 15, 2),
(2218, NULL, 1, 689, '55e955331c9a26240d59e40cf4d8ddf0.pdf', NULL, 'Sensor de monitor Cama , presenta ritmo asistolico para censar frecuencia cardiaca', '2022-06-08 10:00', '0524', NULL, NULL, NULL, 'Se revisa el estado del equipo, se evidencia que esta en buen estado. Se revisa el estado de los latiguillos, se encuentran en buen estado igual. Se realizan pruebas de funcionamiento con simulador paciente. Esperado 60 lpm Medido 60 lpm. Esperado 130 lpm Medido 130 lpm. Esperado 40 lpm Medido 40 lpm. Equipo se deja funcional en el servicio.', '0524', '2022-06-08 15:00', 'no', NULL, 15, 3),
(2220, NULL, 1, 5876, NULL, NULL, 'Doppler ultrasonico no suena', '2022-06-22 ', 'C0079', NULL, NULL, NULL, 'Equipo es reportado debido a que no suena en el momento de medir la frecuencia cardiaca. Se identifica que el transductor esta funcionando correctamente. Se procede a desmontar el equipo. Se verifica que el parlante esta funcional de igual manera. Se observa que el potenciometro esta averiado. Se reemplaza el potenciometro por el del equipo con placa EMCO4094. Pendiente por dar de baja, por daño en la board. Se ensambla el equipo nuevamente. Se realizan pruebas de funcionamiento y el equipo las pasa adecuadamente.																									', 'C0079', '2022-06-22 ', 'no', NULL, 15, 7),
(2223, NULL, 1, 2944, 'bff26518ec7c7c26e55d7fac3e34790a.pdf', NULL, 'La lampara cielitica del angiografo no enciende. Se solicita que la revisen.																						', '2022-06-21 ', 'C0077', NULL, NULL, NULL, 'Se realiza mantenimiento correctivo. Se evidencia que el bombillo de la lampara cielitica no enciende. Se miden los voltajes y se evidencia que estan correctos. Se realiza reemplazo del bombillo por otro de 24V 50W. Se realizan pruebas y la lampara funciona adecuadamente.', 'C0077', '2022-06-21 ', 'no', NULL, 15, 4),
(2224, NULL, 1, 2113, '38da5b87d7a380cb65180d11a15fe6a7.pdf', NULL, 'La bascula se movio de sitio y necesita calibracion.', '2022-06-28 ', 'C0081', NULL, NULL, NULL, 'Previa limpieza y desinfección. se realiza verificacion. Verificación de sus componentes (Tallimetro, pesas, plataforma). Verificación y ajuste a “cero” de la báscula. Verificación de la báscula con pesos a cargas altas, medias y bajas. Se devuelve la bascula al servicio en optimas condiciones.', 'C0081', '2022-06-28 ', 'no', NULL, 15, 7),
(2225, NULL, 1, 2945, '8ba746abc27984f6262999561e34fc6f.pdf', NULL, 'Electrobisturi presenta fallas, aparece que no tiene buen contacto a la placa paciente, se cambia la placa paciente y sigue con el mismo error', '2022-06-23 ', 'C0080', NULL, NULL, NULL, 'El equipo es reportado debido a que presenta una alarma de baja conexión a la placa paciente. Se inspecciona el equipo. Se realizan pruebas de funcionamiento con equipo patrón Fluke QA-ES III. Se realizan las pruebas sobre los diferentes modos de funcionamiento. El equipo pasa todas las pruebas adecuadamente. El equipo se devuelve al servicio funcional.																																																				', 'C0080', '2022-06-23 ', 'no', NULL, 15, 7),
(2226, NULL, 1, 2944, 'ff20d91e1f5df128a4e864db567a8990.pdf', NULL, 'La fluoroscopia no se mostraba en el momento que se activaba, se desfasaba cuando se movía el tubo de rayos x.', '2022-07-05 ', '', NULL, NULL, NULL, 'Acciones correctivas: Se revisó el Log de errores y se encontró\r\nproblemas con el detector. Se realizó pruebas de\r\nintercomunicación y falló la comunicación del detector con la\r\nFDC, se verificó las fibras ok, se evidencia que las fibras de\r\ncomunicación x4 y x5 estaban cruzadas, se colocó en su posicion\r\ninicial y la comunicación quedó ok, los Rayos X quedaron\r\nhabilitados, se hizo carga del firmware del la board FDC OK, se\r\nrealizó adaptación de tubo ok, se encontró adicionalmente\r\nproblemas con el IPPC (Computador de imagen) y falla en en sus\r\ndiscos duros, se hizo limpieza de las memorias, tarjetas de red y\r\nde video, se hizo carga de la imagen del software al Host PC, se\r\nhizo carga del software del IPPC y se recreó los discos de imagen\r\nok, la aplicación subió sin novedad, se realiza pruebas con\r\nphantom de fluoroscopia y de adquisión y el equipo trabajó sin\r\nnovedad. se entrega equipo operativo y queda en monitoreo de su\r\nfuncionamiento tanto del IPCC, FDC y Detector. nota: el IPPC ha\r\nfallado en 2 ocasiones por lo cual se debe reemplazar, solicitará\r\neste repuesto con sus discos duros. Si la falla se vuelve a\r\npresentar se debe detener el equipo y esperar que lleguen los\r\nrepuestos.\r\nSe encontró problemas con la estación 3D, la motherBoard\r\npresenta falla, se debe reemplazar la CPU.\r\nla estación 3D queda fuera de servicio. se solicitará la CPU de la\r\nestación.', 'SIN CODIGO', '2022-07-09 18:30', 'no', NULL, 15, 4),
(2227, NULL, 1, 2021, 'e608cbf22650f54d59a9158363bf08cb.pdf', NULL, 'Bombillo no enciende.', '2022-06-16 ', 'No registra', NULL, NULL, NULL, 'Se realiza limpieza interna y externa y se realiza cambio de condensadores y cableado en la parte del satélite, dada la presencia de sulfatación. Equipo queda en optimas condiciones de funcionamiento', '317', '2022-06-16 ', 'no', NULL, 15, 4),
