(2247, NULL, 1, 974, 'aa23768cd7e368d1bc5f4b0223a5e545.pdf', NULL, 'Se reporta mensaje en pantalla \"error fatal y falla de linea\"', '2022-10-18 08:00', '', NULL, NULL, NULL, 'Revisión del registro de eventos.\r\nSe encuetra falla en la base de datos y error de comunicación con la red.\r\nSe toma el MAC Address del equipo para reservar la dirección IP a través de IT.\r\nSe borra y restablece base de datos.\r\nFuncionamiento del equipo normal.', 'SIN CODIGO', '2022-10-21 ', 'no', NULL, 15, 7),
(2248, NULL, 1, 974, 'e17087b2ef31a3d1390269ad71f3630d.pdf', NULL, 'PROA Connection issues - System has limi\r\n|Connection issues - System has limited connectivity (e.g. no\r\n| SW transfers, issues with PROA tickets, etc.). SKB0121963', '2022-04-22 14:20', 'No registra', NULL, NULL, NULL, 'Se ingresa SRS via Acceso Total, se borra, System Management desde Agent Control y se vuelve a instalar\r\nEvent Management Agent, Running; SD-Asset- Management Agent, Running\r\nFuncionamiento normal ', 'SIN CODIGO', '2022-04-22 ', 'no', NULL, 15, 7),
(2249, NULL, 1, 337, 'fa96e3e1921032ae3d970695632d60c1.pdf', NULL, 'El equipo no pasa la prueba de uniformidad y de respuesta de energia del detector 1, se evidencia mala calidad en la imagen', '2022-09-22 ', 'No registra', NULL, NULL, NULL, 'SE REALIZÓ LA INSTALACIÓN DE LA NUEVA FUENTE DE ALTA TENSIÓN EN EL DETECTOR 1.\r\nSE REALIZARO LOS SIGUIENTES AJUSTES:\r\nITER CAL.\r\nZ ENERGY GAIN CAL.\r\nENERGY MAP CREATION\r\nUNIFORMITY MAP CREATION\r\nTODOS LOS AJUSTES SE REALIZARON EN LOS DOS DETECTORES.', 'wo-09689746', '2022-12-16 15:27', 'no', '', 15, 7),
(2261, NULL, 1, 6273, '2c1ddb2d8e8e038674d659595e92358b.pdf', NULL, 'Pantallas auxiliares no encienden', '2022-12-19 06:00', 'No registra', NULL, NULL, NULL, 'Se realiza ajuste de cables de conexión de las pantallas auxiliares.\r\nSe explica a la ingeniera Angelica elmprocedimiento adecuado para habilitar su funcionamiento, luego de una desconexion\r\nabrupta.\r\nEquipos quedan en correctas condiciones físicas y de funcionamiento.', '05622', '2022-12-22 09:00', 'no', NULL, 15, 5),
(2264, NULL, 1, 694, '6da3e96d1769283cc635db8b09fdee82.pdf', NULL, 'el monitor de signos vitales no esta recibiendo carga', '2023-01-26 ', '3273', NULL, NULL, NULL, 'se atiende llamado, se evidencia cable de poder dañado, se realiza cambio de cable de poder, el equipo funciona correctamente', '3273', '2023-01-26 ', 'no', NULL, 15, 4),
(2265, NULL, 1, 738, '2f54b69ca2a4d465bb8ee6cecdb98110.pdf', NULL, 'favor revisar brazalete no censa cubiculo 6', '2023-01-26 ', '17653', NULL, NULL, NULL, 'se atiende llamado, se revisa brazalete, se comprueba fuga de brazalete, se realiza cambio de brazalete se comprueba correcto funcionamiento, se deja en el servicio en optimas condiciones', '17653', '2023-01-27 ', 'no', NULL, 15, 4),
(2250, NULL, 1, 6951, '4567d112a80da0ede4a04e3fd940406b.pdf', NULL, 'LOS INGENIEROS DE SALA DE OPERACIONES REPORTAN QUE LOS VALORES DE FUGA OBTENIDOS ALCANZAN LOS VALORES LIMITES. POR LO QUE SE SOLICITA REVISION', '2022-10-24 ', 'NO REGISTRA', NULL, NULL, NULL, 'se realiza revision de casette y se encuentra residuos de cal, estos residuos\r\nocasionan fugas se procede a realizar limpieza y se verifica buen funcionamiento, se recomienda cambiar con frecuencia los filtros del canister\r\nya que de esta manera se evita que los residuos vayan al equipo. el equipo es operativo.', 'OTT - 17017', '2022-10-27 ', 'no', NULL, 15, 7),
(2251, NULL, 1, 6190, 'ec3a8479f6d12ab7fb23c643d26963d0.pdf', NULL, 'LOS INGENIEROS DE SALA DE OPERACIONES REPORTAN FUGA QUE ALNCANZA LOS VALORES MAXIMOS PERMITIRODS, POR LO QUE SE SOLICITA REVISION', '2022-10-24 ', 'NO REGISTRA', NULL, NULL, NULL, 'se hacen pruebas de funcionamiento, se corren test de fugas, se observa buen desempeño del equipo, se\r\nrecomienda cambiar regularmente los filtros del canister, para evitar la ocurrencia de fugas en el circuito, el equipo es Operativo.', 'OTT - 17018', '2022-10-27 ', 'no', NULL, 15, 7),
(2253, NULL, 1, 2959, '2e291fd629df75ed83398f40d32f9dbb.pdf', NULL, 'Se reporta ruido en la mesa al realizar los movimientos.', '2022-10-26 ', 'No registra', NULL, NULL, NULL, 'Se realiza la instalación del Control Device, verificación de funcionamiento ok.', 'SIN CODIGO', '2022-10-28 ', 'no', NULL, 15, 0),
(2254, NULL, 1, 5648, NULL, NULL, 'La banda nuevamente quede fuera de servicio, el mantenimiento correctivo realizado por el ingeniero de G-Barco, en donde atravesaba un tornillo para acoplarse con el motor de la banda de igual no tubo los resultados esperados, por lo tanto el equipo queda fuera de servicio, a la espera que la empresa traiga e instale el repuesto por garantía.', '2022-08-22 ', 'NO REGISTRA', NULL, NULL, NULL, 'SE INSTALA MOTOR DE ELEVACIÓN MSI 220V BANDA DE ESFUERZO P/N DC2097829-089, SE REALIZA CALIBRACIÓN DE ALTURA CON\r\nGRADOS DE INCLINACIÓN POR SERVICE APPLICATION - APROBADA, PRUEBAS DE FUNCIONAMIENTO APROBADAS.\r\nSE REALIZA CAMBIO DE CABLE SERIAL POR CABLE DE CONEXIÓN USB QUE SE ENCONTRABA DAÑADO.\r\nOPERACIÓN DEL EQUIPO EN MODO PACIENTE SIMULADO EN CORRECTO FUNCIONAMIENTO.\r\nEQUIPO EN SERVICIO.', 'OTT - 7263', '2022-11-09 ', 'no', '', 15, 7),
(2255, NULL, 1, 355, NULL, NULL, 'Equipo requiere mantenimiento correctivo', '2022-11-10 ', 'NO REGISTRA', NULL, NULL, NULL, 'Equipo dado de baja, se relaciona documento de baja de equipos', '1731', '2023-03-24 ', 'no', '', 15, 6),
(2256, NULL, 1, 373, NULL, NULL, 'Equipo fuera de servicio se envía a sysmed para mantenimiento correctivo', '2022-11-10 ', 'NO REGISTRA', NULL, NULL, NULL, 'SE REALIZA MANTENIMIENTO CORRECTIVO POR PARTE DE LOS INGENIEROS BIOMEDICOS DEL HOSPITAL CON EL TICKET 2564, sE REALIZA CORRECCIÓN: Se atiende llamado, se revisa equipo, se evidencia daño en el seguro de las ventanas y ventanas, se realiza cambio de estas partes, se comprueba el correcto funcionamiento del equipo. equipo funciona correctamente, se deja en el servicio en optimas condiciones', '2564', '2023-03-13 16:21', 'no', '', 15, 4),
