(2266, NULL, 1, 215, '165446eb0fa3d7dd5d427b92cbcb56b0.pdf', NULL, 'Conector de resistencia a desfibrilador no conecta', '2021-02-02 ', '0000', NULL, NULL, NULL, 'Reparación de conector de palas en el equipo, \r\npin del contector de la resistencia de prueba \r\nquedó dentro, lo que no dejaba conectar las \r\npalas.\r\n', '1398', '2021-06-03 ', 'no', NULL, 15, 0),
