(2393, NULL, 1, 8818, NULL, NULL, 'Se realiza reporte de bomba de infusión en el servicio de Urgencias críticos debido a que pinza queda mal insertada en el puerto de infusión, impidiendo así su funcionamiento. ', '2025-02-28 ', '2665', NULL, NULL, NULL, 'Se retira pinza del equipo, se realizan pruebas de funcionamiento, se devuelve el equipo nuevamente al servicio de manera funcional.', '2665', '2025-02-28 ', 'no', NULL, 15, 3),
(2394, NULL, 1, 8360, 'f46eb940d30719fadd92cbce96de4f2b.pdf', NULL, 'Se procede al desmonte del tubo de rayos x Modelo 2216450, SN: 246030GT, todo ok.\r\nSe realiza la instalación del tubo (ULYSSES Green TUBE UNIT ANGIO. PN: D2801A), todo ok.\r\nSe realizan calibraciones de:\r\nX220, Pass\r\nBad pixel, Pass\r\nPixel gain, Pass.\r\nConversion Factor, Pass.\r\nmR/mAs, Pass.\r\nFluoro Tapers, Pass\r\n3D calibration, Pass.\r\nSe realiza Image Quality Check, Pass.\r\nSe realizan pruebas de funcionamiento e imagen, todo ok', '2025-05-31 ', '14741727', NULL, NULL, NULL, 'Se procede al desmonte del tubo de rayos x Modelo 2216450, SN: 246030GT, todo ok.\r\nSe realiza la instalación del tubo (ULYSSES Green TUBE UNIT ANGIO. PN: D2801A), todo ok.\r\nSe realizan calibraciones de:\r\nX220, Pass\r\nBad pixel, Pass\r\nPixel gain, Pass.\r\nConversion Factor, Pass.\r\nmR/mAs, Pass.\r\nFluoro Tapers, Pass\r\n3D calibration, Pass.\r\nSe realiza Image Quality Check, Pass.\r\nSe realizan pruebas de funcionamiento e imagen, todo ok', '14741727', '2025-05-31 ', 'no', NULL, 15, 0),
(2395, NULL, 1, 8781, NULL, NULL, 'NO FUNCIONA EL PULSIOXIMETRO.', '2025-08-03 ', '2153', NULL, NULL, NULL, 'Se realizan diferentes pruebas de funcionamiento del equipo y no se evidencia el error  mencionado.', '2153', '2025-08-03 ', 'no', '', 15, 7),
