(2411, NULL, 1, 4293, 'dbff092c9c69ba876cdd06f2244fd2ce.pdf', NULL, 'Equipo de telemetría no funciona', '2025-04-28 ', '443652', NULL, NULL, NULL, 'Se realiza verificacion del equipo de telemetria del tanque de oxigeno MP2= c04010315. El cableado del equipo se encuentra en buen estado, se envuelve con cinta aislante el cable pero el panel solar no esta recibiendo sol ya que alrededor del tanque pusieron unos paneles aislantes de cerramiento y no permite recibir el sol al panel solar. Se deja el equipo sin funcionamiento y se reprograma visita para dejar en funcionamiento del equipo con corriente directa.', '443652', '2025-04-28 ', 'no', NULL, 15, NULL),
(2412, NULL, 1, 8783, NULL, NULL, 'el equipo cuenta con el brazalete desgastado ', '2025-05-09 ', '2691', NULL, NULL, NULL, 'se realiza cambio de brazalete ', '2691', '2025-05-09 ', 'no', '', 15, 4),
