(2422, NULL, 1, 5727, '4240dd997db8d6002e27b7e53664aa21.pdf', NULL, 'Caída de presión de la red de Oxigeno del hospital', '2024-06-07 ', '439605', NULL, NULL, NULL, 'Se realiza verificación de las presiones en la unidad de urgencias pediátricas y se encontró en 52 PSI, también en Salud Mental con una presión de 49 PSI. Se verifico las unidades de doble regulación realizando limpieza de los filtros en Y, se ventearon los reguladores encontrando bastantes residuos. Se calibraron los reguladores a 65 PSI. Se evidencio que una de las unidades de doble regulación no tiene maya filtro en el cheque en Y', '439605', '2024-06-07 ', 'no', NULL, 15, NULL),
(2423, NULL, 1, 5729, 'f68d0becbcedb630f45d153b45539c14.pdf', NULL, 'Caída de presión de la red de oxigeno de la institución', '2024-06-07 ', '439605', NULL, NULL, NULL, 'Se realiza verificación de las presiones en la unidad de urgencias pediátricas y se encontró en 52 PSI, también en Salud Mental con una presión de 49 PSI. Se verifico las unidades de doble regulación realizando limpieza de los filtros en Y, se ventearon los reguladores encontrando bastantes residuos. Se calibraron los reguladores a 65 PSI. Se evidencio que una de las unidades de doble regulación no tiene maya filtro en el cheque en Y', '439605', '2024-06-07 ', 'no', NULL, 15, NULL),
(2424, NULL, 1, 5728, 'ec2c1c614a0eb60e429f189a99218c0d.pdf', NULL, 'Caída de presión de la red de oxigeno de la institución', '2024-06-07 ', '439605', NULL, NULL, NULL, 'Se realiza verificación de las presiones en la unidad de urgencias pediátricas y se encontró en 52 PSI, también en Salud Mental con una presión de 49 PSI. Se verifico las unidades de doble regulación realizando limpieza de los filtros en Y, se ventearon los reguladores encontrando bastantes residuos. Se calibraron los reguladores a 65 PSI. Se evidencio que una de las unidades de doble regulación no tiene maya filtro en el cheque en Y', '439605', '2024-06-07 ', 'no', NULL, 15, NULL),
(2425, NULL, 1, 5726, '1f633670fe228d4218c4c7976030c2a8.pdf', NULL, 'Caída de presión de la red de oxigeno de la institución', '2024-06-07 ', '439605', NULL, NULL, NULL, 'Se realiza verificación de las presiones en la unidad de urgencias pediátricas y se encontró en 52 PSI, también en Salud Mental con una presión de 49 PSI. Se verifico las unidades de doble regulación realizando limpieza de los filtros en Y, se ventearon los reguladores encontrando bastantes residuos. Se calibraron los reguladores a 65 PSI. Se evidencio que una de las unidades de doble regulación no tiene maya filtro en el cheque en Y', '439605', '2024-06-07 ', 'no', NULL, 15, NULL),
(2426, NULL, 1, 5727, 'abb51ce9c41a4ab6fff40da93e1c993a.pdf', NULL, 'Llamado de emergencia por caída de presión de la red de oxigeno del hospital el fin de semana', '2024-06-10 ', '411370', NULL, NULL, NULL, 'Se realiza verificación de la presión en las unidades de doble regulación, se estabiliza y se hace seguimiento y control durante 3 horas permaneciendo estable.\r\n', '441370', '2024-06-10 ', 'no', NULL, 15, NULL),
