(2428, NULL, 1, 5728, 'b35818e0b66e88a199844dbf30bf63ee.pdf', NULL, 'Llamado de emergencia por caída de presión de la red de oxigeno del hospital el fin de semana', '2024-06-10 ', '441370', NULL, NULL, NULL, 'Se realiza verificación de la presión en las unidades de doble regulación, se estabiliza y se hace seguimiento y control durante 3 horas permaneciendo estable.', '441370', '2024-06-10 ', 'no', '', 15, NULL),
(2429, NULL, 1, 5726, '54fad78f31ca64e66f8bd6e7ea081fbe.pdf', NULL, 'Llamado de emergencia por caída de presión de la red de oxigeno del hospital el fin de semana', '2024-06-10 ', '441370', NULL, NULL, NULL, 'Se realiza verificación de la presión en las unidades de doble regulación, se estabiliza y se hace seguimiento y control durante 3 horas permaneciendo estable.', '441370', '2024-06-10 ', 'no', NULL, 15, NULL),
(2430, NULL, 1, 5727, '0d2df76da3629219cabca0f8b02cfeef.pdf', NULL, 'Caída de presión de oxígeno medicinal de la red del hospital', '2024-06-11 ', '441372', NULL, NULL, NULL, 'Verificación de presion de unidades de regulación doble 70 psi desde la noche 10/06/2024 encontrandose estable al igual se encuentra personal de tenicrio lo cual habia reportado la anomalia el dia viernes 07/06/2024. Los reguladores presentan paso y uno no regula lo cual no da capacidad para el caudal que requiere la clinica.', '441372', '2024-06-11 ', 'no', NULL, 15, NULL),
(2431, NULL, 1, 5729, '1fd28430ce36226a0b8388fcdc0f97c2.pdf', NULL, 'Caída de presión de oxígeno medicinal de la red del hospital', '2024-06-11 ', '441372', NULL, NULL, NULL, 'Verificación de presión de unidades de regulación doble 70 psi desde la noche 10/06/2024 encontrándose estable al igual se encuentra personal de tenicrio lo cual había reportado la anomalía el día viernes 07/06/2024. Los reguladores presentan paso y uno no regula lo cual no da capacidad para el caudal que requiere la clínica.', '441372', '2024-06-11 ', 'no', NULL, 15, NULL),
(2432, NULL, 1, 5728, '37c792c8cacf96171d3f61ec5f4b895e.pdf', NULL, 'Caída de presión de oxígeno medicinal de la red del hospital', '2024-06-11 ', '441372', NULL, NULL, NULL, 'Verificación de presión de unidades de regulación doble 70 psi desde la noche 10/06/2024 encontrándose estable al igual se encuentra personal de tenicrio lo cual había reportado la anomalía el día viernes 07/06/2024. Los reguladores presentan paso y uno no regula lo cual no da capacidad para el caudal que requiere la clínica.', '441372', '2024-06-11 ', 'no', NULL, 15, NULL),
(2433, NULL, 1, 5726, '4d45255e85de0ad4bd6becc711f633fa.pdf', NULL, 'Caída de presión de oxígeno medicinal de la red del hospital', '2024-06-11 ', '441372', NULL, NULL, NULL, 'Verificación de presión de unidades de regulación doble 70 psi desde la noche 10/06/2024 encontrándose estable al igual se encuentra personal de tenicrio lo cual había reportado la anomalía el día viernes 07/06/2024. Los reguladores presentan paso y uno no regula lo cual no da capacidad para el caudal que requiere la clínica.', '441372', ' ', 'no', NULL, 15, NULL),
(2434, NULL, 1, 5727, '6d81fc5708d06ec6d06b0746780d90c2.pdf', NULL, 'Nuevamente caída de presión en la red de oxígeno, se necesita revisión y/o cambio de la unidad de doble regulación', '2024-06-11 ', '439606', NULL, NULL, NULL, 'Se realiza verificación de sistema de unidad de doble regulación, al momento inicial las presiones están estables, el cliente reporta caída de presión en áreas como partos encendiendo las alarmas. Se realizan pruebas a todos los reguladores y se establece las presiones iguales en 75 PSI estática y 58 PSI Dinámica. El área de urgencias que el punto más cercano registra de 4 a 5 PSI más que el área más legaja que es partos al registrar 55 PSI. \r\nRegulador superior del a unidad de regulación #1 tiene paso en la presión', '439606', '2024-06-11 ', 'no', NULL, 15, NULL),
(2435, NULL, 1, 5729, 'cadbfd3d4da91149c1be87b4b8dcb68d.pdf', NULL, 'Nuevamente caída de presión en la red de oxígeno, se necesita revisión y/o cambio de la unidad de doble regulación', '2024-06-11 ', '439606', NULL, NULL, NULL, 'Se realiza verificación de sistema de unidad de doble regulación, al momento inicial las presiones están estables, el cliente reporta caída de presión en áreas como partos encendiendo las alarmas. Se realizan pruebas a todos los reguladores y se establece las presiones iguales en 75 PSI estática y 58 PSI Dinámica. El área de urgencias que el punto más cercano registra de 4 a 5 PSI más que el área más legaja que es partos al registrar 55 PSI. ', '439606', '2024-06-11 ', 'no', NULL, 15, NULL),
(2436, NULL, 1, 5727, '276fb6f8caa54d47f9eb25617872edd0.pdf', NULL, 'Se presenta nuevamente caída de presión en la red de oxígeno', '2024-09-20 ', '439980', NULL, NULL, NULL, 'Se realiza visita técnica para revisión unidades de regulación por caída de presión.\r\nEl cliente manifiesta conocimiento del problema por unidades regulación desactualizadas reguladores son de flujo bajo\r\nCliente solicita levantamiento de información para realizar una parada suministro O2 por remodelación de central de gases\r\nSe inspecciona buitrón para verificar red O2 para instalación de suministro alterno O2 en la red O2\r\nSe requiere la alimentación por thermos designados por messer para la labor.\r\nSe recomienda instalar thermos por fase liquida se requiere suministrar gasificador para dicha conexión.\r\n', '439980', '2024-09-20 ', 'no', NULL, 15, NULL),
(2437, NULL, 1, 5729, '40fa629d868edb0335e60285e71e1413.pdf', NULL, 'Se presenta nuevamente caída de presión en la red de oxígeno', '2024-09-20 ', '439980', NULL, NULL, NULL, 'Se realiza visita técnica para revisión unidades de regulación por caída de presión.\r\nEl cliente manifiesta conocimiento del problema por unidades regulación desactualizadas reguladores son de flujo bajo\r\nCliente solicita levantamiento de información para realizar una parada suministro O2 por remodelación de central de gases\r\nSe inspecciona buitrón para verificar red O2 para instalación de suministro alterno O2 en la red O2\r\nSe requiere la alimentación por thermos designados por messer para la labor.\r\nSe recomienda instalar thermos por fase liquida se requiere suministrar gasificador para dicha conexión.', '439980', '2024-09-20 ', 'no', NULL, 15, NULL),
(2438, NULL, 1, 5728, '5596d03b7d72cf330de2b77ef6868988.pdf', NULL, 'Se presenta nuevamente caída de presión en la red de oxígeno', '2024-09-20 ', '439980', NULL, NULL, NULL, 'Se realiza visita técnica para revisión unidades de regulación por caída de presión.\r\nEl cliente manifiesta conocimiento del problema por unidades regulación desactualizadas reguladores son de flujo bajo\r\nCliente solicita levantamiento de información para realizar una parada suministro O2 por remodelación de central de gases\r\nSe inspecciona buitrón para verificar red O2 para instalación de suministro alterno O2 en la red O2\r\nSe requiere la alimentación por thermos designados por messer para la labor.\r\nSe recomienda instalar thermos por fase liquida se requiere suministrar gasificador para dicha conexión', '439980', '2024-09-20 ', 'no', NULL, 15, NULL),
(2439, NULL, 1, 5726, 'abfbe0539312e4bd12e1334d2e265167.pdf', NULL, 'Se presenta nuevamente caída de presión en la red de oxígeno', '2024-09-20 ', '439980', NULL, NULL, NULL, '\r\nSe realiza visita técnica para revisión unidades de regulación por caída de presión.\r\nEl cliente manifiesta conocimiento del problema por unidades regulación desactualizadas reguladores son de flujo bajo\r\nCliente solicita levantamiento de información para realizar una parada suministro O2 por remodelación de central de gases\r\nSe inspecciona buitrón para verificar red O2 para instalación de suministro alterno O2 en la red O2\r\nSe requiere la alimentación por thermos designados por messer para la labor.\r\nSe recomienda instalar thermos por fase liquida se requiere suministrar gasificador para dicha conexión.', '439980', '2024-09-20 ', 'no', NULL, 15, NULL),
(2440, NULL, 1, 8936, NULL, NULL, 'el equipo imprime vibrado y no muestra la V2 larga ', '2025-05-22 ', '2751', NULL, NULL, NULL, 'se realiza limpieza de electrodos en el equipo y se realiza ajuste de configuración y filtros, por ultimo se entrega el equipo en optimas condiciones de funcionamiento al servicio de hospitalización 1 ', '2751', '2025-05-22 ', 'no', '', 15, 7),
