(2464, NULL, 1, 6273, '1a2ec7479a9ccee426d1fc9e5b3a194b.pdf', NULL, 'Se reporta telefónicamente por la jefe Liliana García que el equipo no da rayo, y se debe reiniciar para que funcione.', '2025-06-13 16:00', '', NULL, NULL, NULL, 'Se realiza actualización de Hotfixes a la version 45.\r\nSe realiza actualización de driver de tarjeta de red I219-LM a la version 12.19.\r\nSe hará seguimiento al correcto funcionamiento del la conexión de las tarjetas de red del equipo.\r\nEn caso de repetirse la falla, reiniciar solo la estación de trabajo (NX), cerrando correctamente la sesión de usuario e informar\r\ndel evento a servicio.', '13683', '2025-06-16 ', 'no', NULL, 15, 7),
(2465, NULL, 1, 8805, NULL, NULL, 'Llamado del servicio por pinza de equipo de bomba de infusión insertada en el equipo. ', '2025-06-13 ', '2771', NULL, NULL, NULL, 'Se realiza retiro de pinza, se realizan pruebas de funci0namiento y se entrega equipo operativo al servicio. ', '2771', '2025-06-13 ', 'no', NULL, 15, 5),
