(2508, NULL, 1, 9553, '4551d03dae5d1ef0c60a77bdb51ce7c5.pdf', NULL, '', ' ', 'boton de apagado de consola falla', NULL, NULL, NULL, 'Se realiza verificación inicial de funcionamiento de todos los botones de la consola, se evidencia que el botón de apagado no funciona, se realiza\r\napertura de consola para verificación de conexiones, se evidencia que el flex de conexión se encuentra haciendo un mal contacto, se realiza\r\najuste de flex, se realizan pruebas de funcionamiento finales, exitosas', 'AA56598', '2025-07-25 ', 'no', NULL, 15, 7),
(2509, NULL, 1, 8808, NULL, NULL, 'bomba de infusión con puerto de carga disfuncional.', '2025-07-24 ', '2859', NULL, NULL, NULL, 'se realiza revisión del cable de poder y posteriormente pruebas de funcionamiento en el equipo, se realiza carga del equipo evidenciando que la batería funciona con normalidad posteriormente se entrega el equipo funcional al servicio y se le recomienda al personal percatarse del indicador de carga cuando se conecta el equipo a la red eléctrica', '2859', '2025-07-24 ', 'no', NULL, 15, 3),
(2510, NULL, 1, 9777, NULL, NULL, 'Se realiza llamado a garantia al proveedor medtronic debido a falla presentada en el equipo en pantalla con número de error #340', '2025-01-15 ', '303955901', NULL, NULL, NULL, 'CORRECTIVE#WARRANTY CLIENTE REPORTA ERROR 340 EN EQUIPO NUEVO. SE\r\nREALIZA CONEXION A PLATAFORMA Y VERIFICACION DE LOGS DE ERRORES, SE\r\nENCUENTRA REGION DESCONFIGURADA. SE REALIZA INTENTO DE CONFIGURACION DE\r\nLA MISMA, SIN EMBARGO NO FUE POSIBLE REALIZAR LA CONEXION AL VLEX. SE\r\nSOLICITA MOVIMIENTO DEL EQUIPO PARA ENVIARLO A LABORATORIO Y REALIZAR REPARACIÓN', '403390635', '2025-01-28 ', 'no', NULL, 15, 7),
(2511, NULL, 1, 9775, NULL, NULL, 'Se realiza reporte a modo de comodato al proveedor medtronic, en donde se reporta falla en el cabezal de cámara. ', '2025-01-05 ', '303972611', NULL, NULL, NULL, 'CORRECTIVE#FIXED ASSET CLIENTE REPORTA QUE CABEZAL NO ES RECONOCIDO POR\r\nPROCESADORA. LIMPIEZA EXTRNA, NINGUN HALLAZGO DE FLUIDOS NI SANGRE. SE\r\nREALIZA REVISION GENERAL Y SE REQUIERE ACTUALIZACION DE PROCESADORA. SE\r\nREALIZAR ACTUALIZACION DE LA MISMA. EQUIPO QUEDA FUNCIONAL.', '403410206', '2025-01-05 ', 'no', NULL, 15, 7),
