INSERT INTO `correctivos_generales` (`id`, `created_at`, `status`, `equipo_id`, `file`, `file_orden`, `orden`, `fecha_inicio`, `code_orden`, `diagnostico`, `code_diagnostico`, `fecha_diagnostico`, `description`, `code`, `fecha_mantenimiento`, `repuesto_pendiente`, `repuesto_id`, `cierre_id`, `tipo_falla_id`) VALUES
(2513, NULL, 1, 8831, NULL, NULL, 'bomba de infusión con falla en puerto de carga ', '2025-07-28 ', '2861', NULL, NULL, NULL, 'se realiza inspección visual del equipo evidenciando que no cuenta con daños físicos se procede a poner a cargar el equipo  y posteriormente se realizan pruebas de funcionamiento identificando que la bomba enciende con normalidad y funciona correctamente. se recomienda en el servicio identificar el testigo de conexión a la red eléctrica cuando se conecten a cargar los equipos debido a que algunos tomas se encuentran. defectuosos.', '2861', '2025-07-28 ', 'no', '', 15, 3),
(2514, NULL, 1, 529, NULL, NULL, 'Se reporta desvió de spot de luz de campo coaxial.', '2025-07-10 ', 'C-3764', NULL, NULL, NULL, 'Se realiza desarme de rosca objetivo con hombre solo de cadena y desarme de carcasa inferior de sistema de iluminación mecánica. Se denota espejo desviado de forma vertical en el plano visual quirúrgico, se realiza ajuste de espejo. Se realiza prueba, luz de spot centrado. Luz de punto negro no se ajusta debido a desgaste de engranaje interno. Se entrega equipo funcional.', 'C-3764', '2025-07-10 ', 'no', NULL, 15, 3),
(2515, NULL, 1, 9010, NULL, NULL, 'Electrocardiógrafo no funcional ', '2025-07-31 ', '2863', NULL, NULL, NULL, 'se realizan pruebas de funcionamiento en el equipo identificando que funciona con normalidad, se realiza toma de ECG en varios pacientes en los cuales el medico de turno expresa que el equipo funciona con normalidad, se entrega el equipo funcional al servicio..', '2863', '2025-07-31 ', 'no', '', 15, NULL),
(2516, NULL, 1, 5577, NULL, NULL, 'Equipo se bloquea intermitentemente durante su uso', '2025-07-29 ', '25828', NULL, NULL, NULL, 'Se realiza reinstalación y actualización de software para borrar los archivos temporales en el software ya que el equipo presenta bloqueos intermitentes. Se realizan pruebas de funcionamiento y equipo opera correctamente', '25828', '2025-07-29 ', 'no', NULL, 15, 7),
(2517, NULL, 1, 2959, NULL, NULL, 'Fallo en conexion entre el gantry y la estacion', '2025-07-25 ', '480100704805', NULL, NULL, NULL, 'Se realiza cambio de colimador (TCO), por errores CT_COA_E_180 y CT_COA_E_4013, lo cual no permitía que el gantry llegara a standby. Se destapa se retira antiguo colimador, y se realiza instalación de nuevo. Se realizan pruebas pertinentes en FRU Replacement, y prueba general, los anteriores con resultados satisfactorios.', '480100704805', '2025-07-25 ', 'no', NULL, 15, 0),
(2518, NULL, 1, 7851, NULL, NULL, 'CAMBIO DE COMPRESOR DE 5 TON MARCA DANFOSS Y CONTROL DE TEMPERATURA UNIVERSAL', '2025-08-06 ', '0000', NULL, NULL, NULL, 'SE CAMBIO DE COMPRESOR DE 5 TON MARCA DANFOSS Y CONTROL DE TEMPERATURA UNIVERSAL TRABAJO REALIZADO POR AMARO POSSO Y DIEGO RODRIGUEZ', '000', '2025-08-08 ', 'no', '', 15, NULL),
