(2551, NULL, 1, 4255, NULL, NULL, 'REPORTE CORRECTIVO', '2025-09-06 ', '3648404', NULL, NULL, NULL, '', '3648404', '2025-09-06 ', 'no', NULL, 14, NULL),
(2555, NULL, 1, 4238, 'c48c8cb309b23e209d561fdbcc5c958f.pdf', NULL, 'Cambio de resistencia esterilizador de calor humedo BMT', '2025-09-18 ', '15270', NULL, NULL, NULL, 'Se realizó mantenimiento correctivo: instalación de resistencia. Se lleva a cabo el\r\nretiro del tapón colocado en el generador, la instalación de la nueva resistencia y\r\nla revisión de la presurización del equipo. No se evidencian fugas durante la prueba.', '15270', '2025-09-22 ', 'no', '', 15, NULL),
(2556, NULL, 1, 4238, 'b782bc380f03b4897f35862a831673ab.pdf', NULL, 'Cambio de codo de Silicona de 90 grados a esterilizador de calor humedo BMT por rotura del mismo', '2025-09-24 ', '15291', NULL, NULL, NULL, 'Se realizó mantenimiento correctivo: cambio de codo en silicona a 90°, debido a\r\nfractura en la anterior. Se realiza el desmonte del codo antiguo, la instalación del\r\nnuevo, ajuste y sellado. Se llevan a cabo pruebas de funcionamiento del equipo, sin\r\ncarga y con carga.\r\n', '15291', '2025-09-30 ', 'no', '', 15, NULL),
(2558, NULL, 1, 4242, '10bac5967d5f6b91404c2791bf663aae.pdf', NULL, 'Cambio de cinco resistencias, valvula de alivio y contactor a esterilizador de calor humedo BMT por daño en estos componetes', '2025-09-16 ', '15280', NULL, NULL, NULL, 'Se realizó mantenimiento correctivo: cambio de resistencias del generador de vapor,\r\ndesmonte y limpieza del generador de vapor y sus correspondientes tuberías, instalación\r\nde válvula de alivio e instalación de contactor. Se lleva a cabo la revisión del\r\nfuncionamiento correcto del equipo posteriormente a las medidas correctivas tomadas.', '15280', '2025-09-29 ', 'no', '', 15, NULL),
(2559, NULL, 1, 3475, 'f366eb0cfe8460fab9695379b2f0b9cb.pdf', NULL, 'SE REPORTA EQUIPO DEBIDO A INTERMITENCIA DE LA LUZ', '2025-09-30 ', 'C00569', NULL, NULL, NULL, 'SE ATIENDE LLAMADO, EQUIPO ES REPORTADO POR INTERMITENCIA EN LA LUZ, NO SE EVIDENCIA DAÑO FISICO, SE REALIZA REPARACIÓN, EN EL PUNTO DE CONEXION DEL CABEZAL; FINALMENTE SE REALIZAN PRUEBAS DE FUNCIONAMIENTO DEL EQUIPO EN GENERAL Y ESTE RESPONDE DE MANERA CORRECTA. SE RECOMIENDA UTILIZAR EL EQUIPO DE MANERA CUIDADOSA, PARA PROLONGAR SU VIDA UTIL. SE ENTREGA EQUIPO FUNCIONAL.', 'C00569', '2025-10-01 ', 'no', NULL, 15, 5),
(2560, NULL, 1, 5930, 'f0bd0400bedd98ceab84d39173ef3fda.pdf', NULL, 'SE REALIZA REPORTE POR INTERMITENCIA DE LA LUZ', '2025-09-30 ', 'C00568', NULL, NULL, NULL, 'SE ATIENDE LLAMADO, EQUIPO ES REPORTADO POR INTERMITENCIA EN LA LUZ, NO SE EVIDENCIA DAÑO FISICO, SE REALIZA REPARACIÓN, EN EL PUNTO DE CONEXION DEL CABEZAL; FINALMENTE SE REALIZAN PRUEBAS DE FUNCIONAMIENTO DEL EQUIPO EN GENERAL Y ESTE RESPONDE DE MANERA CORRECTA. SE RECOMIENDA UTILIZAR EL EQUIPO DE MANERA CUIDADOSA, PARA PROLONGAR SU VIDA UTIL. SE ENTREGA EQUIPO FUNCIONAL.', 'C00568', '2025-10-01 ', 'no', NULL, 15, 5),
(2561, NULL, 1, 9672, 'fcc0cd8ca7477b3a4c86941c9e7ce6ab.pdf', NULL, 'Fallo en modo fatburn, se reinicia el tiempo que lleva ejecutado el paciente', '2025-02-26 ', '6574', NULL, NULL, NULL, 'Personal reporta inconvenientes con el modo fatburn y desprendimiento de tapa de codos de articulaciones, Se realiza verificación de funcionamiento con fabrica, se realizan dos visitas para inspección por fabrica, se realiza manipulación de tablero y ajuste, se informa a personal sobre correcto uso en modos fatburn y cardio ya que equipo requiere monitorizar constantemente la fc. Se entrega equipo completo y funcional', '6574', '2025-02-26 ', 'no', NULL, 15, 5),
(2562, NULL, 1, 9280, 'f5d84def82666edba6de0518c714f4fe.pdf', NULL, 'Fallo interferencia en estudios de potenciales evocados auditivos. No permite realizar procedimientos', '2025-03-12 ', '8531', NULL, NULL, NULL, 'Se realizan test y se evidencia fallo en el canal EP, 3 canales fuera de los limites de tolerancia. Se evidencia demasiado ruido e interferencia en los estudios E.P. Es necesario del envio del equipo al departamento de ingenieria A&B para revision y diagnostico a fondo. Adicionalmente se recomienda conexion del equipo en tomas regulado grado medico o conexion por medio de UPS online', '8531', '2025-03-12 ', 'no', NULL, 15, 7),
(2563, NULL, 1, 9675, '8d137473f8e26a6f6ab5c97d82a1c5bd.pdf', NULL, 'Se presenta fallo en la perilla de freno', '2025-04-24 ', '5407', NULL, NULL, NULL, 'Se evidencia ausencia de tope en perilla de freno, se realiza correccion del pasador y se entrega equipo. ', '5407', '2025-04-24 ', 'no', NULL, 15, 0),
(2564, NULL, 1, 9281, '74eb70ee4eaa5d2273aa96dd32238675.pdf', NULL, 'Se requiere soporte para ingreso de firmas de doctores en la plantilla', '2025-07-09 ', '8325', NULL, NULL, NULL, 'Se realiza agregan firmas de doctores en plantillas de reportes y se realizan pruebas de funcionamiento con paciente en protocolos AEP en contultorio 5', '8325', '2025-07-09 ', 'no', NULL, 15, 7),
