(2574, NULL, 1, 1047, '2460e5ff1c865782c31863f777a2798b.pdf', NULL, ' MENSAJE DE FALLO EN PRUEBA DE BATERIA DURANTE ATG.', '2025-11-22 ', 'WO-00351517', NULL, NULL, NULL, 'LIMPIEZA EXTERNA, NINGUN HALLAZGO DE FLUIDOS NISANGRE. SE REALIZA VERIFICACIONES DE VOLTAJES EN BATERIA Y CIRCUITO DE CARGA, SE ENCUENTRA PROBLEMA DE LECTURA DEL CIRCUITO DE CARGA. SE REALIZA VERIFICACION DE CABLEADO INTERNO DEL CIRCUIT CHARGE Y SE RECTIFICAN LAS CONEXIONES. SE REALIZAN PRUEBAS DE FUNCIONAMIENTO GENERALES Y EL EQUIPO QUEDA HABILITADO.\r\n', 'WO-00351517', '2025-11-22 ', 'no', NULL, 15, 4),
(2575, NULL, 1, 1027, NULL, NULL, ' INTERFERENCIA EN PANTALLA SUPERIOR.', '2025-09-24 ', '403755126', NULL, NULL, NULL, 'LIMPIEZA EXTERNA NINGUN HALLAZGO DE FLUIDOS NI SANGRE. SE REALIZA VERIFICACION DE PANTALLA SUPERIOR SIN ENCONTRAR ALTERACION. SE REALIZA VERIFICACION DE CONEXIONES DE TARJETA GUI. SE CORRIJE FALLA Y EL EQUIPO QUEDA HABILITADO\r\n', '403755126', '2025-09-25 ', 'no', NULL, 15, 4),
(2577, NULL, 1, 9115, NULL, NULL, 'Equipo emite alarma de fallo de resistencia.', '2025-11-10 ', 'ST-025-0724', NULL, NULL, NULL, ' Se realiza envío de resistencia por garantia, personal de ingenieria biomédica de la instalación realiza la instalación del repuesto siguiendo indicaciones de fábrica, Se reliazan pruebas funcionales y operativas, mostrando estas normalidad en su funcionamiento,', 'ST-025-0724', '2025-11-10 ', 'no', '', 15, 0),
(2578, NULL, 1, 529, 'bf6779dde9ae9c2d8d145693ec0372c9.pdf', NULL, 'Se presenta movimiento de tubo coobservador. ', '2025-12-02 ', 'C4185', NULL, NULL, NULL, 'Se realiza revisión a equipo debido a que el cliente reporta movimientos inadecuados en el tubo coobservador y mala visualización.\r\nSe realiza revisión general evidenciando las siguientes novedades:\r\n- Fuerte golpe en tubo coobservador y oculares de 10x en equipo. \r\n- Diplopia en tubo binocular 180°.\r\nSe realiza ajuste a tubo coobervador, mejorando la visualizacion y sus movimientos. Se le informa al Ingeniero del area que el ajuste realizado\r\nes momentaneo debido al fuerte golpe el equipo al moverlo pierde su ajuste. Se realizan pruebas de funcionamiento.Se entrega equipo en buen funcionamiento.', 'C4185', '2025-12-03 ', 'no', '', 15, 3),
(2579, NULL, 1, 6941, NULL, NULL, 'La goma superior de la puerta de la centrifuga está rota.', '2025-12-17 ', 'WO-00567993', NULL, NULL, NULL, 'Se realiza cambio de las gomas superiores de la centrifuga.', '', '2025-12-17 ', 'no', '', 15, 4),
(2580, NULL, 1, 10061, NULL, NULL, 'Equipo en mal funcionamiento', '2024-12-26 ', '51568924', NULL, NULL, NULL, 'Se realiza instalacion de sello de puerta al autoclave, se corrigen fugas en magueras. Se realzian pruebas con carga y se deja en correcto funcionamiento', '51568924', '2024-12-26 ', 'no', NULL, 15, NULL),
(2581, NULL, 1, 10061, NULL, NULL, 'Llamado emergente por problemas de atascamiento de la puerta durante su apertura y cierre.', '2025-07-11 ', 'S1578424', NULL, NULL, NULL, 'Se atiende llamado emergente por problemas de atascamiento de la puerta durante su apertura y cierre. Se revisa el estado del sistema de la puerta y sus componentes. Se lleva a cabo la lubricación del sello de puerta; se realizan pruebas de apertura y cierre, así como ciclo de prueba. No se evidencia más atascamiento de la puerta.', 'S1578424', '2025-07-11 ', 'no', NULL, 15, NULL),
(2582, NULL, 1, 10061, NULL, NULL, 'Llamado emergente debido a bloqueo en la puerta de carga del equipo', '2025-09-25 ', 'S1578424', NULL, NULL, NULL, 'Se atiende llamado emergente por mal funcionamiento de la puerta. Se revisa el sistema de desplazamiento de la puerta y sus componentes. Se realiza la lubricación de los sellos de puerta, ajuste de los racores del sistema intercambiador de calor y ajuste de las tuberías.\r\nSe llevan a cabo ciclos de prueba para comprobar el correcto funcionamiento del equipo, así como la correcta apertura y cierre del sistema de puertas.', 'S1578424', '2025-09-25 ', 'no', NULL, 15, NULL),
(2583, NULL, 1, 10061, NULL, NULL, 'Llamado emergente debido a problemas en el funcionamiento de la puerta.', '2025-10-09 ', '15313', NULL, NULL, NULL, 'Se atiende llamado emergente por mal funcionamiento de la puerta. Se revisa el sistema de desplazamiento de la puerta y sus componentes. Se identifica error en uno de los sensores de puerta; se realiza el correspondiente cambio de sensor (S11) así como la revisión del estado y funcionamiento del otro sensor de puerta (S11.1).\r\nSe llevan a cabo pruebas de funcionamiento de la puerta, así como ciclos de prueba y de esterilización, los cuales aprueban sin novedades, tanto en el proceso de esterilización como en el correcto desplazamiento de la puerta.', '15313', '2025-10-09 ', 'no', '', 15, NULL),
(2584, NULL, 1, 10061, NULL, NULL, 'Llamado por falla en cierre de puerta', '2025-10-16 ', 'S1578424', NULL, NULL, NULL, '.', 'S1578424', '2025-10-16 ', 'no', NULL, 15, NULL),
(2585, NULL, 1, 10061, NULL, NULL, 'Problemas con el cierre de la puerta', '2025-12-04 ', 'S-D', NULL, NULL, NULL, 'Se reemplaza fusible quemado, se tenso la cadena de la puerta, se corrigieron fugas en bomba de agua de sistema de osmosis, sin mas novedades equipo queda operativo', 'S-D', '2025-12-04 ', 'no', NULL, 15, NULL),
(2586, NULL, 1, 10061, NULL, NULL, 'Equipo con niveles de acceso bloqueados', '2025-12-26 ', 'MV1600225', NULL, NULL, NULL, 'Se deja equipo con el nivel de servicio hasta que haya soporte tecnico por parte de fabrica', 'MV1600225', '2025-12-26 ', 'no', NULL, 15, NULL),
(2587, NULL, 1, 10061, NULL, NULL, 'Equipo bloquaedo a los niveles de acceso', '2025-12-30 ', 'S1578424', NULL, NULL, NULL, 'Se restablecen las credenciales del usuario administrativo y del usuario operativo, se modifico la caducidad de las credenciales a un año, aumento el numero de intentos de ingresar a 6 y se realizo una copia de seguridad de los usuario.\r\n\r\nAdmin: usuario: admin\r\n             contraseña: Biomedico#1\r\n\r\nOperativo: usuario: huvcartg\r\n                   contraseña: Cartago#1', 'S1578424', '2025-12-30 ', 'no', NULL, 15, NULL),
