(2589, NULL, 1, 10099, NULL, NULL, 'el equipo se encuentra con el  slide clamp  dañado ', '2025-12-01 ', '02658818', NULL, NULL, NULL, 'se realiza cambio de side clamp, se realizan pruebas de liberación de manera satisfactoria ', '02658818', '2025-12-01 ', 'no', '', 15, 3),
