(2591, NULL, 1, 8808, NULL, NULL, 'Se reporta que el equipo no funciona ', '2025-12-01 ', '02658807', NULL, NULL, NULL, 'Se realiza cambio de switch level, se realizan\r\npruebas de liberación de manera satisfactoria', '02658807', '2025-12-01 ', 'no', '', 15, 2),
(2592, NULL, 1, 5393, NULL, NULL, 'CLIENTE REPORTA RUPTURA DE RESORTE', '2026-01-22 ', 'WO-00361900', NULL, NULL, NULL, 'LIMPIEZA EXTERNA, NINGUN HALLAZGO DE FLUIDOS NI SANGRE. SE REALIZA\r\nREEMPLAZO DEL RESORTE. SE REALIZAN PRUEBAS DE AJUSTE MECANICO EN PUERTO Y PRUEBAS DE CALIDAD DE IMAGEN.\r\nEQUIPO HABILITADO', 'WO-00361900', '2026-01-22 ', 'no', '', 15, 2),
(2593, NULL, 1, 2959, '7ee50d74c6dc0135e8b1b6af09bcb0bb.pdf', NULL, 'Equipo sigue presentando fallo no permite realizar estudios, alcanza stand by', '2026-01-29 ', '480100731644-1', NULL, NULL, NULL, 'Continuando con el servicio, y posterior a la instalación mecánica de los siguientes componentes: Brushblock HP, P/N 11115538, S/N S11689. Tubo ATHLON XT, P/N 11253400, S/N 608052371. HVT, P/N 1115450, S/N 9722. Se procede con la configuración y calibración correspondiente del tomógrafo, Se realizan verificaciones de conexión en los componentes del gantry. Con apoyo del cliente, se ejecutan pruebas operando la UPS en modo bypass. Posteriormente, la UPS se restablece a modo en línea. Tras estas acciones, se completa de manera satisfactoria la calibración del equipo con el tubo y los demás componentes nuevos instalados. Recomendaciones técnicas: Realizar un estudio de calidad de energía del suministro eléctrico que alimenta el tomógrafo, considerando que el equipo se encuentra configurado para 400 Vac, con el fin de garantizar estabilidad y prevenir fallas asociadas a la red eléctrica. Mantener la sala en condiciones ambientales óptimas, ya que durante la visita se evidencia una humedad relativa aproximada del 80%, nivel que puede generar inestabilidad y mal funcionamiento en componentes electrónicos y de alta tensión.\r\nIncrementar las medidas de cuidado y limpieza del equipo, dado que se observa presencia de medio de contraste en carcasas y en la mesa del paciente. Esta condición puede derivar en contaminación de componentes, fallas prematuras y aparición de artefactos en la imagen. El equipo queda operativo, con  ecomendaciones emitidas para preservar su estabilidad y desempeño a largo plazo. por ahora el equipo queda operativo', '480100731644', '2026-02-24 ', 'no', '', 15, 0),
(2594, NULL, 1, 9869, NULL, NULL, 'Se revisa cableado y configuraciones del servidor, sin encontrar fallas. En el equipo, se configuran nuevamente los parametros\r\nde red del equipo, se hacen pruebas y este vuelve a tener conexión estable con el servidor. Se comprueba que se transmitan los\r\nprocedimientos pendientes.', '2026-01-02 ', 'WO-00574107', NULL, NULL, NULL, 'Se revisa cableado y configuraciones del servidor, sin encontrar fallas. En el equipo, se configuran nuevamente los parametros\r\nde red del equipo, se hacen pruebas y este vuelve a tener conexión estable con el servidor. Se comprueba que se transmitan los\r\nprocedimientos pendientes.', 'WO-00574107', '2026-01-04 ', 'no', NULL, 14, 0),
(2595, NULL, 1, 6942, NULL, NULL, 'Se realiza el cambio de la tarjeta de RF y el ajuste correspondiente del tiempo de sellado. Se hacen pruebas exitosas de sellado\r\ny se libera el equipo para uso seguro.', '2026-01-16 ', 'WO-00580368', NULL, NULL, NULL, '', 'WO-00580368', '2026-01-16 ', 'no', NULL, 14, 0),
(2596, NULL, 1, 6941, NULL, NULL, 'Al revisar el equipo, se detecta que al estar la puerta bloqueada y al intentar abrir la puerta de la centrifuga, uno de los sensores\r\ndetecta que está abierta la puerta y genera la alarma. Se realiza el ajuste del sensor correspondiente con el fin de disminuir la\r\nsensibilidad y no se genere un falso positivo de está alarma.', '2025-12-31 ', 'WO-00573907', NULL, NULL, NULL, 'Al revisar el equipo, se detecta que al estar la puerta bloqueada y al intentar abrir la puerta de la centrifuga, uno de los sensores\r\ndetecta que está abierta la puerta y genera la alarma. Se realiza el ajuste del sensor correspondiente con el fin de disminuir la\r\nsensibilidad y no se genere un falso positivo de está alarma.', 'WO-00573907', '2026-01-04 ', 'no', '', 15, 0),
(2597, NULL, 1, 9998, NULL, NULL, 'se realiza revisión del equipo el cual no alcanza temperaturas programadas ', '2026-02-07 ', 'ito-2530', NULL, NULL, NULL, 'se realiza reemplazo de elementos eléctricos específicamente del kit  de arranque del compresor debido a fallas presentadas en su funcionamiento ', 'ito-2530', '2026-02-07 ', 'no', '', 15, 4),
(2598, NULL, 1, 8419, 'a0cb13612b6d8108bfcf7229797151de.pdf', NULL, 'El acrilico de la cabina presenta fisuras en el interior en varias zonas, no se ha presentado ningun golpe o derrame de liquidos sobre este. Se solicita visita por garantia con el proveedor GBARCO', '2026-02-20 ', 'OTT - 52187', NULL, NULL, NULL, 'SE REVISA CONDICION GENERAL DEL EQUIPO. SE EVIDENCIA QUE EN DIFERENTES PUNTOS ALREDEDOR DE TODO EL ACRILICO QUE CONFORMA LA CABINA HAY FRACTURAS Y/O GRIETAS, QUE PUEDEN COMPROMETER LA INTEGRIDAD DEL MISMO. NO HAY SIGNOS DE MALA MANIPULACION O GOLPES INTENCIONADOS.\r\nEL EQUIPO PASA CORRECTAMENTE LA CALIBRACION Y MEDICION DE VOLUMENES. EL EQUIPO ES APTO PARA SU USO', 'OTT - 52187', '2026-02-23 ', 'no', NULL, 15, 7);
